import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  HrmColumnManager, HrmSegmented, HrmSwitch,
  HrmColumnDef, HrmColumnGroup, HrmDataType,
} from 'hrm-ui';
import {
  TablerIconComponent, IconTable, IconFileText, IconChevronDown, IconChevronUp, IconSparkles,
} from '@tabler/icons-angular';
import { EC_COL_GROUPS, EC_FORMAT_LABEL, EcCol, EcFormat, ExportCenterStore } from './_export-data';

/** Kiểu cột tiếng Việt của EcCol → HrmDataType của column-manager (CM cần type chuẩn để chọn icon). */
const TYPE_MAP: Record<string, HrmDataType> = {
  'văn bản': 'text', 'danh mục': 'text', 'trạng thái': 'status', 'ngày': 'date', 'số': 'number',
};

/** 3 định dạng của tab Bảng dữ liệu — mô tả use-case để chọn không phải đoán (mockup màn 04). */
const FMT_OPTS: { value: EcFormat; desc: string }[] = [
  { value: 'xlsx', desc: 'Phù hợp để xem, lọc và chỉnh sửa' },
  { value: 'csv', desc: 'Phù hợp để import vào hệ thống khác' },
  { value: 'pdf', desc: 'Phù hợp để chia sẻ và in ấn' },
];

/** ═════════ EC CANVAS — TAB BẢNG DỮ LIỆU (mockup màn 01/04/07) ═════════
 *  3 panel dọc: Phạm vi → Cột xuất → Định dạng. Chỉ đọc/ghi ExportCenterStore
 *  (host page provide) — dirty-chip, dock, CTA tự phản ứng qua computed của store. */
@Component({
  selector: 'ec-canvas-table',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule, HrmColumnManager, HrmSegmented, HrmSwitch, TablerIconComponent],
  template: `
    <!-- Skeleton 3 panel khi hydrate (contract §5) — flag ngắn hạn trong store -->
    @if (store.hydrating()) {
      @for (i of [1, 2, 3]; track i) {
        <section class="panel">
          <div class="panel-h"><span class="sk sk-t"></span></div>
          <div class="panel-b">
            <div class="sk sk-l w80"></div>
            <div class="sk sk-l w60"></div>
            <div class="sk sk-l w40"></div>
          </div>
        </section>
      }
    } @else {
    <!-- ═══ PANEL 1 · PHẠM VI LẤY DỮ LIỆU ═══ -->
    <!-- ai-on: AI vừa đặt phạm vi → viền primary nhắc "đây là thứ AI điền" (highlight, có Hoàn tác ở dock) -->
    <section class="panel" [class.ai-on]="store.aiTouched().has('scope')">
      <div class="panel-h">
        <span class="ph-t">Phạm vi lấy dữ liệu</span>
        @if (store.aiTouched().has('scope')) {
          <span class="ai-tag"><tabler-icon [icon]="icSparkle" [size]="11" />AI</span>
        }
        <span class="ph-r ph-note"><b class="num strong">{{ num(store.totalFilter) }}</b>&nbsp;nhân viên theo bộ lọc hiện tại</span>
      </div>
      <div class="panel-b">
        <div class="scope">
          <!-- radio-card: cả thẻ là vùng bấm — đích to hơn radio trần -->
          <button type="button" class="rc" [class.on]="store.scope() === 'all'" (click)="store.scope.set('all')">
            <span class="rdo"></span> Tất cả <b class="num">{{ num(store.totalAll) }}</b>
          </button>
          <button type="button" class="rc" [class.on]="store.scope() === 'filter'" (click)="store.scope.set('filter')">
            <span class="rdo"></span> Theo bộ lọc <b class="num">{{ num(store.totalFilter) }}</b>
          </button>
          <!-- disabled CÓ lý do (spec §5) — không ẩn để user khỏi tưởng lỗi -->
          <button type="button" class="rc dis" disabled>
            <span class="rdo"></span> Đã chọn <b class="num">{{ num(store.totalSelected) }}</b>
          </button>
        </div>
        <div class="hint-dis">Chưa chọn dòng nào ở bảng — quay lại danh sách và tick chọn.</div>
        <div class="chips">
          <span class="lb">Thừa kế bộ lọc đang áp:</span>
          @for (c of store.filterChips; track c.k) {
            <span class="tag">{{ c.k }}: <b>{{ c.v }}</b></span>
          }
        </div>
      </div>
    </section>

    <!-- ═══ PANEL 2 · CỘT XUẤT ═══ -->
    <section class="panel" [class.ai-on]="store.aiTouched().has('cols')">
      <div class="panel-h">
        <span class="ph-t">Cột xuất</span>
        @if (store.aiTouched().has('cols')) {
          <span class="ai-tag"><tabler-icon [icon]="icSparkle" [size]="11" />AI</span>
        }
        <span class="ph-r">
          <hrm-segmented size="sm" [options]="colModeOpts"
            [ngModel]="store.colMode()" (ngModelChange)="setColMode($event)" />
        </span>
      </div>
      @if (store.colMode() === 'mau') {
        <!-- Theo mẫu: 1 dòng mô tả bộ cột — đủ xác nhận, không chiếm chỗ (mockup màn 07) -->
        <div class="panel-b mau-desc">
          @if (mauTen()) {
            Dùng mẫu <b class="strong">{{ mauTen() }}</b> —
          } @else {
            Bộ cột hiện tại —
          }
          <b class="num strong">{{ store.visibleColCount() }}</b> cột: {{ visibleTitles() }}.
        </div>
      } @else {
        <!-- Tùy chỉnh: nhúng hrm-column-manager (tái dùng DS — scorecard "chi phí build = 0") -->
        <div class="cm-wrap">
          <hrm-column-manager
            [columns]="cmColumns()" (columnsChange)="onCmColumns($event)"
            [(groups)]="cmGroups"
            [colsShownLabel]="'cột · kéo để đổi thứ tự'"
            [showAllLabel]="'Chọn hết'" [hideAllLabel]="'Bỏ hết'" />
        </div>
      }
      <!-- Feature B — gợi ý cột AI: chip cột đang ẩn đáng thêm (thâm niên/liên hệ/định danh).
           Hiện ở MỌI colMode; bấm chip tự bật 'Tùy chỉnh' rồi hiện cột đó. -->
      @if (store.aiSuggestCols().length) {
        <div class="ai-sugg">
          <span class="ai-sugg-lb"><tabler-icon [icon]="icSparkle" [size]="12" />Gợi ý của AI</span>
          <div class="ai-sugg-chips">
            @for (c of store.aiSuggestCols(); track c.key) {
              <button type="button" class="ai-chip" (click)="addSuggestCol(c.key)">
                <tabler-icon [icon]="icSparkle" [size]="12" />
                <span class="ai-chip-t">{{ c.title }}</span>
                <span class="ai-chip-r">· {{ c.reason }}</span>
              </button>
            }
          </div>
        </div>
      }
    </section>

    <!-- ═══ PANEL 3 · ĐỊNH DẠNG ═══ -->
    <section class="panel" [class.ai-on]="store.aiTouched().has('format')">
      <div class="panel-h">
        <span class="ph-t">Định dạng</span>
        @if (store.aiTouched().has('format')) {
          <span class="ai-tag"><tabler-icon [icon]="icSparkle" [size]="11" />AI</span>
        }
      </div>
      <div class="panel-b">
        <!-- Trigger select: format hiện tại + mô tả use-case -->
        <button type="button" class="fmt-sel" [class.open]="fmtOpen()" (click)="fmtOpen.set(!fmtOpen())">
          <span class="fmt-ic" [class.pdf]="store.format() === 'pdf'" [class.csv]="store.format() === 'csv'">
            <tabler-icon [icon]="store.format() === 'xlsx' ? icTable : icFile" [size]="15" />
          </span>
          <span class="fmt-m">
            <span class="fmt-t">{{ curLabel() }}</span>
            <span class="fmt-s">{{ curDesc() }}</span>
          </span>
          <tabler-icon class="fmt-cv" [icon]="fmtOpen() ? icUp : icDown" [size]="15" />
        </button>
        <!-- Dropdown mở INLINE nối liền dưới trigger (mockup màn 04 — không popover, không đổi lớp) -->
        @if (fmtOpen()) {
          <div class="fmt-drop">
            @for (o of otherFmts(); track o.value) {
              <button type="button" class="fmt-opt" (click)="pickFormat(o.value)">
                <span class="fmt-ic" [class.pdf]="o.value === 'pdf'" [class.csv]="o.value === 'csv'">
                  <tabler-icon [icon]="o.value === 'xlsx' ? icTable : icFile" [size]="15" />
                </span>
                <span class="fmt-m">
                  <span class="fmt-t">{{ label(o.value) }}</span>
                  <span class="fmt-s">{{ o.desc }}</span>
                </span>
              </button>
            }
          </div>
        }

        <!-- PDF config: progressive disclosure inline ngay dưới — chỉ khi format = PDF (T2) -->
        @if (store.format() === 'pdf') {
          <div class="pdfcfg">
            <div class="pdf-row">
              <div class="pdf-f">
                <div class="pdf-l">Khổ giấy</div>
                <div class="kho">
                  <button type="button" class="pdf-sel" (click)="khoOpen.set(!khoOpen())">
                    {{ store.pdfCfg().kho }}
                    <tabler-icon [icon]="khoOpen() ? icUp : icDown" [size]="13" />
                  </button>
                  @if (khoOpen()) {
                    <div class="kho-drop">
                      @for (k of khoOpts; track k) {
                        <button type="button" class="kho-opt" [class.on]="store.pdfCfg().kho === k" (click)="setKho(k)">{{ k }}</button>
                      }
                    </div>
                  }
                </div>
              </div>
              <div class="pdf-f">
                <div class="pdf-l">Hướng giấy</div>
                <div class="fseg">
                  <button type="button" class="m" [class.on]="store.pdfCfg().huong === 'doc'" (click)="setHuong('doc')">Dọc</button>
                  <button type="button" class="m" [class.on]="store.pdfCfg().huong === 'ngang'" (click)="setHuong('ngang')">Ngang</button>
                </div>
              </div>
            </div>
            <div class="tgl-row">
              <span>Hiển thị tiêu đề báo cáo</span>
              <hrm-switch size="sm" [ngModel]="store.pdfCfg().tieuDe" (ngModelChange)="setPdfFlag('tieuDe', $event)" />
            </div>
            <div class="tgl-row">
              <span>Hiển thị bộ lọc đã áp</span>
              <hrm-switch size="sm" [ngModel]="store.pdfCfg().boLoc" (ngModelChange)="setPdfFlag('boLoc', $event)" />
            </div>
            <div class="tgl-row">
              <span>Hiển thị ngày xuất</span>
              <hrm-switch size="sm" [ngModel]="store.pdfCfg().ngayXuat" (ngModelChange)="setPdfFlag('ngayXuat', $event)" />
            </div>
          </div>
        }
      </div>
    </section>

    <!-- backdrop đóng dropdown khi bấm ra ngoài (không chặn scroll canvas) -->
    @if (fmtOpen() || khoOpen()) {
      <div class="ec-backdrop" (click)="closeDrops()"></div>
    }
    }
  `,
  styles: [`
:host { display: flex; flex-direction: column; gap: var(--space-3); min-width: 0; }
.num { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.strong { color: var(--text-strong); }

/* ── Panel chung (pattern hrm-list-page — khớp mockup) ── */
.panel { background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-lg); position: relative; }
.panel-h { display: flex; align-items: center; gap: 10px; padding: 11px 14px; border-bottom: 1px solid var(--border-soft); }
.ph-t { font-size: var(--fs-11); letter-spacing: .8px; text-transform: uppercase; font-weight: var(--font-semibold); color: var(--text-sub); }
.ph-r { margin-left: auto; display: flex; align-items: center; gap: var(--space-2); }
.ph-note { font-size: var(--fs-11); color: var(--text-sub); }
.panel-b { padding: 13px 14px; }

/* ── Highlight "AI đã đặt" (accent = --primary-*, KHÔNG amber) ── */
/* Viền primary nhắc field do AI điền — an toàn: chỉ điền, dock giữ nút Hoàn tác. */
.panel.ai-on { box-shadow: inset 0 0 0 1px var(--primary-border); }
/* Tag ✨ AI tái dùng ở cả 3 panel — nền primary-subtle, chữ primary-base. */
.ai-tag { display: inline-flex; align-items: center; gap: 3px; font-size: var(--fs-11); font-weight: var(--font-medium);
  padding: 2px 8px 2px 6px; border-radius: var(--radius-full); background: var(--primary-bg-subtle); color: var(--primary-base); line-height: 1.4; }
.ai-tag tabler-icon { color: var(--primary-base); flex: none; }

/* ── Feature B — hàng gợi ý cột AI (chip dashed = "thêm vào") ── */
.ai-sugg { border-top: 1px solid var(--border-soft); padding: 11px 14px; display: flex; flex-direction: column; gap: 8px; }
.ai-sugg-lb { display: inline-flex; align-items: center; gap: 5px; font-size: var(--fs-11); font-weight: var(--font-medium); color: var(--primary-base); }
.ai-sugg-lb tabler-icon { color: var(--primary-base); flex: none; }
.ai-sugg-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.ai-chip { display: inline-flex; align-items: center; gap: 5px; padding: 5px 11px; border-radius: var(--radius-full);
  border: 1px dashed var(--primary-border); background: var(--primary-bg-subtle); color: var(--primary-base);
  font-family: inherit; font-size: var(--fs-12); }
.ai-chip:hover { background: var(--primary-bg-soft); }
.ai-chip tabler-icon { color: var(--primary-base); flex: none; }
.ai-chip-t { font-weight: var(--font-medium); }
.ai-chip-r { font-size: var(--fs-11); opacity: .8; }

/* ── Phạm vi: 3 radio-card ── */
.scope { display: flex; gap: 10px; }
.rc { flex: 1; border: 1px solid var(--border-sub); border-radius: var(--radius-md); padding: 10px 12px;
  display: flex; align-items: center; gap: 9px; font-size: var(--fs-13); color: var(--text-body);
  background: var(--bg-surface); font-family: inherit; text-align: left; }
.rdo { width: 15px; height: 15px; border-radius: var(--radius-full); border: 1.5px solid var(--border-strong);
  flex: none; position: relative; background: var(--bg-surface); }
.rc.on { border-color: var(--primary-base); background: var(--primary-bg-subtle); color: var(--text-strong); font-weight: var(--font-medium); }
.rc.on .rdo { border-color: var(--primary-base); }
.rc.on .rdo::after { content: ''; position: absolute; inset: 3px; border-radius: var(--radius-full); background: var(--primary-base); }
.rc.dis { color: var(--text-disabled); background: var(--bg-surface-subtle); cursor: not-allowed; }
.rc.dis .rdo { border-color: var(--border-sub); background: var(--bg-surface-subtle); }
.rc b { margin-left: auto; font-weight: var(--font-semibold); font-size: var(--fs-13); }
.rc.dis b { color: var(--text-disabled); }
.hint-dis { font-size: var(--fs-11); color: var(--text-soft); margin-top: 7px; padding-left: 2px; }
.chips { display: flex; align-items: center; gap: 6px; margin-top: 11px; flex-wrap: wrap; }
.chips .lb { font-size: var(--fs-11); color: var(--text-sub); }
.tag { font-size: var(--fs-11); padding: 3px 9px; border-radius: var(--radius-sm); background: var(--bg-surface-subtle);
  border: 1px solid var(--border-sub); color: var(--text-body); }
.tag b { font-weight: var(--font-medium); color: var(--text-strong); }

/* ── Cột xuất ── */
.mau-desc { font-size: var(--fs-12); color: var(--text-sub); line-height: 1.6; }
.mau-desc b { font-weight: var(--font-medium); }
/* CM tự có hàng tools + list — chỉ cần đệm quanh, không lồng thêm border */
.cm-wrap { padding: var(--space-1) 14px 10px; }
/* canvas ngoài đã scroll — tránh scroll lồng nhau (CM encapsulation None → cần ng-deep để thắng scope emulated) */
.cm-wrap ::ng-deep .cm-scroll { overflow-y: visible; }

/* ── Định dạng: select + dropdown inline ── */
.fmt-sel { width: 100%; display: flex; align-items: center; gap: 10px; border: 1px solid var(--border-sub);
  border-radius: var(--radius-md); padding: 9px 12px; background: var(--bg-surface); font-family: inherit;
  text-align: left; position: relative; z-index: 2; }
.fmt-sel.open { border-color: var(--primary-border); box-shadow: 0 0 0 2px var(--primary-focus-ring); }
.fmt-ic { width: 30px; height: 30px; border-radius: var(--radius-sm); background: var(--success-bg); color: var(--success-base);
  display: flex; align-items: center; justify-content: center; flex: none; }
.fmt-ic.pdf { background: var(--error-bg); color: var(--error-base); }
.fmt-ic.csv { background: var(--bg-surface-muted); color: var(--text-sub); }
.fmt-m { flex: 1; min-width: 0; display: block; }
.fmt-t { display: block; font-size: var(--fs-13); font-weight: var(--font-medium); color: var(--text-strong); }
.fmt-s { display: block; font-size: var(--fs-11); color: var(--text-sub); }
.fmt-cv { color: var(--text-soft); flex: none; }
.fmt-drop { border: 1px solid var(--border-sub); border-top: none; border-radius: 0 0 var(--radius-md) var(--radius-md);
  margin-top: -2px; background: var(--bg-surface); position: relative; z-index: 2; }
.fmt-opt { width: 100%; display: flex; gap: 10px; padding: 8px 12px; align-items: center; border: none;
  background: transparent; font-family: inherit; text-align: left; }
.fmt-opt + .fmt-opt { border-top: 1px solid var(--border-soft); }
.fmt-opt:hover { background: var(--bg-surface-subtle); }

/* ── PDF config inline ── */
.pdfcfg { margin-top: 10px; border: 1px solid var(--border-soft); border-radius: var(--radius-md);
  background: var(--bg-surface-subtle); padding: 12px; }
.pdf-row { display: flex; align-items: center; gap: var(--space-3); }
.pdf-f { flex: 1; min-width: 0; }
.pdf-l { font-size: var(--fs-11); color: var(--text-sub); margin-bottom: 5px; font-weight: var(--font-medium); }
.kho { position: relative; }
.pdf-sel { width: 100%; height: 32px; border: 1px solid var(--border-sub); border-radius: var(--radius-md);
  background: var(--bg-surface); display: flex; align-items: center; justify-content: space-between;
  padding: 0 10px; font-size: var(--fs-12); color: var(--text-strong); font-family: inherit; }
.pdf-sel tabler-icon { color: var(--text-soft); }
.kho-drop { position: absolute; top: calc(100% + 4px); left: 0; right: 0; z-index: 3;
  background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-md);
  box-shadow: var(--shadow-regular-md); overflow: hidden; }
.kho-opt { width: 100%; border: none; background: transparent; text-align: left; padding: 7px 10px;
  font-size: var(--fs-12); color: var(--text-body); font-family: inherit; }
.kho-opt:hover { background: var(--bg-surface-subtle); }
.kho-opt.on { background: var(--primary-bg-subtle); color: var(--primary-base); font-weight: var(--font-medium); }
.fseg { display: flex; background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-md); padding: 2px; gap: 2px; }
.fseg .m { flex: 1; font-size: var(--fs-11); font-weight: var(--font-medium); color: var(--text-sub); padding: 5px 0;
  text-align: center; border-radius: var(--radius-sm); border: none; background: transparent; font-family: inherit; }
.fseg .m.on { background: var(--primary-base); color: var(--text-on-primary); }
.tgl-row { display: flex; align-items: center; justify-content: space-between; padding: 8px 0 0;
  font-size: var(--fs-12); color: var(--text-body); }

/* backdrop trong suốt — đóng dropdown khi bấm ra ngoài, nằm DƯỚI trigger/drop (z-index 1 < 2) */
.ec-backdrop { position: fixed; inset: 0; z-index: 1; }

/* ── Skeleton hydrate (contract §5) ── */
.sk { background: var(--bg-surface-muted); border-radius: var(--radius-sm); animation: ec-sk .9s ease-in-out infinite alternate; }
.sk-t { display: inline-block; width: 140px; height: 12px; }
.sk-l { height: 12px; margin-top: 10px; }
.sk-l:first-child { margin-top: 0; }
.w80 { width: 80%; } .w60 { width: 60%; } .w40 { width: 40%; }
@keyframes ec-sk { from { opacity: 1; } to { opacity: .4; } }
  `],
})
export class EcCanvasTable {
  readonly store = inject(ExportCenterStore);

  /* icons */
  readonly icTable = IconTable;
  readonly icFile = IconFileText;
  readonly icDown = IconChevronDown;
  readonly icUp = IconChevronUp;
  readonly icSparkle = IconSparkles;

  /** Mini-segmented Theo mẫu / Tùy chỉnh — swap cách hiển thị panel Cột xuất. */
  readonly colModeOpts = [
    { label: 'Theo mẫu', value: 'mau' },
    { label: 'Tùy chỉnh', value: 'tuychinh' },
  ];

  readonly khoOpts = ['A4', 'Letter'];

  /* UI state cục bộ — 2 dropdown của panel Định dạng */
  readonly fmtOpen = signal(false);
  readonly khoOpen = signal(false);

  /** Nhóm cột cho column-manager — bản sao cục bộ (taxonomy cố định, CM có thể đổi thứ tự hiển thị). */
  readonly cmGroups = signal<HrmColumnGroup[]>(EC_COL_GROUPS.map((g) => ({ ...g })));

  /** EcCol (store) → HrmColumnDef (CM): map type tiếng Việt → HrmDataType, group → groupId. */
  readonly cmColumns = computed<HrmColumnDef[]>(() =>
    this.store.cols().map((c) => ({
      key: c.key, title: c.title,
      type: TYPE_MAP[c.type] ?? 'text',
      visible: c.visible, groupId: c.group,
    })),
  );

  /** Tên mẫu nguồn — chỉ hiện khi nguồn là Mẫu (lịch/lịch sử không mang tên mẫu). */
  readonly mauTen = computed(() => {
    const s = this.store.source();
    return s?.kind === 'mau' ? s.ten : '';
  });

  /** Danh sách tên cột đang xuất, nối ' · ' (mockup màn 07). */
  readonly visibleTitles = computed(() =>
    this.store.cols().filter((c) => c.visible).map((c) => c.title).join(' · '),
  );

  readonly curLabel = computed(() => EC_FORMAT_LABEL[this.store.format()]);
  readonly curDesc = computed(() => FMT_OPTS.find((f) => f.value === this.store.format())?.desc ?? '');
  /** Dropdown chỉ liệt kê 2 format CHƯA chọn — trigger đã là format hiện tại. */
  readonly otherFmts = computed(() => FMT_OPTS.filter((f) => f.value !== this.store.format()));

  /** Số đếm kiểu vi-VN (1.248) — khớp mockup. */
  num(n: number): string { return n.toLocaleString('vi-VN'); }

  label(f: EcFormat): string { return EC_FORMAT_LABEL[f]; }

  setColMode(v: string | number | null): void {
    if (v === 'mau' || v === 'tuychinh') this.store.colMode.set(v);
  }

  /** CM đổi (visible / thứ tự) → sync ngược store.cols GIỮ metadata gốc (group/type tiếng Việt) → dirty tự tính. */
  onCmColumns(defs: HrmColumnDef[]): void {
    const cur = this.store.cols();
    const next: EcCol[] = [];
    for (const d of defs) {
      const o = cur.find((c) => c.key === d.key);
      if (o) next.push({ ...o, visible: d.visible !== false });
    }
    // Phòng hờ: cột nào CM làm rớt (không xảy ra bình thường) vẫn giữ lại — không mất cột.
    for (const c of cur) if (!next.some((n) => n.key === c.key)) next.push({ ...c });
    this.store.cols.set(next);
  }

  /** Feature B — bấm chip gợi ý: hiện cột đó. Đang "Theo mẫu" → chuyển "Tùy chỉnh"
   *  (cột thêm lẻ không thuộc mẫu; phải ở Tùy chỉnh mới sửa được bộ cột). Set visible=true, giữ thứ tự. */
  addSuggestCol(key: string): void {
    if (this.store.colMode() === 'mau') this.store.colMode.set('tuychinh');
    this.store.cols.set(this.store.cols().map((c) => (c.key === key ? { ...c, visible: true } : c)));
  }

  pickFormat(f: EcFormat): void {
    this.store.format.set(f);
    this.fmtOpen.set(false);
  }

  setKho(k: string): void {
    this.store.pdfCfg.update((c) => ({ ...c, kho: k }));
    this.khoOpen.set(false);
  }

  setHuong(h: 'doc' | 'ngang'): void {
    this.store.pdfCfg.update((c) => ({ ...c, huong: h }));
  }

  setPdfFlag(key: 'tieuDe' | 'boLoc' | 'ngayXuat', v: boolean | null): void {
    this.store.pdfCfg.update((c) => ({ ...c, [key]: !!v }));
  }

  closeDrops(): void {
    this.fmtOpen.set(false);
    this.khoOpen.set(false);
  }
}
