import { ChangeDetectionStrategy, Component, computed, effect, inject, model } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmButton, HrmResult, HrmSegmented, HrmToastService } from 'hrm-ui';
import {
  TablerIconComponent, IconClock, IconDownload, IconPlayerPlay, IconRefresh,
  IconTable, IconX,
} from '@tabler/icons-angular';
import { EC_FORMAT_LABEL, EcSchedule, ExportCenterStore } from './_export-data';
import { EcRail } from './ec-rail';
import { EcCanvasTable } from './ec-canvas-table';
import { EcCanvasDoc } from './ec-canvas-doc';
import { EcDock } from './ec-dock';
import { EcAiBar } from './ec-ai-bar';

/** ═════════ EXPORT CENTER — MODAL host (design-contract-export-center.md) ═════════
 *  KHÔNG phải page riêng: nhúng vào list-page "Chế độ xem dữ liệu", mở/đóng qua [(open)]
 *  từ chính nút "Xuất dữ liệu" của list-page (exportClick). Bề mặt = MODAL 1200px centered
 *  = "Bàn Xuất Một Mặt Phẳng": ec-rail (tái dùng) · canvas giữa (segmented Bảng/Văn bản +
 *  src-bar + @switch view) · ec-dock (tóm tắt bất biến).
 *  PROVIDE ExportCenterStore TẠI ĐÂY — con ec-* chỉ inject. */
@Component({
  selector: 'sg-feature-export-center',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [ExportCenterStore],
  host: { '(document:keydown.escape)': 'onEsc()' },
  imports: [
    FormsModule, HrmButton, HrmResult, HrmSegmented, TablerIconComponent,
    EcRail, EcCanvasTable, EcCanvasDoc, EcDock, EcAiBar,
  ],
  template: `
    <!-- ═══ MODAL 1200px — Rail · Canvas · Dock (1 mặt phẳng) · mở từ nút "Xuất dữ liệu" của list-page ═══ -->
    @if (open()) {
    <div class="ec-backdrop" (click)="close()"></div>
    <div class="ec-modal" role="dialog" aria-modal="true" aria-label="Xuất dữ liệu">
      <div class="ec-shell">
        <!-- Header custom (tpl-dhead mockup) -->
        <div class="dhead">
          <div class="dh-ic"><tabler-icon [icon]="icDl" [size]="19" /></div>
          <div class="dh-t">
            <h3>Xuất dữ liệu</h3>
            <p>Xuất bảng dữ liệu (Excel/CSV/PDF) hoặc văn bản theo mẫu (WORD/PDF) — mẫu, lịch và lịch sử ở cột trái.</p>
          </div>
          <button type="button" class="dh-x" aria-label="Đóng" (click)="close()">
            <tabler-icon [icon]="icX" [size]="16" />
          </button>
        </div>

        <div class="dbody">
          <ec-rail />

          <div class="canvas">
            <!-- cv-top: segmented swap canvas (rail + dock đứng yên) + src-bar nguồn tường minh -->
            <div class="cv-top">
              <hrm-segmented [options]="segOpts"
                [ngModel]="store.segTab()" (ngModelChange)="setSeg($event)" />
              @if (store.segTab() === 'doc') {
                <div class="src-bar">Đang soạn: <b>{{ store.selectedDoc()?.ten ?? '—' }}</b></div>
              } @else if (store.view() === 'config') {
                <div class="src-bar">
                  @if (store.source(); as s) {
                    @switch (s.kind) {
                      @case ('mau') {
                        <span>Đang dùng mẫu: <b>{{ s.ten }}</b></span>
                        @if (srcIsDefault()) { <span class="pin">★ mặc định</span> }
                      }
                      @case ('lich') {
                        <span>Đang xem lịch: <b>{{ s.ten }}</b></span>
                        <span class="sdot" [class.act]="srcSchedActive()" [class.off]="!srcSchedActive()">
                          {{ srcSchedActive() ? 'hoạt động' : 'tạm dừng' }}</span>
                      }
                      @case ('hist') { <span>Khôi phục từ lịch sử: <b>{{ s.ten }}</b></span> }
                    }
                  } @else {
                    <span>Cấu hình thủ công (chưa dùng mẫu)</span>
                  }
                  <!-- Chip mời lưu (mockup màn 08) — trung tính theo KIND nguồn (hist/null), không đụng dirtyCount -->
                  @if (store.suggestSaveTemplate()) {
                    <span class="savehint">chưa lưu thành mẫu ·
                      <button type="button" (click)="store.saveModalOpen.set(true)">+ Lưu</button></span>
                  }
                  <!-- Dirty-chip chống cry-wolf — chỉ khi lệch nguồn ghim (mockup màn 04) -->
                  @if (store.dirtyCount() > 0) {
                    <span class="dirty">
                      <span class="dot"></span> đã chỉnh <b class="num">{{ store.dirtyCount() }}</b> mục ·
                      <button type="button" (click)="store.saveModalOpen.set(true)">+ Lưu mẫu mới</button>
                    </span>
                  }
                </div>
              }
            </div>

            <div class="cv-scroll">
              @switch (store.view()) {
                @case ('config') {
                  @if (store.segTab() === 'table') { <ec-canvas-table /> } @else { <ec-canvas-doc /> }
                }

                <!-- ─── Màn 12: Export thành công — vòng lặp khép kín (rail dòng 1 = "Vừa xong") ─── -->
                @case ('exportSuccess') {
                  <div class="panel grow">
                    <hrm-result status="success"
                      [title]="'Đã xuất ' + exportRows() + ' dòng'"
                      subtitle='File sẵn sàng tải xuống — đồng thời đã ghi vào Lịch sử xuất (dòng đầu cột trái) để lần sau "Dùng lại".'>
                      <div class="rs-body">
                        <div class="file-chip">
                          <span class="fc-ic"><tabler-icon [icon]="icTable" [size]="15" /></span>
                          <b>{{ store.exportFileName() }}</b>
                          <span class="sz">{{ fileKb() }} KB</span>
                        </div>
                        <div class="res-acts">
                          <hrm-button variant="primary" (click)="downloadFile()">
                            <tabler-icon [icon]="icDl" [size]="14" /> Tải xuống
                          </hrm-button>
                          <!-- "Xuất tiếp" GIỮ cấu hình — không đóng modal đột ngột (mockup màn 12) -->
                          <hrm-button (click)="store.view.set('config')">
                            <tabler-icon [icon]="icRf" [size]="14" /> Xuất tiếp (giữ cấu hình)
                          </hrm-button>
                          <hrm-button (click)="close()">Đóng</hrm-button>
                        </div>
                      </div>
                    </hrm-result>
                  </div>
                }

                <!-- ─── Màn 13: Tạo lịch thành công — trả lời "bao giờ nó chạy?" ─── -->
                @case ('scheduleSuccess') {
                  <div class="panel grow">
                    <hrm-result status="success" title="Đã tạo lịch xuất"
                      subtitle="Hệ thống sẽ tự tạo file và gửi người nhận theo nhịp bên dưới — không cần thao tác thêm.">
                      <div class="rs-body">
                        @if (store.lastSchedule(); as s) {
                          <div class="res-card">
                            <div class="rc-t">{{ s.ten }}</div>
                            <div class="rc-r"><span>Nhịp chạy</span><b>{{ nhipRun(s) }} · <span class="num">{{ s.gio }}</span></b></div>
                            <div class="rc-r"><span>Nội dung</span><b>{{ fmtLabel(s) }} · <span class="num">{{ store.rowCount().toLocaleString('vi-VN') }}</span> nhân viên ({{ scopeLabel() }})</b></div>
                            <div class="rc-r"><span>Người nhận</span><b>{{ s.nguoiNhan.join(' · ') }}</b></div>
                            <div class="rc-r"><span>Lần chạy đầu</span><b class="num">{{ firstRun(s) }}</b></div>
                            <div class="rc-r"><span>Trạng thái</span><b><span class="sdot act">Đang hoạt động</span></b></div>
                          </div>
                          <div class="res-acts">
                            <hrm-button variant="primary" (click)="viewSchedules()">
                              <tabler-icon [icon]="icClock" [size]="14" /> Xem lịch xuất
                            </hrm-button>
                            <!-- "Chạy thử ngay" — xây niềm tin automation từ phút đầu (notebar màn 13) -->
                            <hrm-button (click)="store.runScheduleNow(s.id)">
                              <tabler-icon [icon]="icPlay" [size]="14" /> Chạy thử ngay
                            </hrm-button>
                            <hrm-button (click)="close()">Đóng</hrm-button>
                          </div>
                        }
                      </div>
                    </hrm-result>
                  </div>
                }
              }
            </div>

            <!-- Command bar AI (feature A/C) — GHIM ĐÁY canvas (sau cv-scroll), full width, CHỈ ở màn cấu hình (ẩn khi success) -->
            @if (store.view() === 'config') {
              <div class="ai-mount"><ec-ai-bar /></div>
            }
          </div>

          <ec-dock />
        </div>
      </div>
    </div>
    }
  `,
  styles: [`
:host{display:contents}
.num{font-family:var(--font-mono);font-variant-numeric:tabular-nums}

/* ── Modal overlay: backdrop + card centered (thay hrm-drawer) ── */
.ec-backdrop{position:fixed;inset:0;background:var(--overlay-bg, rgb(14 18 27 / 0.46));z-index:1050}
.ec-modal{position:fixed;inset:0;margin:auto;z-index:1051;
  width:min(1200px, 96vw);height:min(864px, 92vh);
  background:var(--bg-surface);border-radius:var(--radius-3xl);
  box-shadow:var(--shadow-regular-lg);overflow:hidden;
  display:flex;flex-direction:column}
.ec-shell{display:flex;flex-direction:column;height:100%;min-height:0}

/* Header modal custom (tpl-dhead mockup) */
.dhead{display:flex;align-items:flex-start;gap:12px;padding:18px 22px 14px;
  border-bottom:1px solid var(--border-sub);flex:none}
.dh-ic{width:36px;height:36px;border-radius:var(--radius-md);background:var(--primary-bg-subtle);
  color:var(--primary-base);display:flex;align-items:center;justify-content:center;flex:none}
.dh-t{flex:1;min-width:0}
.dh-t h3{font-size:var(--fs-18);font-weight:var(--font-semibold);color:var(--text-strong);margin:0}
.dh-t p{font-size:var(--fs-13);color:var(--text-sub);margin:2px 0 0}
.dh-x{width:30px;height:30px;border:none;background:transparent;color:var(--text-sub);cursor:pointer;
  border-radius:var(--radius-sm);display:flex;align-items:center;justify-content:center;flex:none}
.dh-x:hover{background:var(--bg-surface-subtle)}

/* Thân 3 vùng: rail (268 tự thân) · canvas co giãn · dock (300 tự thân) */
.dbody{flex:1;display:flex;min-height:0}
.canvas{flex:1;min-width:0;display:flex;flex-direction:column;background:var(--bg-app)}
/* Command bar AI ghim ĐÁY canvas (sau cv-scroll): full width, inset 18px khớp cv-top/cv-scroll.
   .canvas flex column + cv-scroll flex:1 cuộn → ai-mount flex:none tự dính đáy; border-top + nền surface tách khối, không đè dock */
/* Bỏ band footer (border-top + nền surface) — chatbot AI nổi thẳng trên canvas; giữ padding chừa shadow. */
.ai-mount{flex:none;padding:var(--space-3) 18px}
.cv-top{display:flex;align-items:center;gap:14px;padding:12px 18px 0;flex:none}
.src-bar{display:flex;align-items:center;gap:var(--space-2);margin-left:auto;font-size:var(--fs-12);
  color:var(--text-sub);white-space:nowrap;min-width:0;overflow:hidden}
.src-bar b{color:var(--text-strong);font-weight:var(--font-medium)}
.src-bar .pin{color:var(--warning-base)}
.cv-scroll{flex:1;overflow-y:auto;padding:14px 18px 18px;display:flex;flex-direction:column;
  gap:12px;min-height:0}

/* Trạng thái lịch trên src-bar — luôn render 2 chiều (AP-01) */
.sdot{display:inline-flex;align-items:center;gap:5px;font-size:var(--fs-11);font-weight:var(--font-medium)}
.sdot::before{content:'';width:7px;height:7px;border-radius:var(--radius-full)}
.sdot.act{color:var(--success-text)}
.sdot.act::before{background:var(--success-base)}
.sdot.off{color:var(--text-soft)}
.sdot.off::before{background:var(--text-soft)}

/* Dirty-chip trong src-bar (mockup màn 04) — amber CHỈ cho cảnh báo (AP-07) */
.dirty{display:inline-flex;align-items:center;gap:5px;font-size:var(--fs-11);font-weight:var(--font-medium);
  background:var(--warning-bg);color:var(--warning-text);border:1px solid var(--warning-border);
  padding:2px 9px;border-radius:var(--radius-full);flex:none}
.dirty .dot{width:6px;height:6px;border-radius:var(--radius-full);background:var(--warning-base)}
.dirty b{font-weight:var(--font-semibold)}
.dirty button{border:none;background:transparent;color:inherit;font-weight:var(--font-semibold);
  font-size:var(--fs-11);text-decoration:underline;cursor:pointer;padding:0}

/* Chip mời lưu — trung tính (amber CHỈ cho cảnh báo, AP-07) */
.savehint{display:inline-flex;align-items:center;gap:4px;font-size:var(--fs-11);font-weight:var(--font-medium);
  color:var(--text-sub);background:var(--bg-surface-subtle);border:1px solid var(--border-sub);
  padding:2px 9px;border-radius:var(--radius-full);flex:none}
.savehint button{border:none;background:transparent;color:var(--primary-base);font-weight:var(--font-semibold);
  font-size:var(--fs-11);cursor:pointer;padding:0}
.savehint button:hover{text-decoration:underline}

/* ── Màn success (12/13): panel chiếm trọn canvas, hrm-result ở giữa ── */
.panel{background:var(--bg-surface);border:1px solid var(--border-sub);border-radius:var(--radius-lg)}
.panel.grow{flex:1;display:flex;align-items:center;justify-content:center;padding:40px 20px}
.rs-body{display:flex;flex-direction:column;align-items:center;gap:var(--space-2)}
.file-chip{display:inline-flex;align-items:center;gap:9px;border:1px solid var(--border-sub);
  border-radius:var(--radius-md);padding:9px 14px;background:var(--bg-surface-subtle);
  font-size:var(--fs-12);color:var(--text-body)}
.file-chip b{font-weight:var(--font-medium);color:var(--text-strong)}
.file-chip .sz{font-family:var(--font-mono);font-size:var(--fs-11);color:var(--text-sub)}
.fc-ic{width:30px;height:30px;border-radius:var(--radius-sm);background:var(--success-bg);
  color:var(--success-base);display:flex;align-items:center;justify-content:center;flex:none}
.res-acts{display:flex;gap:10px;margin-top:14px;flex-wrap:wrap;justify-content:center}
.res-card{border:1px solid var(--border-sub);border-radius:var(--radius-lg);padding:14px 18px;
  margin-top:var(--space-2);text-align:left;min-width:360px;background:var(--bg-surface)}
.res-card .rc-t{font-size:var(--fs-13);font-weight:var(--font-semibold);color:var(--text-strong)}
.res-card .rc-r{display:flex;justify-content:space-between;gap:var(--space-4);font-size:var(--fs-12);
  color:var(--text-sub);margin-top:7px}
.res-card .rc-r b{color:var(--text-strong);font-weight:var(--font-medium);text-align:right}
  `],
})
export class SgFeatureExportCenter {
  protected readonly store = inject(ExportCenterStore);
  private readonly toast = inject(HrmToastService);

  /* Icons (Tabler object mode) */
  protected readonly icDl = IconDownload;
  protected readonly icX = IconX;
  protected readonly icTable = IconTable;
  protected readonly icRf = IconRefresh;
  protected readonly icClock = IconClock;
  protected readonly icPlay = IconPlayerPlay;

  /** Modal mở/đóng — [(open)] two-way với consumer (list-page nút "Xuất dữ liệu"). */
  readonly open = model(false);

  constructor() {
    // Mở modal từ ngoài → luôn khởi về canvas cấu hình (không dựng lại màn success cũ) + re-hydrate mẫu ghim.
    let wasOpen = false;
    effect(() => {
      const o = this.open();
      if (o && !wasOpen) this.prepareOpen();
      wasOpen = o;
    });
  }

  /** Segmented canvas: chỉ hoán đổi canvas — rail và dock đứng yên (hợp đồng §2). */
  protected readonly segOpts = [
    { label: 'Bảng dữ liệu', value: 'table' },
    { label: 'Văn bản theo mẫu', value: 'doc' },
  ];

  /** ★ chỉ khi nguồn là mẫu VÀ đang ghim mặc định (đồng bộ logic dock). */
  protected readonly srcIsDefault = computed(() => {
    const s = this.store.source();
    return s?.kind === 'mau' && !!this.store.templates().find((t) => t.id === s.id)?.macDinh;
  });

  /** Nguồn là lịch → trạng thái sống để render 2 chiều trên src-bar (AP-01). */
  protected readonly srcSchedActive = computed(() => {
    const s = this.store.source();
    if (s?.kind !== 'lich') return false;
    return !!this.store.schedules().find((x) => x.id === s.id)?.active;
  });

  /** Số dòng của LẦN XUẤT vừa rồi (snapshot lastExport — không đổi khi user chỉnh tiếp). */
  protected readonly exportRows = computed(() =>
    (this.store.lastExport()?.soDong ?? 0).toLocaleString('vi-VN'));

  /** Dung lượng file demo — suy ra deterministic từ dòng × cột (26×6 ≈ 128 KB khớp mockup). */
  protected readonly fileKb = computed(() => {
    const h = this.store.lastExport();
    if (!h) return '0';
    return Math.max(8, Math.round(h.soDong * h.colKeys.length * 0.82)).toLocaleString('vi-VN');
  });

  /* ── Modal open/close ── */

  /** Chuẩn bị mỗi lần mở: re-hydrate mẫu ghim ★ (copy UI: "tự nạp mỗi khi mở") —
   *  CHỈ khi không phá dở tay người dùng (dirty = 0) và kịch bản còn mẫu. */
  private prepareOpen(): void {
    // Đầu mỗi lần mở → dọn highlight AI phiên trước (không để kết quả A/C dính dai sang lần mở mới).
    this.store.aiClear();
    if (this.store.scenario() !== 'no-templates' && this.store.dirtyCount() === 0) {
      const t = this.store.templates().find((x) => x.macDinh);
      if (t) this.store.hydrateTemplate(t.id);
    }
    this.store.view.set('config');
  }

  protected close(): void {
    this.open.set(false);
  }

  /** Esc đóng modal (guard theo open để không đụng overlay khác). */
  protected onEsc(): void {
    if (this.open()) this.close();
  }

  protected setSeg(v: string | number | null): void {
    if (v !== 'table' && v !== 'doc') return;
    this.store.segTab.set(v);
    // Đổi tab → dọn highlight AI: kết quả A (bảng) / C (văn bản) của tab cũ không dính sang tab mới.
    this.store.aiClear();
    // Đang đứng ở màn success mà đổi tab → quay về cấu hình (success chỉ có nghĩa ngay sau hành động).
    if (this.store.view() !== 'config') this.store.view.set('config');
  }

  /* ── Success actions ── */

  protected downloadFile(): void {
    this.toast.success('Đang tải xuống', '"' + this.store.exportFileName() + '"');
  }

  /** "Xem lịch xuất": về canvas cấu hình + rail lọc Lịch — lịch mới nằm dòng 1 (recency). */
  protected viewSchedules(): void {
    this.store.railFilter.set('lich');
    this.store.view.set('config');
  }

  /* ── Labels màn 13 ── */

  /** Nhịp chạy kiểu mockup: "Mỗi thứ Hai" / "Hàng ngày" / "Ngày 01 hàng tháng". */
  protected nhipRun(s: EcSchedule): string {
    if (s.tanSuat === 'ngay') return 'Hàng ngày';
    if (s.tanSuat === 'tuan') {
      const thu = s.thu ?? 'Thứ Hai';
      return 'Mỗi ' + thu.charAt(0).toLowerCase() + thu.slice(1); // "Mỗi thứ Hai" (mockup màn 13)
    }
    return 'Ngày ' + String(s.ngayThang ?? 1).padStart(2, '0') + ' hàng tháng';
  }

  /** Lần chạy đầu: "Thứ Hai 25/08/2026 · 08:00" (tuần) — trả lời "bao giờ nó chạy?". */
  protected firstRun(s: EcSchedule): string {
    const prefix = s.tanSuat === 'tuan' ? (s.thu ?? '') + ' ' : '';
    return prefix + s.lanKe + ' · ' + s.gio;
  }

  /** Nhãn phạm vi hiện tại — success card phải khớp scope thật, không hardcode "theo bộ lọc". */
  protected scopeLabel(): string {
    const sc = this.store.scope();
    return sc === 'all' ? 'tất cả' : sc === 'filter' ? 'theo bộ lọc' : 'dòng đã chọn';
  }

  protected fmtLabel(s: EcSchedule): string {
    return EC_FORMAT_LABEL[s.format];
  }
}
