/* ─────────────────────────── Types ─────────────────────────── */

export type EcFormat = 'xlsx' | 'csv' | 'pdf' | 'word';
export type EcScope = 'all' | 'filter' | 'selected';
export type EcRailFilter = 'all' | 'mau' | 'lich' | 'hist';

/** Cột xuất của bảng nhân viên (9 cột · 4 nhóm). */
export interface EcCol { key: string; title: string; group: string; type: string; visible: boolean; }

/** Mẫu xuất bảng đã lưu (Mẫu của tôi). */
export interface EcTemplate { id: string; ten: string; moTa?: string; soCot: number; format: EcFormat; capNhat: string; macDinh?: boolean; colKeys: string[]; }

/** Lịch xuất tự động. */
export interface EcSchedule { id: string; ten: string; tanSuat: 'ngay' | 'tuan' | 'thang'; thu?: string; ngayThang?: number; gio: string; format: EcFormat; nguoiNhan: string[]; active: boolean; templateTen: string; lanKe: string; lanChay: { at: string; soDong: number }[]; }

/** Một lần xuất đã thực hiện (Lịch sử). */
export interface EcHistory { id: string; ten: string; soDong: number; format: EcFormat; at: string; nguoi: string; colKeys: string[]; moi?: boolean; }

/** Mẫu văn bản {{field}} (tab "Văn bản theo mẫu"). */
export interface EcDocTemplate { id: string; ten: string; soTruong: number; format: 'word' | 'pdf'; capNhat: string; body: string; }

/** Item hợp nhất trên rail tái dùng (Mẫu + Lịch + Lịch sử). `active` = lịch đang hoạt động. */
export interface EcRailItem { kind: 'mau' | 'lich' | 'hist'; id: string; ten: string; meta: string; sub?: string; active?: boolean; macDinh?: boolean; }

/** Nhân viên demo (nguồn dữ liệu preview + cột xuất). */
export interface EcEmployee { name: string; code: string; email: string; phone: string; department: string; position: string; status: string; joinDate: string; score: number; manager: string; }

/** Kế hoạch AI suy từ câu lệnh NL — feature A (bảng) điền tất cả field; feature C (văn bản) chỉ dùng `summary`.
 *  Field undefined = AI KHÔNG đụng tới (chỉ điền thứ suy chắc được). */
export interface EcAiPlan {
  summary: string;
  scope?: EcScope;
  colKeys?: string[];
  format?: EcFormat;
  schedule?: { tanSuat: 'ngay' | 'tuan' | 'thang'; thu?: string; ngayThang?: number; nguoiNhan?: string[] };
  sensitiveCols?: string[];
  unresolved?: string;
}

