/** Nhịp chạy của lịch → chuỗi hiển thị ("Hàng ngày" · "Thứ Hai" · "Ngày 01"). */
export function ecNhipLabel(s: EcSchedule): string {
  if (s.tanSuat === 'ngay') return 'Hàng ngày';
  if (s.tanSuat === 'tuan') return s.thu ?? 'Hàng tuần';
  return 'Ngày ' + String(s.ngayThang ?? 1).padStart(2, '0');
}

/** Bỏ dấu tiếng Việt → slug tên file (mockup màn 12: danh-sach-nhan-vien_20-08-2026.xlsx). */
export function ecSlug(text: string): string {
  return text
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd').replace(/Đ/g, 'D')
    .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

