/** Thứ tự recency CỨNG của rail theo seed (mockup màn 01) — item mới tạo runtime luôn nổi lên đầu. */
const RAIL_RECENCY_ORDER = [
  'mau:tpl-1', 'hist:his-1', 'lich:sch-1', 'mau:tpl-2', 'hist:his-2',
  'mau:tpl-3', 'lich:sch-2', 'hist:his-3', 'hist:his-4', 'lich:sch-3', 'hist:his-5',
];

/* ─────────────────────────── Store ─────────────────────────── */

/** Store của Export Center — provide tại page component (KHÔNG providedIn root: mỗi lần vào demo là phiên mới). */
@Injectable()
export class ExportCenterStore {
  private readonly toast = inject(HrmToastService);
  /** Đếm id runtime — deterministic, không Math.random (zoneless). */
  private seq = 0;

  /* ── Hằng ngữ cảnh (từ list page giả định) ── */
  readonly totalAll = 1248;
  readonly totalFilter = 26;
  readonly totalSelected = 0; // 0 → radio "Đã chọn" disabled kèm lý do (spec §5)
  readonly filterChips: { k: string; v: string }[] = [
    { k: 'Phòng ban', v: 'Kinh doanh' },
    { k: 'Trạng thái', v: 'Đang làm việc' },
    { k: 'Chi nhánh', v: 'Hồ Chí Minh' },
  ];

  /* ── Dữ liệu ── */
  readonly templates = signal<EcTemplate[]>(SEED_TEMPLATES);
  readonly schedules = signal<EcSchedule[]>(SEED_SCHEDULES);
  readonly history = signal<EcHistory[]>(SEED_HISTORY);
  readonly docTemplates = signal<EcDocTemplate[]>(SEED_DOC_TEMPLATES);
  readonly employees: EcEmployee[] = SEED_EMPLOYEES;

  /* ── Cấu hình hiện tại (canvas) ── */
  /** Mặc định "Theo bộ lọc" — thừa kế ngữ cảnh list page, khỏi khai lại (scorecard). */
  readonly scope = signal<EcScope>('filter');
  readonly cols = signal<EcCol[]>(SEED_COLS.map((c) => ({ ...c })));
  readonly format = signal<EcFormat>('xlsx');
  readonly pdfCfg = signal<{ kho: string; huong: string; tieuDe: boolean; boLoc: boolean; ngayXuat: boolean }>({
    kho: 'A4', huong: 'ngang', tieuDe: true, boLoc: true, ngayXuat: true,
  });
  readonly colMode = signal<'mau' | 'tuychinh'>('mau');

  /* ── Nguồn cấu hình + dirty ── */
  /** Pre-hydrate từ mẫu GHIM ★ (tpl-1) — nguồn tường minh, không auto-nạp "lần gần nhất". */
  readonly source = signal<{ kind: 'mau' | 'lich' | 'hist'; id: string; ten: string } | null>({
    kind: 'mau', id: 'tpl-1', ten: 'Danh sách nhân viên tháng',
  });
  /** Snapshot lúc hydrate — mốc so dirty. Seed cols đã khớp tpl-1 nên baseline = chính nó.
   *  CHỈ lưu thứ QUYẾT ĐỊNH nội dung file: cột (đã gồm thứ tự) + định dạng. colMode ('mau'↔'tuychinh')
   *  chỉ là affordance HIỂN THỊ (phải bật Tùy chỉnh mới kéo được cột) → KHÔNG tính dirty, tránh cry-wolf. */
  private readonly baseline = signal<{ colKeys: string[]; format: EcFormat }>({
    colKeys: [...TPL1_COLS], format: 'xlsx',
  });
  /** Đếm mục lệch baseline (cột+thứ tự / định dạng) — KHÔNG tính scope/filter/colMode: ngữ cảnh & hiển thị, chống cry-wolf. */
  readonly dirtyCount = computed(() => {
    const b = this.baseline();
    let n = 0;
    if (this.visibleColKeys().join('|') !== b.colKeys.join('|')) n++;
    if (this.format() !== b.format) n++;
    return n;
  });

  /* ── UI state ── */
  readonly segTab = signal<'table' | 'doc'>('table');
  readonly railFilter = signal<EcRailFilter>('all');
  readonly railQuery = signal('');
  readonly view = signal<'config' | 'exportSuccess' | 'scheduleSuccess'>('config');
  /** Loading demo (contract §5): skeleton 3 panel canvas khi hydrate · spinner trong CTA khi đang xuất. */
  readonly hydrating = signal(false);
  readonly exporting = signal(false);
  readonly schedOpen = signal(false);          // dock morph "Đặt lịch" (không modal thứ hai)
  readonly saveModalOpen = signal(false);      // modal "Lưu thành mẫu mới"
  readonly createSchedModalOpen = signal(false); // modal tạo lịch từ rail (không có cấu hình đang mở)
  readonly selectedDocId = signal('doc-1');
  readonly docTab = signal<'edit' | 'preview'>('edit');
  readonly previewEmpIdx = signal(0);
  readonly fieldPickerOpen = signal(false);
  /** Kịch bản demo empty states (màn 14/15) — ẩn nguồn tương ứng khỏi rail. */
  readonly scenario = signal<'full' | 'no-templates' | 'no-schedules'>('full');

  /* ── Kết quả gần nhất (cho màn success) ── */
  readonly lastExport = signal<EcHistory | null>(null);
  readonly lastSchedule = signal<EcSchedule | null>(null);

  /* ── Computed ── */

  /** Key các cột đang hiện — theo đúng thứ tự mảng (thứ tự xuất). */
  readonly visibleColKeys = computed(() => this.cols().filter((c) => c.visible).map((c) => c.key));
  readonly visibleColCount = computed(() => this.visibleColKeys().length);

  /** Số dòng theo phạm vi — bind sống lên CTA "Xuất N dòng". */
  readonly rowCount = computed(() => {
    const s = this.scope();
    return s === 'all' ? this.totalAll : s === 'filter' ? this.totalFilter : this.totalSelected;
  });

  /** 5 thông tin của dock tóm tắt (bất biến, mọi mode). */
  readonly summary = computed(() => ({
    soDong: this.rowCount(),
    soCot: this.visibleColCount(),
    tongCot: this.cols().length,
    dinhDang: EC_FORMAT_LABEL[this.format()],
    phamVi: EC_SCOPE_LABEL[this.scope()],
  }));

  /** Rail hợp nhất Mẫu + Lịch + Lịch sử, sắp theo recency cứng (seed) — item mới tạo nổi lên đầu. */
  readonly railItems = computed<EcRailItem[]>(() => {
    const sc = this.scenario();
    const items: EcRailItem[] = [
      ...this.templates().map<EcRailItem>((t) => ({
        kind: 'mau', id: t.id, ten: t.ten,
        meta: t.soCot + ' cột · ' + EC_FORMAT_SHORT[t.format] + ' · ' + t.capNhat,
        macDinh: t.macDinh,
      })),
      ...this.schedules().map<EcRailItem>((s) => ({
        kind: 'lich', id: s.id, ten: s.ten,
        meta: ecNhipLabel(s) + ' · ' + s.gio + ' · ' + EC_FORMAT_SHORT[s.format],
        sub: s.active ? 'Đang hoạt động' : 'Tạm dừng', // AP-01: trạng thái luôn render cả 2 chiều
        active: s.active,
      })),
      ...this.history().map<EcRailItem>((h) => ({
        kind: 'hist', id: h.id, ten: h.ten,
        meta: h.soDong.toLocaleString('vi-VN') + ' NV · ' + EC_FORMAT_SHORT[h.format] + ' · ' + h.at + ' · ' + h.nguoi,
      })),
    ];
    // Sort: index trong bảng recency seed; item ngoài seed (vừa tạo runtime) = -1 → luôn đứng đầu.
    const idx = (it: EcRailItem) => RAIL_RECENCY_ORDER.indexOf(it.kind + ':' + it.id);
    items.sort((a, b) => idx(a) - idx(b));

    const filter = this.railFilter();
    const q = this.railQuery().trim().toLowerCase();
    return items.filter((it) => {
      if (sc === 'no-templates' && it.kind === 'mau') return false;
      if (sc === 'no-schedules' && it.kind === 'lich') return false;
      if (filter !== 'all' && it.kind !== filter) return false;
      if (q && !it.ten.toLowerCase().includes(q)) return false;
      return true;
    });
  });

  /** Mẫu văn bản đang soạn (tab doc). */
  readonly selectedDoc = computed(() => this.docTemplates().find((d) => d.id === this.selectedDocId()) ?? null);

  /** Chip mời lưu (mockup màn 08): cấu hình thô — theo KIND nguồn (hist/null), KHÔNG đụng dirtyCount (chống cry-wolf). */
  readonly suggestSaveTemplate = computed(() => {
    const s = this.source();
    return !s || s.kind === 'hist';
  });

  /** Tên file của lần xuất gần nhất (mockup màn 12: danh-sach-nhan-vien_20-08-2026.xlsx). */
  readonly exportFileName = computed(() => {
    const h = this.lastExport();
    if (!h) return '';
    return ecSlug(h.ten) + '_' + EC_TODAY.replace(/\//g, '-') + EC_FORMAT_EXT[h.format];
  });

  /* ── Field picker văn bản: 9 field · 3 nhóm — CÙNG taxonomy với Cột xuất ── */
  readonly docFields: { nhom: string; fields: { code: string; label: string }[] }[] = [
    {
      nhom: 'Thông tin nhân viên',
      fields: [
        { code: 'name', label: 'Họ tên' },
        { code: 'code', label: 'Mã nhân viên' },
        { code: 'email', label: 'Email' },
        { code: 'phone', label: 'Điện thoại' },
      ],
    },
    {
      nhom: 'Công việc',
      fields: [
        { code: 'department', label: 'Phòng ban' },
        { code: 'position', label: 'Vị trí' },
        { code: 'manager', label: 'Quản lý trực tiếp' },
      ],
    },
    {
      nhom: 'Thời gian',
      fields: [
        { code: 'joinDate', label: 'Ngày vào' },
        { code: 'leaveDate', label: 'Ngày nghỉ việc' },
      ],
    },
  ];

  /* ── Actions: hydrate (rail → canvas) ── */

  /** Nạp mẫu vào canvas — colMode 'mau', reset baseline (dirty về 0). */
  hydrateTemplate(id: string): void {
    const t = this.templates().find((x) => x.id === id);
    if (!t) return;
    this.source.set({ kind: 'mau', id: t.id, ten: t.ten });
    this.applyColKeys(t.colKeys);
    this.format.set(t.format);
    this.colMode.set('mau');
    this.afterHydrate();
  }

  /** Nạp lịch — bộ cột lấy từ mẫu mà lịch dùng; colMode GIỮ nguyên (spec). */
  hydrateSchedule(id: string): void {
    const s = this.schedules().find((x) => x.id === id);
    if (!s) return;
    this.source.set({ kind: 'lich', id: s.id, ten: s.ten });
    const t = this.templates().find((x) => x.ten === s.templateTen);
    if (t) this.applyColKeys(t.colKeys);
    this.format.set(s.format);
    this.afterHydrate();
  }

  /** Khôi phục lịch sử — trọn cột + thứ tự + định dạng; colMode 'tuychinh' (mockup màn 08: cấu hình thô, không gắn mẫu). */
  hydrateHistory(id: string): void {
    const h = this.history().find((x) => x.id === id);
    if (!h) return;
    this.source.set({ kind: 'hist', id: h.id, ten: h.ten + ' · ' + h.at });
    this.applyColKeys(h.colKeys);
    this.format.set(h.format);
    this.colMode.set('tuychinh');
    this.afterHydrate();
  }

  /** "Dùng lại" trên rail lịch sử = khôi phục nguyên cấu hình. */
  reuseHistory(id: string): void { this.hydrateHistory(id); }

  /* ── Actions: thực thi ── */

  /** Xuất ngay: spinner trong CTA ~600ms (contract §5) → ghi Lịch sử (dòng 1 rail, badge mới) + màn success. */
  exportNow(): void {
    if (this.exporting()) return;
    this.exporting.set(true);
    setTimeout(() => {
      const h: EcHistory = {
        id: 'his-n' + ++this.seq,
        // Lịch sử ghi theo DATASET đang xuất (mockup màn 12), không theo tên mẫu nguồn.
        ten: 'Danh sách nhân viên',
        soDong: this.rowCount(),
        format: this.format(),
        at: 'Vừa xong',
        nguoi: 'Bạn',
        colKeys: this.visibleColKeys(),
        moi: true,
      };
      this.history.update((l) => [h, ...l]);
      this.lastExport.set(h);
      this.exporting.set(false);
      this.view.set('exportSuccess');
    }, 600);
  }

  /** Lưu cấu hình hiện tại thành mẫu mới — nguồn chuyển sang mẫu vừa lưu → dirty về 0 (đường 1-click cho mai). */
  saveTemplate(data: { ten: string; moTa?: string; macDinh?: boolean }): void {
    const colKeys = this.visibleColKeys();
    const t: EcTemplate = {
      id: 'tpl-n' + ++this.seq,
      ten: data.ten, moTa: data.moTa,
      soCot: colKeys.length, format: this.format(), capNhat: EC_TODAY,
      macDinh: !!data.macDinh, colKeys,
    };
    this.templates.update((l) => [t, ...(data.macDinh ? l.map((x) => ({ ...x, macDinh: false })) : l)]);
    this.saveModalOpen.set(false);
    this.source.set({ kind: 'mau', id: t.id, ten: t.ten });
    this.colMode.set('mau');
    this.resetBaseline();
    this.toast.success('Đã lưu mẫu', '"' + data.ten + '" — dùng lại chỉ 1 cú nhấp');
  }

  /** Tạo lịch từ cấu hình đang mở (dock morph) hoặc modal — default theo config hiện tại. */
  createSchedule(data: {
    ten: string; tanSuat?: 'ngay' | 'tuan' | 'thang'; thu?: string; ngayThang?: number;
    gio?: string; format?: EcFormat; nguoiNhan?: string[];
  }): void {
    const tanSuat = data.tanSuat ?? 'tuan';
    const s: EcSchedule = {
      id: 'sch-n' + ++this.seq,
      ten: data.ten,
      tanSuat,
      thu: tanSuat === 'tuan' ? (data.thu ?? 'Thứ Hai') : undefined,
      ngayThang: tanSuat === 'thang' ? (data.ngayThang ?? 1) : undefined,
      gio: data.gio ?? '08:00',
      format: data.format ?? this.format(),
      nguoiNhan: data.nguoiNhan ?? ['HR Manager', 'hr@company.com'],
      active: true,
      templateTen: this.source()?.ten ?? 'Danh sách nhân viên tháng',
      // lanKe demo cố định theo tần suất — không tính từ Date.now() (zoneless).
      lanKe: EC_NEXT_RUN[tanSuat],
      lanChay: [],
    };
    this.schedules.update((l) => [s, ...l]);
    this.lastSchedule.set(s);
    this.schedOpen.set(false);
    this.createSchedModalOpen.set(false);
    this.view.set('scheduleSuccess');
  }

  /** Chạy lịch ngay: ghi lần chạy + ghi Lịch sử. */
  runScheduleNow(id: string): void {
    const s = this.schedules().find((x) => x.id === id);
    if (!s) return;
    const soDong = this.totalFilter; // lịch chạy trên phạm vi "Theo bộ lọc" tại thời điểm chạy
    this.schedules.update((l) => l.map((x) => x.id === id
      ? { ...x, lanChay: [{ at: 'Vừa xong', soDong }, ...x.lanChay] }
      : x));
    const t = this.templates().find((x) => x.ten === s.templateTen);
    this.history.update((l) => [{
      id: 'his-n' + ++this.seq,
      ten: s.ten, soDong, format: s.format, at: 'Vừa xong', nguoi: 'System (chạy tay)',
      colKeys: t ? [...t.colKeys] : this.visibleColKeys(), moi: true,
    }, ...l]);
    this.toast.success('Đã chạy lịch', '"' + s.ten + '" — ' + soDong + ' dòng');
  }

  /** Bật/tạm dừng lịch — AP-01: cả 2 chiều đều là trạng thái hợp lệ, không xóa. */
  toggleScheduleActive(id: string): void {
    // Kích hoạt lại: lanKe tính theo ĐÚNG tần suất của lịch (ngày/tuần/tháng) — không gán cứng nhịp tuần.
    this.schedules.update((l) => l.map((x) => (x.id === id
      ? { ...x, active: !x.active, lanKe: !x.active ? EC_NEXT_RUN[x.tanSuat] : '—' }
      : x)));
  }

  /** Ghim mẫu mặc định ★ — đúng 1 mẫu, dùng pre-hydrate lần mở sau. */
  setDefaultTemplate(id: string): void {
    this.templates.update((l) => l.map((x) => ({ ...x, macDinh: x.id === id })));
    const t = this.templates().find((x) => x.id === id);
    if (t) this.toast.success('Đã đặt mẫu mặc định', '"' + t.ten + '" sẽ tự nạp khi mở');
  }

  /** Sao chép mẫu — bản sao nổi lên đầu rail (recency). */
  duplicateTemplate(id: string): void {
    const t = this.templates().find((x) => x.id === id);
    if (!t) return;
    const copy: EcTemplate = { ...t, id: 'tpl-n' + ++this.seq, ten: t.ten + ' (bản sao)', macDinh: false, capNhat: EC_TODAY, colKeys: [...t.colKeys] };
    this.templates.update((l) => [copy, ...l]);
    this.toast.neutral('Đã sao chép mẫu', '"' + copy.ten + '" ở đầu danh sách');
  }

  /** Đổi tên mẫu — cascade sang nguồn đang dùng VÀ sang lịch liên kết (lịch link bằng tên;
   *  không cascade thì hydrate/chạy lịch nạp nhầm cột im lặng). */
  renameTemplate(id: string, ten: string): void {
    const old = this.templates().find((x) => x.id === id);
    if (!old) return;
    const oldTen = old.ten;
    this.templates.update((l) => l.map((x) => (x.id === id ? { ...x, ten, capNhat: EC_TODAY } : x)));
    this.schedules.update((l) => l.map((x) => (x.templateTen === oldTen ? { ...x, templateTen: ten } : x)));
    const src = this.source();
    if (src?.kind === 'mau' && src.id === id) this.source.set({ ...src, ten });
    this.toast.success('Đã đổi tên mẫu', 'thành "' + ten + '"');
  }

  /** Xóa mẫu (confirm 2 bước làm ở UI) — nếu là nguồn đang dùng thì gỡ nguồn, cấu hình giữ nguyên. */
  deleteTemplate(id: string): void {
    const t = this.templates().find((x) => x.id === id);
    this.templates.update((l) => {
      const next = l.filter((x) => x.id !== id);
      // Xóa mẫu mặc định ★ → thăng mẫu đầu còn lại làm mặc định, để pre-hydrate lần mở sau không mất ★.
      if (t?.macDinh && next.length && !next.some((x) => x.macDinh)) next[0] = { ...next[0], macDinh: true };
      return next;
    });
    if (this.source()?.kind === 'mau' && this.source()?.id === id) this.source.set(null);
    if (t) this.toast.warning('Đã xóa mẫu', '"' + t.ten + '"');
  }

  /** Xóa lịch (confirm 2 bước làm ở UI). */
  deleteSchedule(id: string): void {
    const s = this.schedules().find((x) => x.id === id);
    this.schedules.update((l) => l.filter((x) => x.id !== id));
    if (this.source()?.kind === 'lich' && this.source()?.id === id) this.source.set(null);
    if (s) this.toast.warning('Đã xóa lịch', '"' + s.ten + '"');
  }

  /** Hoàn tác chỉnh sửa — trả canvas về đúng snapshot nguồn (dirty về 0). */
  resetToBaseline(): void {
    const b = this.baseline();
    this.applyColKeys(b.colKeys);
    this.format.set(b.format);
  }

  /* ── Actions: văn bản theo mẫu ── */

  /** Chèn {{code}} vào body mẫu văn bản đang soạn — demo không track caret nên chèn cuối. */
  insertField(code: string): void {
    const id = this.selectedDocId();
    this.docTemplates.update((l) => l.map((d) => (d.id === id ? { ...d, body: d.body + ' {{' + code + '}}' } : d)));
    this.fieldPickerOpen.set(false);
  }

  /** Render preview với dữ liệu THẬT của 1 nhân viên — soi lỗi mẫu trước khi tạo cả loạt. */
  renderDocPreview(empIdx: number): string {
    const doc = this.selectedDoc();
    const emp = this.employees[empIdx];
    if (!doc || !emp) return '';
    return doc.body.replace(/\{\{(\w+)\}\}/g, (_, key: string) => {
      const v = (emp as unknown as Record<string, string | number>)[key];
      // Field chưa có dữ liệu (vd leaveDate với người đang làm việc) → gạch dài, không để {{raw}} lọt ra văn bản.
      return v === undefined || v === '' ? '—' : String(v);
    });
  }

  /* ─────────────────────────── AI mock (feature A · B · C) ───────────────────────────
   *  Engine TẤT ĐỊNH (không LLM): map keyword tiếng Việt → EcAiPlan. AI CHỈ ĐIỀN cấu hình,
   *  TUYỆT ĐỐI KHÔNG auto-Xuất. Field AI đặt đánh dấu qua aiTouched (highlight + Hoàn tác);
   *  cột nhạy cảm (email/phone) gắn cờ sensitiveCols. Zoneless-an-toàn: setTimeout + signal.set. */

  readonly aiPrompt = signal('');
  readonly aiThinking = signal(false);
  /** Plan vừa áp — hiện "AI hiểu…" + nút Hoàn tác. */
  readonly aiPlan = signal<EcAiPlan | null>(null);
  /** Field AI đã đặt: 'scope'|'cols'|'format'|'schedule' — LUÔN set Set MỚI để highlight sống. */
  readonly aiTouched = signal<Set<string>>(new Set());
  /** Snapshot trước khi AI áp — cho Hoàn tác một-phát. */
  private aiUndo: { scope: EcScope; colKeys: string[]; format: EcFormat; colMode: 'mau' | 'tuychinh' } | null = null;
  /** Dock đọc để prefill morph khi AI mở lịch. */
  readonly aiScheduleSeed = signal<EcAiPlan['schedule'] | null>(null);
  /** 4 câu gợi ý gõ nhanh (feature A). */
  readonly aiSuggestPrompts: string[] = [
    'NV phòng Kinh doanh — email, ngày vào, xuất PDF',
    'Báo cáo điểm đánh giá cả công ty, Excel, gửi HR hàng tháng',
    'Danh bạ nhân sự — mã, vị trí, điện thoại, email',
    'Xuất CSV toàn bộ để import hệ thống khác',
  ];

  /** Feature B — tối đa 2 cột ĐANG ẨN đáng thêm (ưu tiên thâm niên → liên hệ → định danh). */
  readonly aiSuggestCols = computed<{ key: string; title: string; reason: string }[]>(() => {
    const visible = new Set(this.visibleColKeys());
    const cand: { key: string; reason: string }[] = [
      { key: 'joinDate', reason: 'thâm niên' },
      { key: 'email', reason: 'liên hệ' },
      { key: 'code', reason: 'định danh' },
    ];
    const all = this.cols();
    const out: { key: string; title: string; reason: string }[] = [];
    for (const c of cand) {
      if (visible.has(c.key)) continue;               // bỏ cột đã hiện
      const col = all.find((x) => x.key === c.key);
      if (!col) continue;
      out.push({ key: c.key, title: col.title, reason: c.reason });
      if (out.length >= 2) break;
    }
    return out;
  });

  /** NL → EcAiPlan (feature A). Tất định; match tiếng Việt CÓ DẤU. Không side-effect (chỉ suy). */
  aiParse(prompt: string): EcAiPlan {
    const p = prompt.toLowerCase();
    const has = (...kw: string[]) => kw.some((k) => p.includes(k));

    // ── "phòng <TênPhòng>" = NGỮ CẢNH LỌC (không phải yêu cầu cột). Tách khỏi cột 'department'. ──
    const DEPTS = ['kinh doanh', 'nhân sự', 'kỹ thuật', 'tài chính', 'kế toán', 'marketing', 'hành chính', 'sản xuất', 'công nghệ', 'it'];
    const deptFilter = DEPTS.find((d) => p.includes('phòng ' + d) || p.includes('bộ phận ' + d) || p.includes('ban ' + d));

    // ── Cột: gom key match, 'name' luôn đầu, phần còn lại theo thứ tự nhóm co-ban→cong-viec→thoi-gian→danh-gia ──
    const matched = new Set<string>();
    if (has('mã')) matched.add('code');
    if (has('email', 'thư')) matched.add('email');
    if (has('điện thoại', 'sđt', 'số điện thoại')) matched.add('phone');
    // 'department' CHỈ khi nói rõ CỘT "phòng ban" / "cột phòng" — KHÔNG bắt "phòng Kinh doanh" (đó là lọc).
    if (/phòng ban|cột phòng|kèm phòng/.test(p)) matched.add('department');
    if (has('vị trí', 'chức danh', 'chức vụ')) matched.add('position');
    if (has('trạng thái', 'tình trạng')) matched.add('status');
    if (has('ngày vào', 'thâm niên')) matched.add('joinDate');
    if (has('điểm', 'đánh giá', 'kpi')) matched.add('score');
    const ORDER = ['name', 'code', 'email', 'phone', 'department', 'position', 'status', 'joinDate', 'score'];
    const colKeys = matched.size ? ['name', ...ORDER.filter((k) => k !== 'name' && matched.has(k))] : undefined;

    // ── Phạm vi (lọc theo phòng cụ thể → filter, giữ bộ lọc ngữ cảnh của list-page) ──
    let scope: EcScope | undefined;
    if (has('tất cả', 'toàn bộ', 'cả công ty', 'toàn công ty')) scope = 'all';
    else if (deptFilter || /phòng ban|cột phòng/.test(p) || has('bộ phận', 'trạng thái', 'tình trạng', 'bộ lọc')) scope = 'filter';

    // ── Định dạng (dùng ranh giới từ cho 'in' để tránh dính "kinh"/"tin") ──
    let format: EcFormat | undefined;
    if (has('pdf', 'chia sẻ') || /\bin\b/.test(p)) format = 'pdf';
    else if (has('excel', 'xlsx', 'bảng tính')) format = 'xlsx';
    else if (has('csv', 'import', 'hệ thống khác')) format = 'csv';

    // ── Lịch (chỉ set khi có keyword tần suất) ──
    let schedule: EcAiPlan['schedule'] | undefined;
    if (has('hàng tuần', 'mỗi tuần', 'thứ 2', 'thứ hai')) schedule = { tanSuat: 'tuan', thu: 'Thứ Hai' };
    else if (has('hàng ngày', 'mỗi ngày')) schedule = { tanSuat: 'ngay' };
    else if (has('hàng tháng', 'mỗi tháng', 'đầu tháng', 'ngày 1')) schedule = { tanSuat: 'thang', ngayThang: 1 };
    if (schedule) {
      const nguoiNhan: string[] = [];
      if (has('hr')) nguoiNhan.push('HR Manager');
      if (has('sếp', 'quản lý', 'giám đốc')) nguoiNhan.push('Quản lý trực tiếp');
      if (nguoiNhan.length) schedule = { ...schedule, nguoiNhan };
    }

    // ── Cột nhạy cảm = colKeys ∩ {email, phone} ──
    const sens = colKeys?.filter((k) => k === 'email' || k === 'phone') ?? [];
    const sensitiveCols = sens.length ? sens : undefined;

    // ── Tóm tắt tiếng Việt + phần chưa suy được ──
    const titleOf = (k: string) => this.cols().find((c) => c.key === k)?.title ?? k;
    const titleCase = (s: string) => s.charAt(0).toUpperCase() + s.slice(1); // "kinh doanh" → "Kinh doanh" (chỉ hoa chữ đầu, đúng tiếng Việt)
    const parts: string[] = [];
    // Phạm vi: nếu lọc theo phòng cụ thể → nêu rõ tên phòng (không chỉ "Theo bộ lọc").
    if (scope === 'filter' && deptFilter) parts.push('Phạm vi Theo bộ lọc · phòng ' + titleCase(deptFilter));
    else if (scope) parts.push('Phạm vi ' + EC_SCOPE_LABEL[scope]);
    if (colKeys) parts.push(colKeys.length + ' cột (' + colKeys.map(titleOf).join(', ') + ')');
    if (format) parts.push(EC_FORMAT_SHORT[format]);
    if (schedule) {
      const nhip = schedule.tanSuat === 'ngay' ? 'Hàng ngày'
        : schedule.tanSuat === 'tuan' ? 'Hàng tuần ' + (schedule.thu ?? '')
          : 'Hàng tháng ngày ' + String(schedule.ngayThang ?? 1).padStart(2, '0');
      parts.push('lịch ' + nhip.trim());
    }
    const summary = parts.length ? parts.join(' · ') : 'Chưa suy được cấu hình — thử nêu cột, định dạng hoặc phạm vi';
    let unresolved: string | undefined;
    if (schedule && !schedule.nguoiNhan?.length) unresolved = 'chưa rõ người nhận';
    else if (!parts.length) unresolved = 'chưa rõ yêu cầu';

    return { summary, scope, colKeys, format, schedule, sensitiveCols, unresolved };
  }

  /** Feature A — chạy AI: "nghĩ" ~700ms rồi ĐIỀN cấu hình (không Xuất). Lưu snapshot để Hoàn tác. */
  aiRun(prompt: string): void {
    this.aiThinking.set(true);
    const plan = this.aiParse(prompt);
    setTimeout(() => {
      // Chụp state HIỆN TẠI trước khi AI đặt — mốc Hoàn tác.
      this.aiUndo = {
        scope: this.scope(),
        colKeys: this.visibleColKeys(),
        format: this.format(),
        colMode: this.colMode(),
      };
      const touched = new Set<string>();
      if (plan.scope) { this.scope.set(plan.scope); touched.add('scope'); }
      if (plan.colKeys) { this.colMode.set('tuychinh'); this.applyColKeys(plan.colKeys); touched.add('cols'); }
      if (plan.format) { this.format.set(plan.format); touched.add('format'); }
      if (plan.schedule) { this.aiScheduleSeed.set(plan.schedule); this.schedOpen.set(true); touched.add('schedule'); }
      this.aiTouched.set(touched);              // Set MỚI mỗi lần
      this.aiPlan.set(plan);
      this.aiThinking.set(false);
      // KHÔNG gọi exportNow — AI chỉ điền, người dùng tự bấm Xuất.
    }, 700);
  }

  /** Hoàn tác — trả cấu hình về đúng snapshot trước khi AI áp (highlight tắt). */
  aiUndoApply(): void {
    const u = this.aiUndo;
    if (!u) return;
    this.scope.set(u.scope);
    this.applyColKeys(u.colKeys);
    this.format.set(u.format);
    this.colMode.set(u.colMode);
    this.schedOpen.set(false);
    this.aiScheduleSeed.set(null);
    this.aiPlan.set(null);
    this.aiTouched.set(new Set());
    this.aiUndo = null;
  }

  /** Dọn highlight AI — gọi khi hydrate mẫu khác / đổi tab để highlight không dính dai.
   *  Reset LUÔN aiUndo: nút Hoàn tác đã ẩn thì snapshot cũ (thuộc nguồn TRƯỚC hydrate) phải bỏ,
   *  tránh Hoàn tác ở nguồn mới áp nhầm state của mẫu cũ (ghi đè im lặng). */
  aiClear(): void {
    this.aiPlan.set(null);
    this.aiTouched.set(new Set());
    this.aiUndo = null;
    this.aiPrompt.set(''); // ô command bar không giữ câu cũ khi đổi tab / hydrate mẫu khác
  }

  /** Feature C — soạn nháp văn bản theo keyword vào MẪU ĐANG CHỌN (~700ms). */
  aiRunDoc(prompt: string): void {
    this.aiThinking.set(true);
    setTimeout(() => {
      const p = prompt.toLowerCase();
      const draft = p.includes('nghỉ phép') ? DOC_DRAFT.nghiPhep
        : (p.includes('xác nhận') || p.includes('công tác')) ? DOC_DRAFT.xacNhan
          : p.includes('hợp đồng') ? DOC_DRAFT.hopDong
            : DOC_DRAFT.phieu;
      const id = this.selectedDocId();
      this.docTemplates.update((l) => l.map((d) => (d.id === id ? { ...d, body: draft } : d)));
      this.aiThinking.set(false);
      this.aiPlan.set({ summary: 'Đã soạn nháp — sửa tuỳ ý' });
    }, 700);
  }

  /** Feature B — gợi ý tên + mô tả khi Lưu mẫu (suy từ cột + phạm vi + định dạng hiện tại). */
  aiSuggestTemplateMeta(): { ten: string; moTa: string } {
    const keys = this.visibleColKeys();
    const titles = keys.map((k) => this.cols().find((c) => c.key === k)?.title ?? k);
    const ten = 'Báo cáo nhân sự — ' + keys.length + ' cột · ' + EC_SCOPE_LABEL[this.scope()];
    const moTa = titles.join(', ') + ' · Định dạng ' + EC_FORMAT_LABEL[this.format()];
    return { ten, moTa };
  }

  /* ── Private ── */

  /** Áp bộ cột theo colKeys: cột chọn lên đầu đúng thứ tự, cột còn lại ẩn nhưng vẫn giữ (đếm 6/9). */
  private applyColKeys(keys: string[]): void {
    const cur = this.cols();
    const chosen = keys
      .map((k) => cur.find((c) => c.key === k))
      .filter((c): c is EcCol => !!c)
      .map((c) => ({ ...c, visible: true }));
    const rest = cur.filter((c) => !keys.includes(c.key)).map((c) => ({ ...c, visible: false }));
    this.cols.set([...chosen, ...rest]);
  }

  /** Sau hydrate: quay về canvas cấu hình + chốt baseline mới (dirty về 0). */
  private afterHydrate(): void {
    // Dọn AI TRƯỚC: mọi đường hydrate (pick/useTemplate/reuse/hydrateSchedule) đi qua đây → badge 'AI',
    // dải "AI hiểu…" + nút Hoàn tác không dính sang nguồn mới; xoá luôn aiUndo (snapshot của nguồn cũ).
    this.aiClear();
    this.view.set('config');
    this.segTab.set('table');
    this.schedOpen.set(false);
    this.resetBaseline();
    // Skeleton 3 panel ngắn khi hydrate (contract §5) — flag ngắn hạn, không chặn rail/dock.
    this.hydrating.set(true);
    setTimeout(() => this.hydrating.set(false), 350);
  }

  /** Chốt snapshot hiện tại làm mốc dirty. */
  private resetBaseline(): void {
    this.baseline.set({ colKeys: this.visibleColKeys(), format: this.format() });
  }
}
