import { ChangeDetectionStrategy, Component, inject, model } from '@angular/core';
import {
  IconArrowLeft, IconArrowRight, IconHistory, IconUpload, IconX,
  TablerIconComponent,
} from '@tabler/icons-angular';
import { HrmButton, HrmStepItem, HrmSteps } from 'hrm-ui';
import { ImportStore } from './import.store';
import { SgImportStepSetup } from './step-setup';
import { SgImportStepReview } from './step-review';
import { SgImportStepConfirm } from './step-confirm';
import { SgImportStepResult } from './step-result';
import { SgImportHistory } from './import-history';

/** sg-import-wizard — shell dialog "Import dữ liệu" 4 bước (AI-first).
 *  Overlay tự dựng (mask + dialog) theo pattern hdw-cmg-* của hrm-data-workspace.
 *  Store provide TẠI ĐÂY — mỗi lần mở wizard dùng chung một ImportStore cho 4 step + lịch sử. */
@Component({
  selector: 'sg-import-wizard',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    TablerIconComponent, HrmButton, HrmSteps,
    SgImportStepSetup, SgImportStepReview, SgImportStepConfirm, SgImportStepResult, SgImportHistory,
  ],
  providers: [ImportStore],
  host: { '(document:keydown.escape)': 'onEsc()' },
  template: `
    @if (open()) {
      <div class="imw-mask"></div>
      <div class="imw-dialog" role="dialog" aria-modal="true" aria-labelledby="imw-title" tabindex="-1">

        <!-- Header: tiêu đề + Lịch sử + đóng -->
        <div class="imw-head">
          <div class="imw-head-l">
            <span class="imw-head-ic"><tabler-icon [icon]="icUpload" [size]="18" /></span>
            <span class="imw-title" id="imw-title">Import dữ liệu</span>
          </div>
          <div class="imw-head-r">
            <hrm-button variant="text" size="sm" (click)="st.historyOpen.set(true)">
              <tabler-icon [icon]="icHistory" [size]="16" /> Lịch sử
            </hrm-button>
            <button type="button" class="imw-x" aria-label="Đóng" (click)="close()">
              <tabler-icon [icon]="icX" [size]="18" />
            </button>
          </div>
        </div>

        <!-- Stepper 4 bước -->
        <div class="imw-steps">
          <hrm-steps [items]="stepItems" [current]="st.step()" size="small" />
        </div>

        <!-- Body: render step hiện tại -->
        <div class="imw-body">
          @switch (st.step()) {
            @case (0) { <sg-import-step-setup /> }
            @case (1) { <sg-import-step-review /> }
            @case (2) { <sg-import-step-confirm /> }
            @case (3) { <sg-import-step-result /> }
          }
        </div>

        <!-- Footer động theo step -->
        <div class="imw-foot">
          <hrm-button variant="default" (click)="close()">Đóng</hrm-button>
          <div class="imw-foot-r">
            @switch (st.step()) {
              @case (0) {
                <hrm-button variant="primary" [disabled]="!st.canContinueSetup()" (click)="st.goto(1)">
                  Tiếp tục <tabler-icon [icon]="icArrowRight" [size]="16" />
                </hrm-button>
              }
              @case (1) {
                <hrm-button variant="default" (click)="st.goto(0)">
                  <tabler-icon [icon]="icArrowLeft" [size]="16" /> Quay lại
                </hrm-button>
                <hrm-button variant="primary" (click)="st.goto(2)">
                  Tiếp tục <tabler-icon [icon]="icArrowRight" [size]="16" />
                </hrm-button>
              }
              @case (2) {
                @if (st.importPhase() === 'idle') {
                  <hrm-button variant="default" (click)="st.goto(1)">
                    <tabler-icon [icon]="icArrowLeft" [size]="16" /> Quay lại
                  </hrm-button>
                  <hrm-button variant="primary" (click)="st.startImport()">
                    Import {{ st.BIG.willImport }} dòng <tabler-icon [icon]="icArrowRight" [size]="16" />
                  </hrm-button>
                } @else if (st.importPhase() === 'running') {
                  <hrm-button variant="default" (click)="st.runBackground()">Chạy nền</hrm-button>
                }
              }
              @case (3) {
                <hrm-button variant="primary" (click)="st.resetAll()">Import tệp khác</hrm-button>
              }
            }
          </div>
        </div>

        <!-- Lịch sử import: overlay TRONG dialog (component tự absolute inset 0) -->
        @if (st.historyOpen()) {
          <sg-import-history />
        }
      </div>
    }
  `,
  styles: [`
    .imw-mask { position: fixed; inset: 0; background: var(--overlay); z-index: var(--z-modal); }
    .imw-dialog { position: fixed; z-index: calc(var(--z-modal) + 1); top: 50%; left: 50%; transform: translate(-50%, -50%);
      width: min(1280px, 96vw); height: min(860px, 94vh); display: flex; flex-direction: column;
      background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-xl);
      box-shadow: var(--shadow-regular-lg); overflow: hidden; }

    /* Header */
    .imw-head { flex: none; display: flex; align-items: center; justify-content: space-between;
      gap: var(--space-3); padding: var(--space-3) var(--space-4); border-bottom: 1px solid var(--border-soft); }
    .imw-head-l { display: flex; align-items: center; gap: var(--space-2); min-width: 0; }
    .imw-head-ic { display: grid; place-items: center; width: 32px; height: 32px; flex: none;
      border-radius: var(--radius-md); background: var(--primary-bg-subtle); color: var(--primary-base); }
    .imw-title { font-size: var(--fs-16, 16px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .imw-head-r { display: flex; align-items: center; gap: var(--space-1); }
    .imw-x { display: grid; place-items: center; width: 30px; height: 30px; border: 0; background: transparent;
      border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .imw-x:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }

    /* Stepper */
    .imw-steps { flex: none; padding: var(--space-3) var(--space-6); border-bottom: 1px solid var(--border-soft); }

    /* Body — step tự dựng card trên nền canvas; KHÔNG cho dialog scroll ngang */
    .imw-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; overflow-x: hidden;
      padding: var(--space-5) var(--space-6); background: var(--bg-canvas); }

    /* Footer */
    .imw-foot { flex: none; display: flex; align-items: center; gap: var(--space-2);
      padding: var(--space-3) var(--space-4); border-top: 1px solid var(--border-soft);
      background: var(--bg-surface); }
    .imw-foot-r { display: flex; align-items: center; gap: var(--space-2); margin-inline-start: auto; }
    .imw-foot-r hrm-button { font-variant-numeric: tabular-nums; }
  `],
})
export class SgImportWizard {
  protected readonly st = inject(ImportStore);

  /** Hai chiều với trang cha: <sg-import-wizard [(open)]="importOpen" /> */
  readonly open = model(false);

  protected readonly stepItems: HrmStepItem[] = [
    { title: 'Thiết lập' },
    { title: 'Kiểm tra & sửa' },
    { title: 'Xác nhận & import' },
    { title: 'Kết quả' },
  ];

  protected readonly icUpload = IconUpload;
  protected readonly icHistory = IconHistory;
  protected readonly icX = IconX;
  protected readonly icArrowLeft = IconArrowLeft;
  protected readonly icArrowRight = IconArrowRight;

  protected close(): void {
    this.open.set(false);
  }

  /** ESC: lớp trên cùng đóng trước — lịch sử đang mở thì đóng lịch sử, không thì đóng dialog. */
  protected onEsc(): void {
    if (!this.open()) return;
    if (this.st.historyOpen()) { this.st.historyOpen.set(false); return; }
    this.close();
  }
}
