import {
  ChangeDetectionStrategy, Component, ElementRef, TemplateRef,
  afterNextRender, computed, inject, signal, viewChild,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmButton, HrmEmpty, HrmInput, HrmMessageService, HrmModalService, HrmToastService } from 'hrm-ui';
import {
  TablerIconComponent, IconSearch, IconStar, IconFileText, IconClock, IconCalendar,
  IconDownload, IconRefresh, IconDots, IconPencil, IconCopy, IconTrash,
  IconPlayerPlay, IconPlayerPause, IconCheck,
} from '@tabler/icons-angular';
import { EC_TODAY, EcDocTemplate, EcRailFilter, EcRailItem, EcSchedule, ExportCenterStore } from './_export-data';

/** ═════════ EC-RAIL — rail trái "Tái dùng" 268px (mockup màn 01/02/07/08/12/13/14/15) ═════════
 *  MỘT danh sách hợp nhất Mẫu + Lịch + Lịch sử (store.railItems, recency-sort) — chip lọc thay tab khu riêng.
 *  Click item = hydrate thẳng vào canvas (không màn chi tiết). Search type-ahead: Enter① nạp item đầu,
 *  Enter② xuất (guard 2-Enter — tóm tắt kịp vào mắt trước khi thực thi).
 *  KHÔNG provide store — host page provide (mỗi lần vào demo là phiên mới). */
@Component({
  selector: 'ec-rail',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule, HrmButton, HrmEmpty, HrmInput, TablerIconComponent],
  template: `
    @if (store.segTab() === 'doc') {
      <!-- ═══ Ngữ cảnh tab VĂN BẢN (Contract §2 · mockup màn 09): rail = "Mẫu đã lưu" ═══ -->
      <div class="rl-search">
        <hrm-input
          [prefixIcon]="icSearch"
          placeholder="Tìm mẫu văn bản…"
          [ngModel]="store.railQuery()"
          (ngModelChange)="onQuery($event)"
          (keydown.enter)="onEnter($event)" />
      </div>
      <div class="rl-list">
        <div class="rl-h">Mẫu đã lưu · <b class="num">{{ docItems().length }}</b></div>
        @for (d of docItems(); track d.id) {
          <div class="ri" role="button" tabindex="0"
            [class.on]="store.selectedDocId() === d.id"
            (click)="pickDoc(d.id)" (keydown.enter)="pickDoc(d.id)">
            <span class="ri-ic t-mau"><tabler-icon [icon]="icFileText" [size]="14" /></span>
            <div class="ri-m">
              <div class="ri-t">{{ d.ten }}</div>
              <div class="ri-s"><b class="num">{{ d.soTruong }}</b>&nbsp;trường · {{ d.format === 'word' ? 'WORD' : 'PDF' }} · {{ d.capNhat }}</div>
            </div>
          </div>
        } @empty {
          <div class="rl-empty">
            <hrm-empty preset="no-results" description="Không tìm thấy mẫu văn bản" />
          </div>
        }
      </div>
      <div class="rl-foot">
        <button type="button" class="lnk" (click)="addDocTemplate()">+ Thêm mẫu văn bản</button>
      </div>
    } @else {
    <!-- Search type-ahead — kbd hint "⏎⏎ dùng" (Enter① nạp · Enter② thực thi: xuất/chạy lịch) -->
    <div class="rl-search">
      <hrm-input
        [prefixIcon]="icSearch"
        [placeholder]="searchPh()"
        [ngModel]="store.railQuery()"
        (ngModelChange)="onQuery($event)"
        (keydown.enter)="onEnter($event)" />
      <span class="kbd">⏎⏎ dùng</span>
    </div>

    <!-- Chip lọc loại = cách xem "Mẫu của tôi"/"Lịch xuất"/"Lịch sử" — không phải tab khu riêng -->
    <div class="rl-chips">
      @for (c of chips; track c.v) {
        <button type="button" class="rl-chip" [class.on]="store.railFilter() === c.v"
          (click)="setFilter(c.v)">{{ c.l }}</button>
      }
    </div>

    <div class="rl-list">
      @for (g of groups(); track g.header) {
        <div class="rl-h">{{ g.header }}@if (g.count != null) { · <b class="num">{{ g.count }}</b> }</div>
        @for (it of g.items; track key(it)) {
          <div class="ri" role="button" tabindex="0"
            [class.on]="isOn(it)" [class.fresh]="isNew(it)"
            [class.has-keb]="it.kind !== 'hist'" [class.keb-open]="kebabFor() === key(it)"
            (click)="pick(it)" (keydown.enter)="pick(it)">
            <!-- Ô icon vuông theo loại: mẫu=primary · lịch=success · lịch sử=muted; vừa tạo=tick xanh -->
            <span class="ri-ic"
              [class.t-mau]="it.kind === 'mau'" [class.t-lich]="it.kind === 'lich'"
              [class.t-hist]="it.kind === 'hist'" [class.t-new]="isNew(it)">
              <tabler-icon [icon]="$any(icFor(it))" [size]="14" />
            </span>
            <div class="ri-m">
              <div class="ri-t">{{ it.ten }}@if (it.macDinh) { <span class="pin">★</span> }</div>
              @let p = metaParts(it);
              <div class="ri-s">@if (p.num) {<b class="num">{{ p.num }}</b>&nbsp;}{{ p.rest }}</div>
              <!-- AP-01: trạng thái lịch luôn render cả 2 chiều — hoạt động lẫn tạm dừng -->
              @if (it.kind === 'lich' && it.sub) {
                <div class="ri-s">
                  <span class="sdot" [class.act]="it.active" [class.paused]="!it.active">{{ it.sub }}</span>
                </div>
              }
              <!-- Hành động nhanh khi hover/đang chọn — mẫu: Dùng mẫu · lịch sử: Tải xuống + Dùng lại -->
              @if (it.kind === 'mau') {
                <div class="ri-acts">
                  <button type="button" class="mini p" (click)="useTemplate(it, $event)">
                    <tabler-icon [icon]="icDl" [size]="11" /> Dùng mẫu</button>
                </div>
              } @else if (it.kind === 'hist') {
                <div class="ri-acts">
                  <button type="button" class="mini" (click)="download(it, $event)">
                    <tabler-icon [icon]="icDl" [size]="11" /> Tải xuống</button>
                  <button type="button" class="mini p" (click)="reuse(it, $event)">
                    <tabler-icon [icon]="icRf" [size]="11" /> Dùng lại</button>
                </div>
              }
            </div>
            <!-- Badge loại chỉ ở chế độ "Tất cả" — khi đã lọc theo loại thì badge thừa (mockup màn 02/07) -->
            @if (store.railFilter() === 'all') {
              <span class="bdg" [class.b-mau]="it.kind === 'mau'"
                [class.b-lich]="it.kind === 'lich'" [class.b-hist]="it.kind === 'hist'">{{ bdgLabel[it.kind] }}</span>
            }
            <!-- Kebab ⋯ (AP-05): quản trị hiếm dùng gom một chỗ, xóa tách riêng màu đỏ -->
            @if (it.kind !== 'hist') {
              <button type="button" class="ri-keb" aria-label="Mở menu quản trị"
                (click)="toggleKebab(it, $event)">
                <tabler-icon [icon]="icDots" [size]="14" />
              </button>
              @if (kebabFor() === key(it)) {
                <div class="menu" (click)="$event.stopPropagation()">
                  @if (it.kind === 'mau') {
                    <button type="button" class="mi" (click)="setDefault(it, $event)">
                      <tabler-icon [icon]="icStar" [size]="14" /> Đặt làm mặc định</button>
                    <button type="button" class="mi" (click)="editItem(it, $event)">
                      <tabler-icon [icon]="icPencil" [size]="14" /> Chỉnh sửa</button>
                    <button type="button" class="mi" (click)="duplicateTpl(it, $event)">
                      <tabler-icon [icon]="icCopy" [size]="14" /> Sao chép</button>
                    <button type="button" class="mi" (click)="openRename(it, $event)">
                      <tabler-icon [icon]="icPencil" [size]="14" /> Đổi tên</button>
                    <div class="msep"></div>
                    @if (confirmDel() === key(it)) {
                      <!-- Confirm 2 bước TẠI CHỖ (Contract §4) — nền error-bg, không popconfirm chồng lớp -->
                      <div class="del-strip">
                        <span>Xóa mẫu?</span>
                        <button type="button" class="del-yes" (click)="doDelete(it, $event)">Xóa</button>
                        <button type="button" class="del-no" (click)="cancelDelete($event)">Hủy</button>
                      </div>
                    } @else {
                      <button type="button" class="mi danger" (click)="askDelete(it, $event)">
                        <tabler-icon [icon]="icTrash" [size]="14" /> Xóa mẫu</button>
                    }
                  } @else {
                    <button type="button" class="mi" (click)="runNow(it, $event)">
                      <tabler-icon [icon]="icPlay" [size]="14" /> Chạy ngay</button>
                    <button type="button" class="mi" (click)="editItem(it, $event)">
                      <tabler-icon [icon]="icPencil" [size]="14" /> Chỉnh sửa</button>
                    <button type="button" class="mi" (click)="togglePause(it, $event)">
                      <tabler-icon [icon]="it.active ? icPause : icPlay" [size]="14" />
                      {{ it.active ? 'Tạm dừng' : 'Kích hoạt lại' }}</button>
                    <button type="button" class="mi" (click)="duplicateSched(it, $event)">
                      <tabler-icon [icon]="icCopy" [size]="14" /> Nhân bản</button>
                    <div class="msep"></div>
                    @if (confirmDel() === key(it)) {
                      <div class="del-strip">
                        <span>Xóa lịch?</span>
                        <button type="button" class="del-yes" (click)="doDelete(it, $event)">Xóa</button>
                        <button type="button" class="del-no" (click)="cancelDelete($event)">Hủy</button>
                      </div>
                    } @else {
                      <button type="button" class="mi danger" (click)="askDelete(it, $event)">
                        <tabler-icon [icon]="icTrash" [size]="14" /> Xóa lịch</button>
                    }
                  }
                </div>
              }
            }
          </div>
        }
      }

      <!-- Empty states — không chỉ nói "trống": bán giá trị + CTA hành động ngay trên cấu hình đang mở -->
      @if (emptyKind() === 'mau') {
        <div class="rl-empty">
          <hrm-empty description="Chưa có mẫu nào" [image]="empIcMau" [action]="empActMau" />
        </div>
      } @else if (emptyKind() === 'lich') {
        <div class="rl-empty">
          <hrm-empty description="Chưa có lịch xuất nào" [image]="empIcLich" [action]="empActLich" />
        </div>
      } @else if (emptyKind() === 'search') {
        <div class="rl-empty">
          <hrm-empty preset="no-results" description="Không tìm thấy kết quả phù hợp" />
        </div>
      }
    </div>

    <!-- Footer đổi theo ngữ cảnh lọc (mockup 01/02/07) — mặc định: đường vào Lịch sử -->
    <div class="rl-foot">
      @switch (store.railFilter()) {
        @case ('mau') {
          <button type="button" class="lnk" (click)="store.saveModalOpen.set(true)">+ Lưu cấu hình hiện tại thành mẫu mới</button>
        }
        @case ('lich') {
          <button type="button" class="lnk" (click)="store.createSchedModalOpen.set(true)">+ Tạo lịch xuất mới</button>
        }
        @default {
          <button type="button" class="lnk" (click)="store.railFilter.set('hist')">Xem tất cả lịch sử →</button>
        }
      }
    </div>
    }

    <!-- Backdrop đóng kebab — 1 lớp trong drawer, không overlay hệ thống -->
    @if (kebabFor()) { <div class="keb-back" (click)="kebabFor.set(null)"></div> }

    <!-- Template cho hrm-empty tùy biến (icon đĩa tròn + mô tả + CTA) -->
    <ng-template #empIcMau><span class="e-ic"><tabler-icon [icon]="icStar" [size]="22" /></span></ng-template>
    <ng-template #empActMau>
      <div class="e-s">Cấu hình một lần, lưu thành mẫu — lần xuất sau chỉ còn 1 cú nhấp. Mẫu đặt ★ mặc định sẽ tự nạp mỗi khi mở.</div>
      <hrm-button variant="primary" size="sm" (click)="store.saveModalOpen.set(true)">Lưu cấu hình hiện tại thành mẫu</hrm-button>
    </ng-template>
    <ng-template #empIcLich><span class="e-ic"><tabler-icon [icon]="icClock" [size]="22" /></span></ng-template>
    <ng-template #empActLich>
      <div class="e-s">Đặt lịch để hệ thống tự tạo file và gửi người nhận đúng hẹn — báo cáo thứ Hai không cần nhớ nữa.</div>
      <hrm-button variant="primary" size="sm" (click)="store.schedOpen.set(true)">Tạo lịch từ cấu hình hiện tại</hrm-button>
    </ng-template>

    <!-- Modal đổi tên mẫu (mở qua HrmModalService — 1 lớp overlay duy nhất trên drawer) -->
    <ng-template #renameTpl>
      <hrm-input [ngModel]="renameVal()" (ngModelChange)="renameVal.set($event)" placeholder="Tên mẫu" />
    </ng-template>
  `,
  styles: [`
:host{display:flex;flex-direction:column;width:268px;flex:none;min-height:0;height:100%;
  background:var(--bg-surface-subtle);border-right:1px solid var(--border-sub)}
.num{font-family:var(--font-mono);font-variant-numeric:tabular-nums}

/* ── Search ── */
.rl-search{position:relative;margin:var(--space-3) var(--space-3) var(--space-2)}
.rl-search .kbd{position:absolute;right:9px;top:50%;transform:translateY(-50%);z-index:1;pointer-events:none;
  font-family:var(--font-mono);font-size:var(--fs-11);border:1px solid var(--border-sub);
  border-radius:var(--radius-xs);padding:1px 5px;color:var(--text-soft);background:var(--bg-surface-subtle)}
/* chừa chỗ cho kbd hint bên phải trong ô input */
.rl-search ::ng-deep .ant-input-affix-wrapper{padding-right:64px;background:var(--bg-surface)}

/* ── Chip lọc loại ── */
.rl-chips{display:flex;gap:6px;padding:2px var(--space-3) var(--space-2);flex-wrap:wrap}
.rl-chip{font-size:var(--fs-11);padding:3px 10px;border-radius:var(--radius-full);cursor:pointer;
  border:1px solid var(--border-sub);background:var(--bg-surface);color:var(--text-sub);font-weight:500}
.rl-chip.on{background:var(--primary-bg-subtle);border-color:var(--primary-border);color:var(--primary-base)}

/* ── List + nhóm ── */
.rl-list{flex:1;overflow-y:auto;padding:0 var(--space-2) var(--space-2);min-height:0}
.rl-h{font-size:var(--fs-11);letter-spacing:.8px;text-transform:uppercase;color:var(--text-soft);
  font-weight:600;padding:10px 6px 6px}

/* ── Item ── */
.ri{display:flex;gap:9px;padding:9px var(--space-2);border-radius:var(--radius-md);
  align-items:flex-start;position:relative;cursor:pointer}
.ri:hover{background:var(--bg-surface)}
.ri.on{background:var(--bg-surface);box-shadow:inset 0 0 0 1px var(--primary-border),var(--shadow-regular-xs)}
/* item vừa tạo (xuất xong/lịch mới) — nổi tông success như mockup màn 12/13 */
.ri.fresh{background:var(--success-bg);box-shadow:inset 0 0 0 1px var(--success-border)}
.ri-ic{width:28px;height:28px;border-radius:var(--radius-sm);flex:none;
  display:flex;align-items:center;justify-content:center}
.ri-ic.t-mau{background:var(--primary-bg-subtle);color:var(--primary-base)}
.ri-ic.t-lich{background:var(--success-bg);color:var(--success-base)}
.ri-ic.t-hist{background:var(--bg-surface-muted);color:var(--text-sub)}
.ri-ic.t-new{background:var(--success-bg);color:var(--success-base)}
.ri-m{flex:1;min-width:0}
.ri-t{font-size:var(--fs-13);font-weight:500;color:var(--text-strong);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ri-t .pin{color:var(--warning-base);font-size:var(--fs-11)}
.ri-s{font-size:var(--fs-11);color:var(--text-sub);margin-top:2px;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ri-s b{font-weight:500;font-size:var(--fs-11)}

/* trạng thái lịch — luôn render 2 chiều (AP-01) */
.sdot{display:inline-flex;align-items:center;gap:5px;font-size:var(--fs-11);font-weight:500}
.sdot::before{content:'';width:7px;height:7px;border-radius:var(--radius-full)}
.sdot.act{color:var(--success-text)}
.sdot.act::before{background:var(--success-base)}
.sdot.paused{color:var(--text-soft)}
.sdot.paused::before{background:var(--text-soft)}

/* badge loại nguồn */
.bdg{font-size:var(--fs-10);font-weight:600;letter-spacing:.3px;padding:2px 7px;
  border-radius:var(--radius-full);flex:none;margin-top:1px}
.bdg.b-mau{background:var(--primary-bg-subtle);color:var(--primary-base)}
.bdg.b-lich{background:var(--success-bg);color:var(--success-text)}
.bdg.b-hist{background:var(--bg-surface-muted);color:var(--text-sub)}

/* hành động nhanh — chỉ hiện khi hover hoặc item đang chọn; 2 nút cùng 1 hàng, không ép xuống dòng */
.ri-acts{display:none;gap:6px;margin-top:7px;flex-wrap:nowrap}
.ri:hover .ri-acts,.ri.on .ri-acts{display:flex}
.mini{font-size:var(--fs-11);font-weight:500;padding:3px 9px;border-radius:var(--radius-sm);cursor:pointer;
  border:1px solid var(--border-sub);background:var(--bg-surface);color:var(--text-body);
  display:inline-flex;gap:4px;align-items:center;white-space:nowrap}
.mini.p{background:var(--primary-base);border-color:var(--primary-base);color:var(--text-on-primary)}
.mini.p:hover{background:var(--primary-hover)}

/* kebab — hover mới hiện; badge nhường chỗ khi hover item có kebab */
.ri-keb{position:absolute;top:8px;right:6px;width:22px;height:22px;border:none;background:transparent;
  color:var(--text-soft);border-radius:var(--radius-sm);display:none;align-items:center;
  justify-content:center;cursor:pointer}
.ri:hover .ri-keb,.ri.keb-open .ri-keb{display:flex}
.ri-keb:hover{background:var(--bg-surface-subtle)}
.ri.keb-open .ri-keb{background:var(--bg-surface-muted)}
.ri.has-keb:hover .bdg,.ri.keb-open .bdg{display:none}

/* menu kebab tự dựng theo mockup */
.menu{position:absolute;top:32px;right:6px;background:var(--bg-surface);border:1px solid var(--border-sub);
  border-radius:var(--radius-lg);box-shadow:var(--shadow-regular-md);padding:5px;min-width:172px;z-index:21}
.mi{display:flex;align-items:center;gap:9px;font-size:var(--fs-13);color:var(--text-body);width:100%;
  padding:7px 10px;border-radius:var(--radius-sm);white-space:nowrap;border:none;background:transparent;
  cursor:pointer;text-align:left}
.mi:hover{background:var(--bg-surface-subtle);color:var(--text-strong)}
.mi.danger{color:var(--error-base)}
.mi.danger:hover{background:var(--error-bg)}
.msep{height:1px;background:var(--border-soft);margin:4px 6px}
.keb-back{position:fixed;inset:0;z-index:20;background:transparent}

/* empty state trong rail */
.rl-empty{padding:var(--space-4) var(--space-2)}
.e-ic{display:inline-flex;width:52px;height:52px;border-radius:var(--radius-full);
  background:var(--bg-surface-muted);color:var(--text-soft);align-items:center;justify-content:center}
.e-s{font-size:var(--fs-11);color:var(--text-sub);line-height:1.55;max-width:210px;
  margin:0 auto var(--space-2);text-align:center}

/* footer */
.rl-foot{padding:10px var(--space-3);border-top:1px solid var(--border-sub)}
.lnk{font-size:var(--fs-12);color:var(--primary-base);font-weight:500;border:none;background:transparent;
  cursor:pointer;padding:0}
.lnk:hover{text-decoration:underline}

/* confirm xóa TẠI CHỖ trong kebab (Contract §4) — nền error-bg, 2 bước, không overlay chồng lớp */
.del-strip{display:flex;align-items:center;gap:8px;background:var(--error-bg);border:1px solid var(--error-border);
  border-radius:var(--radius-sm);padding:6px 8px;margin:2px;font-size:var(--fs-12);color:var(--error-text)}
.del-strip span{flex:1;white-space:nowrap;font-weight:500}
.del-yes{border:none;background:var(--error-base);color:var(--text-on-primary);font-size:var(--fs-11);
  font-weight:600;padding:3px 10px;border-radius:var(--radius-sm);cursor:pointer}
.del-no{border:none;background:transparent;color:var(--text-sub);font-size:var(--fs-11);padding:3px 8px;cursor:pointer}
.del-no:hover{color:var(--text-strong)}

/* ≤1280px: rail thu gọn thành icon-strip (Contract §2) — chỉ còn ô icon, click vẫn hydrate */
@media (max-width:1280px){
  :host{width:56px}
  .rl-search,.rl-chips,.rl-foot,.rl-h,.ri-m,.bdg{display:none}
  .ri-keb,.ri:hover .ri-keb,.ri.keb-open .ri-keb{display:none}
  .rl-list{padding:var(--space-2) 6px}
  .ri{justify-content:center;padding:7px 0}
}
  `],
})
export class EcRail {
  protected readonly store = inject(ExportCenterStore);
  private readonly modal = inject(HrmModalService);
  /** Xác nhận thay-đổi-trạng-thái (tạo/nhân bản) → toast (tone khớp store). */
  private readonly toast = inject(HrmToastService);
  /** CHỈ dùng cho thông báo loading/tiến trình (vd "Đang tải xuống…") — KHÔNG cho state-change. */
  private readonly msg = inject(HrmMessageService);
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);

  /* Icons (Tabler object mode) */
  protected readonly icSearch = IconSearch;
  protected readonly icFileText = IconFileText;
  protected readonly icStar = IconStar;
  protected readonly icClock = IconClock;
  protected readonly icDl = IconDownload;
  protected readonly icRf = IconRefresh;
  protected readonly icDots = IconDots;
  protected readonly icPencil = IconPencil;
  protected readonly icCopy = IconCopy;
  protected readonly icTrash = IconTrash;
  protected readonly icPlay = IconPlayerPlay;
  protected readonly icPause = IconPlayerPause;

  protected readonly chips: { v: EcRailFilter; l: string }[] = [
    { v: 'all', l: 'Tất cả' }, { v: 'mau', l: 'Mẫu' }, { v: 'lich', l: 'Lịch' }, { v: 'hist', l: 'Lịch sử' },
  ];
  protected readonly bdgLabel: Record<EcRailItem['kind'], string> = { mau: 'Mẫu', lich: 'Lịch', hist: 'Lịch sử' };

  /** Kebab đang mở cho item nào (key kind:id) — chỉ 1 menu tại một thời điểm. */
  protected readonly kebabFor = signal<string | null>(null);
  /** Bước confirm xóa TẠI CHỖ đang mở cho item nào (key kind:id) — Contract §4. */
  protected readonly confirmDel = signal<string | null>(null);

  /** Guard 2-Enter: Enter① nạp item đầu (tóm tắt kịp vào mắt), Enter② thực thi CTA của nguồn đã nạp. */
  private enterArmed: EcRailItem | null = null;

  /* Modal đổi tên */
  private readonly renameTpl = viewChild.required<TemplateRef<void>>('renameTpl');
  protected readonly renameVal = signal('');
  private renameId = '';
  /** Đếm id bản sao lịch — deterministic, không Math.random (zoneless). */
  private copySeq = 0;
  /** Đếm id mẫu văn bản tạo mới từ footer rail (tab doc). */
  private docSeq = 0;

  constructor() {
    // Search focus mặc định (spec §2) — đường bàn phím bắt đầu ngay khi mở drawer.
    afterNextRender(() => {
      this.host.nativeElement.querySelector<HTMLInputElement>('.rl-search input')?.focus();
    });
  }

  /** Placeholder đổi theo chip lọc (mockup màn 01/02/07/08). */
  protected readonly searchPh = computed(() => {
    switch (this.store.railFilter()) {
      case 'mau': return 'Tìm mẫu…';
      case 'lich': return 'Tìm lịch xuất…';
      case 'hist': return 'Tìm trong lịch sử…';
      default: return 'Tìm mẫu, lịch, lịch sử…';
    }
  });

  /** Danh sách mẫu văn bản cho rail ở tab "Văn bản theo mẫu" — lọc theo cùng ô tìm kiếm. */
  protected readonly docItems = computed<EcDocTemplate[]>(() => {
    const q = this.store.railQuery().trim().toLowerCase();
    return this.store.docTemplates().filter((d) => !q || d.ten.toLowerCase().includes(q));
  });

  /** Nhóm hiển thị theo ngữ cảnh lọc: all='Vừa xong'/'Dùng gần nhất' · mẫu/lịch=đếm N · hist=theo ngày. */
  protected readonly groups = computed<{ header: string; count?: number; items: EcRailItem[] }[]>(() => {
    const items = this.store.railItems();
    const f = this.store.railFilter();
    if (!items.length) return [];
    // count tách khỏi header → template render số bằng .num (font-mono, AP-03).
    if (f === 'mau') return [{ header: 'Mẫu của tôi', count: items.length, items }];
    if (f === 'lich') return [{ header: 'Lịch xuất', count: items.length, items }];
    if (f === 'hist') {
      const homNay = items.filter((i) => this.isTodayHist(i));
      const truoc = items.filter((i) => !this.isTodayHist(i));
      const g: { header: string; count?: number; items: EcRailItem[] }[] = [];
      if (homNay.length) g.push({ header: 'Hôm nay', items: homNay });
      if (truoc.length) g.push({ header: 'Tuần này', items: truoc });
      return g;
    }
    // 'all': item vừa tạo runtime tách nhóm "Vừa xong" (mockup màn 12/13) — vòng lặp tái dùng khép kín.
    const moi = items.filter((i) => this.isNew(i));
    const rest = items.filter((i) => !this.isNew(i));
    const g: { header: string; count?: number; items: EcRailItem[] }[] = [];
    if (moi.length) g.push({ header: 'Vừa xong', items: moi });
    if (rest.length) g.push({ header: 'Dùng gần nhất', items: rest });
    return g;
  });

  /** Empty theo scenario + filter (màn 14/15); còn lại = không khớp tìm kiếm. */
  protected readonly emptyKind = computed<'mau' | 'lich' | 'search' | null>(() => {
    if (this.store.railItems().length) return null;
    if (this.store.railFilter() === 'mau' && this.store.scenario() === 'no-templates') return 'mau';
    if (this.store.railFilter() === 'lich' && this.store.scenario() === 'no-schedules') return 'lich';
    return 'search';
  });

  /* ── Helpers ── */

  protected key(it: EcRailItem): string { return it.kind + ':' + it.id; }

  /** Item .on khi trùng nguồn đang nạp trên canvas. */
  protected isOn(it: EcRailItem): boolean {
    const s = this.store.source();
    return !!s && s.kind === it.kind && s.id === it.id;
  }

  /** Vừa tạo trong phiên (xuất xong / lịch mới) — tô success + icon tick. */
  protected isNew(it: EcRailItem): boolean {
    if (it.kind === 'hist') return !!this.store.history().find((h) => h.id === it.id)?.moi;
    if (it.kind === 'lich') return this.store.lastSchedule()?.id === it.id;
    return false;
  }

  private isTodayHist(it: EcRailItem): boolean {
    const at = this.store.history().find((h) => h.id === it.id)?.at ?? '';
    return at.startsWith('Hôm nay') || at.startsWith('Vừa xong');
  }

  protected icFor(it: EcRailItem): unknown {
    if (this.isNew(it)) return IconCheck;
    if (it.kind === 'mau') return it.macDinh ? IconStar : IconFileText;
    if (it.kind === 'lich') return IconCalendar;
    return IconClock;
  }

  /** Tách số đếm đầu meta để render mono tabular-nums (AP-03) — phần còn lại giữ nguyên. */
  protected metaParts(it: EcRailItem): { num: string; rest: string } {
    const m = /^([\d.,]+)\s(.*)$/.exec(it.meta);
    return m ? { num: m[1], rest: m[2] } : { num: '', rest: it.meta };
  }

  /* ── Search: type-ahead + guard 2-Enter ── */

  protected onQuery(q: string): void {
    this.store.railQuery.set(q);
    this.enterArmed = null; // đổi query → vòng Enter mới, không thực thi nhầm
  }

  protected onEnter(ev: Event): void {
    ev.preventDefault();
    // Tab văn bản: Enter nạp mẫu văn bản đầu tiên khớp tìm kiếm.
    if (this.store.segTab() === 'doc') {
      const first = this.docItems()[0];
      if (first) this.pickDoc(first.id);
      return;
    }
    // Hàng RENDER đầu tiên (nhóm "Vừa xong" hoist lên trên) — không phải railItems()[0] thô.
    const rendered = this.groups()[0]?.items[0] ?? this.store.railItems()[0];
    // Enter② chỉ thực thi khi armed CÒN hiển thị (đổi chip/tab có thể lọc nó ra) — nếu không, coi như Enter①.
    const armedStillShown = this.enterArmed
      && this.store.railItems().some((x) => this.key(x) === this.key(this.enterArmed!));
    if (!armedStillShown) {
      if (!rendered) return;
      this.pick(rendered);
      this.enterArmed = rendered; // Enter② thực thi CTA tương ứng nguồn vừa nạp
    } else {
      const armed = this.enterArmed!;
      this.enterArmed = null;
      // Contract recipe: Enter② = CTA primary ĐANG hiển thị — nguồn lịch là "Chạy ngay", còn lại là Xuất.
      if (armed.kind === 'lich') this.store.runScheduleNow(armed.id);
      else this.store.exportNow();
    }
  }

  protected setFilter(v: EcRailFilter): void {
    this.store.railFilter.set(v);
    this.kebabFor.set(null);
    this.enterArmed = null; // đổi chip lọc → vòng Enter mới (armed cũ có thể đã bị lọc ra)
  }

  /* ── Hydrate (click item → canvas) ── */

  protected pick(it: EcRailItem): void {
    this.kebabFor.set(null);
    if (it.kind === 'mau') this.store.hydrateTemplate(it.id);
    else if (it.kind === 'lich') this.store.hydrateSchedule(it.id);
    else this.store.hydrateHistory(it.id);
  }

  /** Chọn mẫu văn bản (tab doc): đổi selectedDocId + về tab Soạn thảo — không đụng canvas Bảng. */
  protected pickDoc(id: string): void {
    this.store.selectedDocId.set(id);
    this.store.docTab.set('edit');
  }

  /** Footer tab doc: tạo mẫu văn bản mới (demo) — nổi lên đầu danh sách + mở soạn ngay. */
  protected addDocTemplate(): void {
    const d: EcDocTemplate = {
      id: 'doc-r' + ++this.docSeq, ten: 'Mẫu văn bản mới', soTruong: 1, format: 'word',
      capNhat: EC_TODAY, body: 'TIÊU ĐỀ VĂN BẢN\n\nHọ tên: {{name}}',
    };
    this.store.docTemplates.update((l) => [d, ...l]);
    this.pickDoc(d.id);
    // Tạo mẫu mới = thay-đổi-trạng-thái (twin của saveTemplate → success) → toast success.
    this.toast.success('Đã tạo mẫu văn bản mới', '"' + d.ten + '" — mở soạn ngay');
  }

  protected useTemplate(it: EcRailItem, ev: Event): void {
    ev.stopPropagation();
    this.store.hydrateTemplate(it.id);
  }

  protected reuse(it: EcRailItem, ev: Event): void {
    ev.stopPropagation();
    this.store.reuseHistory(it.id);
  }

  protected download(it: EcRailItem, ev: Event): void {
    ev.stopPropagation();
    // Ranh giới có chủ đích: đây là thông báo LOADING/tiến trình (không phải xác nhận state-change),
    // nên dùng HrmMessageService (dòng giữa-trên), KHÔNG dùng toast.
    this.msg.success('Đang tải xuống "' + it.ten + '"…');
  }

  /* ── Kebab ── */

  protected toggleKebab(it: EcRailItem, ev: Event): void {
    ev.stopPropagation();
    this.confirmDel.set(null);
    this.kebabFor.update((k) => (k === this.key(it) ? null : this.key(it)));
  }

  private closeKebab(ev: Event): void {
    ev.stopPropagation();
    this.kebabFor.set(null);
  }

  protected setDefault(it: EcRailItem, ev: Event): void {
    this.closeKebab(ev);
    this.store.setDefaultTemplate(it.id);
  }

  /** "Chỉnh sửa" = nạp vào canvas để sửa tại chỗ — không màn chi tiết riêng (round-trip = 0). */
  protected editItem(it: EcRailItem, ev: Event): void {
    this.closeKebab(ev);
    this.pick(it);
  }

  protected duplicateTpl(it: EcRailItem, ev: Event): void {
    this.closeKebab(ev);
    this.store.duplicateTemplate(it.id);
  }

  protected runNow(it: EcRailItem, ev: Event): void {
    this.closeKebab(ev);
    this.store.runScheduleNow(it.id);
  }

  protected togglePause(it: EcRailItem, ev: Event): void {
    this.closeKebab(ev);
    this.store.toggleScheduleActive(it.id);
  }

  /** Nhân bản lịch — bản sao tạm dừng lần chạy cũ, nổi lên đầu rail (recency). */
  protected duplicateSched(it: EcRailItem, ev: Event): void {
    this.closeKebab(ev);
    const s = this.store.schedules().find((x) => x.id === it.id);
    if (!s) return;
    // Bản sao TẠM DỪNG (active:false, lanKe '—') — không tự bắn trùng lịch gốc; user tự bật lại.
    const copy: EcSchedule = { ...s, id: 'sch-c' + ++this.copySeq, ten: s.ten + ' (bản sao)', active: false, lanKe: '—', nguoiNhan: [...s.nguoiNhan], lanChay: [] };
    this.store.schedules.update((l) => [copy, ...l]);
    // Nhân bản lịch = twin của duplicateTemplate (store dùng neutral) → toast neutral, KHÔNG message.
    this.toast.neutral('Đã nhân bản lịch', '"' + s.ten + '" — bản sao đang tạm dừng');
  }

  /* ── Xóa: confirm 2 bước TẠI CHỖ trong kebab (Contract §4 — nền --error-bg, không modal chồng lớp) ── */

  protected askDelete(it: EcRailItem, ev: Event): void {
    ev.stopPropagation();
    this.confirmDel.set(this.key(it));
  }

  protected cancelDelete(ev: Event): void {
    ev.stopPropagation();
    this.confirmDel.set(null);
  }

  protected doDelete(it: EcRailItem, ev: Event): void {
    ev.stopPropagation();
    this.confirmDel.set(null);
    this.kebabFor.set(null);
    if (it.kind === 'mau') this.store.deleteTemplate(it.id);
    else this.store.deleteSchedule(it.id);
  }

  /* ── Đổi tên mẫu ── */

  protected openRename(it: EcRailItem, ev: Event): void {
    this.closeKebab(ev);
    this.renameId = it.id;
    this.renameVal.set(it.ten);
    const ref = this.modal.open({
      title: 'Đổi tên mẫu', content: this.renameTpl(), width: 420,
      footer: [
        { label: 'Hủy', onClick: () => ref.close() },
        { label: 'Đổi tên', type: 'primary', onClick: () => { this.applyRename(); ref.close(); } },
      ],
    });
  }

  private applyRename(): void {
    const ten = this.renameVal().trim();
    if (!ten) return;
    // Cascade tên sang nguồn + lịch liên kết được xử lý trong store.renameTemplate (chống nạp nhầm cột).
    this.store.renameTemplate(this.renameId, ten);
  }
}
