import { ChangeDetectionStrategy, Component, computed, effect, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  HrmAlert, HrmButton, HrmCheckbox, HrmInput, HrmOption, HrmSegmented, HrmSelect,
  HrmTag, HrmTextarea, HrmTimePicker, HrmToastService,
} from 'hrm-ui';
import {
  TablerIconComponent, IconClock, IconDownload, IconPencil, IconPlayerPause, IconPlayerPlay,
  IconRefresh, IconSparkles, IconStar, IconX,
} from '@tabler/icons-angular';
import {
  EC_FORMAT_LABEL, EC_FORMAT_SHORT, EC_NEXT_RUN, EC_TODAY, EcAiPlan, EcDocTemplate, EcFormat, EcSchedule,
  ExportCenterStore, ecNhipLabel,
} from './_export-data';

/** ═════════ EC-DOCK — DOCK PHẢI 300px sticky (mockup màn 01/05/07/08/09) + 2 modal (màn 03/06) ═════════
 *  Bất biến hợp đồng thiết kế: khối TÓM TẮT không bao giờ bị che — mode "Đặt lịch" chỉ MỞ THÊM
 *  dải field phía trên (dock morph, không modal thứ hai); cảnh báo nhạy cảm thường trực cạnh CTA.
 *  Modal "Lưu thành mẫu" + "Tạo lịch xuất" dựng overlay tự chứa (đúng 1 lớp trên drawer — P4). */
@Component({
  selector: 'ec-dock',
  imports: [
    FormsModule, HrmAlert, HrmButton, HrmCheckbox, HrmInput, HrmSegmented, HrmSelect, HrmTag,
    HrmTextarea, HrmTimePicker, TablerIconComponent,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (store.segTab() === 'table') {
      <!-- ─── Nguồn cấu hình (pre-hydrate tường minh — nguồn ghi rõ cạnh CTA) ─── -->
      <div class="dk-src">
        <span>{{ srcKindLabel() }}</span>
        <b>
          {{ srcName() }}
          @if (srcIsDefault()) { <span class="pin">★ mặc định</span> }
        </b>
      </div>

      <!-- Chip mời lưu (mockup màn 08): cấu hình thô từ lịch sử / thủ công — trung tính, KHÔNG đụng dirty -->
      @if (store.suggestSaveTemplate()) {
        <div class="savehint">chưa lưu thành mẫu · <button type="button" (click)="openSaveModal()">+ Lưu</button></div>
      }

      <!-- Dirty-chip chống cry-wolf: chỉ hiện khi lệch baseline (không tính filter sống) -->
      @if (store.dirtyCount() > 0) {
        <div class="dirty">
          <span class="dot"></span>
          <span>đã chỉnh <b class="num">{{ store.dirtyCount() }}</b> mục</span>
          <button type="button" (click)="store.resetToBaseline()">Hoàn tác</button>
          <span class="sep">·</span>
          <button type="button" (click)="openSaveModal()">+ Lưu mẫu mới</button>
        </div>
      }

      <!-- ─── DOCK MORPH: dải đặt lịch mở TRÊN tóm tắt — tóm tắt vẫn hiện (màn 05) ─── -->
      @if (store.schedOpen()) {
        <div class="sched">
          <div class="sched-t"><tabler-icon [icon]="iClock" [size]="14" /> {{ editingScheduleId() ? 'Chỉnh sửa lịch xuất' : 'Đặt lịch cho cấu hình này' }}</div>
          <div class="f-l">Tần suất</div>
          <hrm-segmented size="sm" [block]="true" [options]="tanSuatOptions"
            [ngModel]="schTanSuat()" (ngModelChange)="schTanSuat.set($event)" />
          @if (schTanSuat() === 'ngay') {
            <div class="f-l">Thời gian</div>
            <hrm-time-picker size="sm" [minuteStep]="15"
              [ngModel]="schGio()" (ngModelChange)="schGio.set($event)" />
          } @else {
            <div class="f-2">
              <div>
                <div class="f-l">{{ schTanSuat() === 'tuan' ? 'Thứ' : 'Ngày' }}</div>
                @if (schTanSuat() === 'tuan') {
                  <hrm-select size="sm" [options]="thuOptions" [allowClear]="false" [showSearch]="false"
                    [ngModel]="schThu()" (ngModelChange)="schThu.set($event)" />
                } @else {
                  <hrm-select size="sm" [options]="ngayOptions" [allowClear]="false" [showSearch]="false"
                    [ngModel]="schNgayThang()" (ngModelChange)="schNgayThang.set($event)" />
                }
              </div>
              <div>
                <div class="f-l">Thời gian</div>
                <hrm-time-picker size="sm" [minuteStep]="15"
                  [ngModel]="schGio()" (ngModelChange)="schGio.set($event)" />
              </div>
            </div>
          }
          <div class="f-l">Người nhận</div>
          @if (schNguoiNhan().length) {
            <div class="rcpt">
              @for (r of schNguoiNhan(); track r) {
                <hrm-tag color="blue" size="sm" [closeable]="true" (closed)="removeRcpt(r)">{{ r }}</hrm-tag>
              }
            </div>
          }
          <hrm-input size="sm" placeholder="+ Thêm… (Enter)"
            [ngModel]="schNewRcpt()" (ngModelChange)="schNewRcpt.set($event)" (keydown.enter)="addRcpt()" />
          <div class="f-l">Tên lịch xuất</div>
          <hrm-input size="sm" placeholder="VD: Báo cáo nhân sự hàng tuần"
            [ngModel]="schTen()" (ngModelChange)="schTen.set($event)" />
          <div class="f-ck"><hrm-checkbox [ngModel]="schMailReady()" (ngModelChange)="schMailReady.set(!!$event)">Gửi email khi file sẵn sàng</hrm-checkbox></div>
          <div class="f-ck"><hrm-checkbox [ngModel]="schMailChanged()" (ngModelChange)="schMailChanged.set(!!$event)">Chỉ gửi khi dữ liệu thay đổi</hrm-checkbox></div>
        </div>
      }

      <!-- ─── TÓM TẮT — bất biến, không mode nào che ─── -->
      @if (srcSchedule(); as s) {
        <!-- Nguồn là LỊCH (màn 07): Nhịp chạy + Người nhận + Nội dung -->
        <div class="dk-sum">
          <div class="dk-h">Nhịp chạy</div>
          <div class="dk-row"><span>Tần suất</span><b>{{ nhipFull(s) }}</b></div>
          <div class="dk-row"><span>Thời gian</span><b class="num">{{ s.gio }}</b></div>
          <div class="dk-row"><span>Lần kế tiếp</span><b class="num">{{ s.lanKe }}</b></div>
          <div class="dk-row"><span>Trạng thái</span>
            <b><span class="sdot" [class.act]="s.active" [class.off]="!s.active">{{ s.active ? 'Đang hoạt động' : 'Tạm dừng' }}</span></b></div>
        </div>
        <div class="dk-sum">
          <div class="dk-h">Người nhận</div>
          @for (r of s.nguoiNhan; track r) {
            <div class="dk-row"><span>{{ r }}</span><b class="soft">{{ rcptKind(r) }}</b></div>
          }
        </div>
        <div class="dk-sum">
          <div class="dk-h">Nội dung</div>
          <div class="dk-row"><span>Số dòng (hiện tại)</span><b class="num">{{ rowCountLabel() }}</b></div>
          <div class="dk-row"><span>Cột</span><b class="num">{{ store.summary().soCot }}/{{ store.summary().tongCot }}</b></div>
          <div class="dk-row"><span>Định dạng</span><b>{{ store.summary().dinhDang }}</b></div>
        </div>
      } @else {
        <div class="dk-sum">
          <div class="dk-h">Tóm tắt</div>
          <div class="dk-row"><span>Số dòng</span><b class="num">{{ rowCountLabel() }}</b></div>
          <div class="dk-row"><span>Cột xuất</span><b class="num">{{ store.summary().soCot }}/{{ store.summary().tongCot }}</b></div>
          <div class="dk-row"><span>Định dạng</span><b>{{ store.summary().dinhDang }}</b></div>
          <div class="dk-row"><span>Phạm vi</span><b>{{ store.summary().phamVi }}</b></div>
          @if (store.scope() === 'filter') {
            <div class="dk-chips">
              @for (c of store.filterChips; track c.k) { <span class="chip">{{ c.v }}</span> }
            </div>
          }
        </div>
      }

      <!-- Cảnh báo nhạy cảm thường trực — điểm mắt bắt buộc đi qua trước CTA (soft = thẻ toast bám ẢNH 3, không closeable) -->
      <hrm-alert class="dk-alert" type="warning" appearance="soft" message="Dữ liệu nhạy cảm."
        description="File chứa thông tin nhân sự được phân quyền." />

      <!-- ─── CTA — primary duy nhất, count sống theo phạm vi ─── -->
      <div class="dk-cta">
        @if (store.schedOpen()) {
          <hrm-button variant="primary" [block]="true" [disabled]="!schTen().trim()" (click)="saveSchedule()">
            <tabler-icon [icon]="iClock" [size]="15" /> {{ editingScheduleId() ? 'Cập nhật lịch' : 'Lưu lịch xuất' }}
          </hrm-button>
          <hrm-button [block]="true" (click)="cancelSched()">{{ editingScheduleId() ? 'Hủy chỉnh sửa' : 'Hủy đặt lịch' }}</hrm-button>
          <div class="dk-note">Lịch chạy trên phạm vi "Theo bộ lọc" tại thời điểm chạy.</div>
        } @else if (srcSchedule(); as s) {
          <hrm-button variant="primary" [block]="true" (click)="store.runScheduleNow(s.id)">
            <tabler-icon [icon]="iPlay" [size]="15" /> Chạy ngay
          </hrm-button>
          <hrm-button [block]="true" (click)="editSchedule(s)">
            <tabler-icon [icon]="iPencil" [size]="14" /> Chỉnh sửa lịch
          </hrm-button>
          <hrm-button variant="text" [block]="true" (click)="store.toggleScheduleActive(s.id)">
            <tabler-icon [icon]="s.active ? iPause : iPlay" [size]="13" />
            {{ s.active ? 'Tạm dừng lịch' : 'Kích hoạt lịch' }}
          </hrm-button>
        } @else {
          <hrm-button variant="primary" [block]="true" [loading]="store.exporting()"
            [disabled]="store.rowCount() === 0" (click)="store.exportNow()">
            <tabler-icon [icon]="iDownload" [size]="15" /> Xuất <span class="num">{{ rowCountLabel() }}</span> dòng
          </hrm-button>
          <hrm-button [block]="true" (click)="openSchedMorph()">
            <tabler-icon [icon]="iClock" [size]="14" /> Đặt lịch xuất
          </hrm-button>
          <hrm-button variant="text" [block]="true" (click)="openSaveModal()">+ Lưu thành mẫu mới</hrm-button>
        }
      </div>
    } @else {
      <!-- ═══ Tab VĂN BẢN THEO MẪU (màn 09): tóm tắt đổi đơn vị đếm — phiếu/trường ═══ -->
      <div class="dk-src">
        <span>Mẫu văn bản</span>
        <b>{{ store.selectedDoc()?.ten ?? '—' }}</b>
      </div>
      <div class="dk-sum">
        <div class="dk-h">Tóm tắt</div>
        <div class="dk-row"><span>Nhân viên áp dụng</span><b class="num">{{ store.totalFilter }}</b></div>
        <div class="dk-row"><span>Phạm vi</span><b>Theo bộ lọc</b></div>
        <div class="dk-row"><span>Số văn bản tạo ra</span><b><span class="num">{{ store.totalFilter }}</span> phiếu</b></div>
        <div class="dk-row"><span>Trường dữ liệu</span><b class="num">{{ store.selectedDoc()?.soTruong ?? 0 }}</b></div>
        <div class="dk-row"><span>Định dạng</span><b>{{ docFormatLabel() }}</b></div>
      </div>
      <hrm-alert class="dk-alert" type="warning" appearance="soft" message="Dữ liệu nhạy cảm."
        description="Văn bản chứa thông tin nhân sự được phân quyền." />
      <div class="dk-cta">
        <hrm-button variant="primary" [block]="true" (click)="docDownload()">
          <tabler-icon [icon]="iDownload" [size]="15" /> Tải về {{ docFormatShort() }} (<span class="num">{{ store.totalFilter }}</span>)
        </hrm-button>
        <hrm-button [block]="true" (click)="docUpdate()">
          <tabler-icon [icon]="iRefresh" [size]="14" /> Cập nhật mẫu này
        </hrm-button>
        <!-- Cặp secondary/text của action hierarchy §4 (mockup màn 09/10) -->
        <hrm-button variant="text" [block]="true" (click)="docSaveAsNew()">+ Lưu thành mẫu mới</hrm-button>
      </div>
    }

    <!-- ═══ MODAL "Lưu thành mẫu" (màn 03) — đúng 1 lớp overlay trên drawer ═══ -->
    @if (store.saveModalOpen()) {
      <div class="mback" (click)="store.saveModalOpen.set(false)">
        <div class="modal" (click)="$event.stopPropagation()">
          <div class="mo-h">
            <span class="mo-ic"><tabler-icon [icon]="iStar" [size]="16" /></span>
            <h4>Lưu thành mẫu mới</h4>
            <button type="button" class="mo-x" (click)="store.saveModalOpen.set(false)"><tabler-icon [icon]="iX" [size]="15" /></button>
          </div>
          <div class="mo-b">
            <!-- B (autofill): AI suy Tên + Mô tả từ cấu hình hiện tại → CHỈ điền 2 ô, người dùng sửa được -->
            <div class="f-l f-l-ai">
              <span>Tên mẫu <span class="req">*</span></span>
              <button type="button" class="ai-hint" (click)="aiFillTemplateMeta()">
                <tabler-icon [icon]="iSparkles" [size]="13" /> Gợi ý
              </button>
            </div>
            <hrm-input placeholder="VD: Danh sách nhân viên tháng — bản rút gọn"
              [ngModel]="svTen()" (ngModelChange)="svTen.set($event)" />
            <div class="f-l">Mô tả <span class="opt">(tùy chọn)</span></div>
            <hrm-textarea [minRows]="2" [maxRows]="3" placeholder="Bộ cột này dùng cho việc gì, gửi ai…"
              [ngModel]="svMoTa()" (ngModelChange)="svMoTa.set($event)" />
            <div class="f-l">Nhóm mẫu</div>
            <hrm-select [options]="nhomOptions" [allowClear]="false" [showSearch]="false"
              [ngModel]="svNhom()" (ngModelChange)="svNhom.set($event)" />
            <div class="f-ck"><hrm-checkbox [ngModel]="svMacDinh()" (ngModelChange)="svMacDinh.set(!!$event)">Đặt làm mẫu mặc định (pre-hydrate khi mở Xuất dữ liệu)</hrm-checkbox></div>
            <!-- Ghi chú "bộ lọc là ngữ cảnh sống" — chặn hiểu nhầm mẫu đóng băng filter -->
            <div class="mo-note">
              Sẽ lưu: <b class="num">{{ store.summary().soCot }}/{{ store.summary().tongCot }}</b> cột ·
              {{ store.summary().dinhDang }} · phạm vi <b>{{ store.summary().phamVi }}</b>
              (bộ lọc là ngữ cảnh sống — không đóng băng vào mẫu).
            </div>
          </div>
          <div class="mo-f">
            <hrm-button (click)="store.saveModalOpen.set(false)">Hủy</hrm-button>
            <hrm-button variant="primary" [disabled]="!svTen().trim()" (click)="saveTemplate()">
              <tabler-icon [icon]="iStar" [size]="14" /> Lưu mẫu
            </hrm-button>
          </div>
        </div>
      </div>
    }

    <!-- ═══ MODAL "Tạo lịch xuất" đầy đủ (màn 06) — đường vào từ rail, chọn cấu hình nguồn ═══ -->
    @if (store.createSchedModalOpen()) {
      <div class="mback" (click)="store.createSchedModalOpen.set(false)">
        <div class="modal w560" (click)="$event.stopPropagation()">
          <div class="mo-h">
            <span class="mo-ic"><tabler-icon [icon]="iClock" [size]="16" /></span>
            <h4>Đặt lịch xuất dữ liệu</h4>
            <button type="button" class="mo-x" (click)="store.createSchedModalOpen.set(false)"><tabler-icon [icon]="iX" [size]="15" /></button>
          </div>
          <div class="mo-sub">Tự động tạo file theo lịch và gửi đến người nhận.</div>
          <div class="mo-b">
            <div class="f-l">Tên lịch xuất <span class="req">*</span></div>
            <hrm-input placeholder="VD: Báo cáo nhân sự hàng tuần"
              [ngModel]="schTen()" (ngModelChange)="schTen.set($event)" />
            <div class="f-2">
              <div class="wide">
                <div class="f-l">Dùng cấu hình</div>
                <hrm-select [options]="templateOptions()" [allowClear]="false" [showSearch]="false"
                  [ngModel]="csTemplateId()" (ngModelChange)="pickCsTemplate($event)" />
              </div>
              <div>
                <div class="f-l">Định dạng</div>
                <hrm-select [options]="formatOptions" [allowClear]="false" [showSearch]="false"
                  [ngModel]="csFormat()" (ngModelChange)="csFormat.set($event)" />
              </div>
            </div>
            <!-- Ghi chú phạm vi — lịch KHÔNG đóng băng 26 dòng, chạy trên dữ liệu mới nhất -->
            <div class="mo-note">
              Phạm vi của cấu hình: <b>Theo bộ lọc hiện tại</b> —
              <b class="num">{{ store.totalFilter }}</b> nhân viên tại thời điểm đặt · lịch chạy sẽ lấy dữ liệu mới nhất.
            </div>
            <div class="f-l">Tần suất</div>
            <hrm-segmented size="sm" [block]="true" [options]="tanSuatOptions"
              [ngModel]="schTanSuat()" (ngModelChange)="schTanSuat.set($event)" />
            @if (schTanSuat() === 'ngay') {
              <div class="f-l">Thời gian</div>
              <hrm-time-picker size="sm" [minuteStep]="15"
                [ngModel]="schGio()" (ngModelChange)="schGio.set($event)" />
            } @else {
              <div class="f-2">
                <div>
                  <div class="f-l">{{ schTanSuat() === 'tuan' ? 'Thứ' : 'Ngày' }}</div>
                  @if (schTanSuat() === 'tuan') {
                    <hrm-select size="sm" [options]="thuOptions" [allowClear]="false" [showSearch]="false"
                      [ngModel]="schThu()" (ngModelChange)="schThu.set($event)" />
                  } @else {
                    <hrm-select size="sm" [options]="ngayOptions" [allowClear]="false" [showSearch]="false"
                      [ngModel]="schNgayThang()" (ngModelChange)="schNgayThang.set($event)" />
                  }
                </div>
                <div>
                  <div class="f-l">Thời gian</div>
                  <hrm-time-picker size="sm" [minuteStep]="15"
                    [ngModel]="schGio()" (ngModelChange)="schGio.set($event)" />
                </div>
              </div>
            }
            <div class="f-l">Người nhận</div>
            @if (schNguoiNhan().length) {
              <div class="rcpt">
                @for (r of schNguoiNhan(); track r) {
                  <hrm-tag color="blue" size="sm" [closeable]="true" (closed)="removeRcpt(r)">{{ r }}</hrm-tag>
                }
              </div>
            }
            <hrm-input size="sm" placeholder="+ Thêm người trong hệ thống hoặc email… (Enter)"
              [ngModel]="schNewRcpt()" (ngModelChange)="schNewRcpt.set($event)" (keydown.enter)="addRcpt()" />
            <div class="f-ck"><hrm-checkbox [ngModel]="schMailReady()" (ngModelChange)="schMailReady.set(!!$event)">Gửi email khi file sẵn sàng</hrm-checkbox></div>
            <div class="f-ck"><hrm-checkbox [ngModel]="schMailChanged()" (ngModelChange)="schMailChanged.set(!!$event)">Chỉ gửi khi có dữ liệu thay đổi</hrm-checkbox></div>
          </div>
          <div class="mo-f">
            <hrm-button (click)="store.createSchedModalOpen.set(false)">Hủy</hrm-button>
            <hrm-button variant="primary" [disabled]="!schTen().trim()" (click)="saveScheduleFromModal()">
              <tabler-icon [icon]="iClock" [size]="14" /> Lưu lịch xuất
            </hrm-button>
          </div>
        </div>
      </div>
    }
  `,
  styles: [`
    /* ─── Dock 300px sticky — cột phải của drawer, tóm tắt luôn trong tầm mắt ─── */
    :host{display:flex;flex-direction:column;gap:var(--space-3);width:300px;flex:none;
      border-left:1px solid var(--border-sub);background:var(--bg-surface);
      padding:var(--space-4);overflow-y:auto;position:sticky;top:0;max-height:100%;min-height:0}
    .num{font-family:var(--font-mono);font-variant-numeric:tabular-nums}

    /* Nguồn cấu hình */
    .dk-src{font-size:var(--fs-12);color:var(--text-sub);line-height:1.5;flex:none}
    .dk-src b{display:block;font-size:var(--fs-13);color:var(--text-strong);font-weight:var(--font-medium)}
    .dk-src .pin{color:var(--warning-base);font-size:var(--fs-11)}

    /* Dirty-chip — amber CHỈ cho cảnh báo (AP-07), link hành động ngay trong chip */
    .dirty{display:flex;align-items:center;gap:var(--space-1);flex-wrap:wrap;flex:none;
      font-size:var(--fs-11);font-weight:var(--font-medium);
      background:var(--warning-bg);color:var(--warning-text);border:1px solid var(--warning-border);
      padding:var(--space-1) var(--space-3);border-radius:var(--radius-full)}
    .dirty .dot{width:6px;height:6px;border-radius:var(--radius-full);background:var(--warning-base)}
    .dirty .sep{color:var(--warning-border)}
    .dirty button{border:none;background:transparent;color:inherit;font-weight:var(--font-semibold);
      font-size:var(--fs-11);text-decoration:underline;cursor:pointer;padding:0}

    /* Chip mời lưu — trung tính (amber CHỈ cho cảnh báo, AP-07) */
    .savehint{display:inline-flex;align-items:center;gap:4px;flex:none;align-self:flex-start;
      font-size:var(--fs-11);color:var(--text-sub);background:var(--bg-surface-subtle);
      border:1px solid var(--border-sub);padding:var(--space-1) var(--space-3);border-radius:var(--radius-full)}
    .savehint button{border:none;background:transparent;color:var(--primary-base);
      font-weight:var(--font-semibold);font-size:var(--fs-11);cursor:pointer;padding:0}
    .savehint button:hover{text-decoration:underline}

    /* Khối tóm tắt — bất biến */
    .dk-sum{border:1px solid var(--border-sub);border-radius:var(--radius-lg);overflow:hidden;flex:none}
    .dk-h{font-size:var(--fs-11);letter-spacing:.8px;text-transform:uppercase;font-weight:var(--font-semibold);
      color:var(--text-sub);background:var(--bg-surface-subtle);
      padding:var(--space-2) var(--space-3);border-bottom:1px solid var(--border-soft)}
    .dk-row{display:flex;justify-content:space-between;align-items:baseline;gap:var(--space-2);
      padding:var(--space-2) var(--space-3);font-size:var(--fs-12);color:var(--text-sub);
      border-bottom:1px solid var(--border-soft)}
    .dk-row:last-child{border-bottom:none}
    .dk-row b{color:var(--text-strong);font-weight:var(--font-medium);text-align:right}
    .dk-row .soft{color:var(--text-soft);font-weight:var(--font-regular)}
    .dk-chips{padding:0 var(--space-3) var(--space-2);display:flex;gap:var(--space-1);flex-wrap:wrap}
    .chip{font-size:var(--fs-11);padding:2px 7px;border-radius:var(--radius-sm);
      background:var(--bg-surface-subtle);border:1px solid var(--border-sub);color:var(--text-body)}

    /* Trạng thái lịch — luôn render cả 2 chiều (AP-01) */
    .sdot{display:inline-flex;align-items:center;gap:5px;font-size:var(--fs-11);font-weight:var(--font-medium)}
    .sdot::before{content:'';width:7px;height:7px;border-radius:var(--radius-full)}
    .sdot.act{color:var(--success-text)}
    .sdot.act::before{background:var(--success-base)}
    .sdot.off{color:var(--text-soft)}
    .sdot.off::before{background:var(--text-soft)}

    /* Dock morph đặt lịch — viền primary để mắt biết đang ở mode lịch, không che tóm tắt.
       P2: morph TỰ scroll ở viewport thấp — tóm tắt + CTA luôn trong khung nhìn (bất biến §2). */
    .sched{border:1px solid var(--primary-border);border-radius:var(--radius-lg);
      background:var(--primary-bg-subtle);padding:var(--space-3);flex:none;
      max-height:45vh;overflow-y:auto}
    .sched-t{font-size:var(--fs-12);font-weight:var(--font-semibold);color:var(--primary-base);
      display:flex;gap:var(--space-1);align-items:center;margin-bottom:var(--space-2)}
    .sched hrm-input{margin-top:var(--space-1)}

    /* Field label dùng chung (morph + modal) */
    .f-l{font-size:var(--fs-11);color:var(--text-sub);font-weight:var(--font-medium);
      margin:var(--space-2) 0 var(--space-1)}
    .f-l .opt{color:var(--text-soft);font-weight:var(--font-regular)}
    .req{color:var(--error-base)}
    /* Nhãn có nút gợi ý AI — label trái, nút phải cùng hàng */
    .f-l-ai{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2)}
    /* Nút "✨ Gợi ý" — accent AI = primary (KHÔNG amber); chỉ điền, không tự Xuất */
    .ai-hint{display:inline-flex;align-items:center;gap:3px;cursor:pointer;
      border:1px solid var(--primary-border);background:var(--primary-bg-subtle);color:var(--primary-base);
      font-size:var(--fs-11);font-weight:var(--font-medium);line-height:1.6;
      padding:1px var(--space-2);border-radius:var(--radius-full)}
    .ai-hint:hover{background:var(--primary-bg-soft)}
    .f-2{display:flex;gap:var(--space-2)}
    .f-2>div{flex:1;min-width:0}
    .f-2>.wide{flex:1.4}
    .rcpt{display:flex;gap:var(--space-1);flex-wrap:wrap;margin-bottom:var(--space-1)}
    .f-ck{margin-top:var(--space-2);font-size:var(--fs-12);color:var(--text-body)}

    .dk-alert{flex:none}

    /* CTA — margin-top:auto neo đáy dock; primary duy nhất (AP-06) */
    .dk-cta{margin-top:auto;display:flex;flex-direction:column;gap:var(--space-2);
      padding-top:var(--space-2);flex:none}
    .dk-note{font-size:var(--fs-11);color:var(--text-soft);text-align:center;line-height:1.5}

    /* Modal overlay tự chứa — nền token --overlay, 1 lớp duy nhất trên drawer (P4) */
    .mback{position:fixed;inset:0;background:var(--overlay);display:flex;align-items:center;
      justify-content:center;z-index:1100}
    .modal{background:var(--bg-surface);border-radius:var(--radius-3xl);box-shadow:var(--shadow-regular-lg);
      width:460px;max-width:92vw;max-height:92vh;overflow-y:auto}
    .modal.w560{width:560px}
    .mo-h{display:flex;align-items:center;gap:var(--space-3);padding:var(--space-5) var(--space-5) 0}
    .mo-h h4{flex:1;font-size:var(--fs-16);font-weight:var(--font-semibold);color:var(--text-strong);margin:0}
    .mo-ic{width:32px;height:32px;border-radius:var(--radius-md);background:var(--primary-bg-subtle);
      color:var(--primary-base);display:flex;align-items:center;justify-content:center;flex:none}
    .mo-x{width:30px;height:30px;border:none;background:transparent;color:var(--text-sub);cursor:pointer;
      border-radius:var(--radius-sm);display:flex;align-items:center;justify-content:center}
    .mo-x:hover{background:var(--bg-surface-subtle)}
    .mo-sub{padding:2px var(--space-5) 0;font-size:var(--fs-12);color:var(--text-sub)}
    .mo-b{padding:var(--space-3) var(--space-5) var(--space-1)}
    .mo-f{display:flex;gap:var(--space-3);justify-content:flex-end;padding:var(--space-4) var(--space-5) var(--space-5)}
    .mo-note{margin-top:var(--space-3);border:1px solid var(--border-soft);border-radius:var(--radius-md);
      background:var(--bg-surface-subtle);padding:var(--space-2) var(--space-3);
      font-size:var(--fs-11);color:var(--text-sub);line-height:1.6}
    .mo-note b{color:var(--text-strong)}
  `],
})
export class EcDock {
  protected readonly store = inject(ExportCenterStore);
  /** Mọi xác nhận thay-đổi-trạng-thái đi qua toast (thẻ góc trên-phải), tone ngữ nghĩa khớp store. */
  private readonly toast = inject(HrmToastService);
  /** Đếm id bản sao mẫu văn bản — deterministic, không Math.random (zoneless). */
  private docSeq = 0;

  /* ── Icons (Tabler object mode) ── */
  protected readonly iClock = IconClock;
  protected readonly iDownload = IconDownload;
  protected readonly iPencil = IconPencil;
  protected readonly iPause = IconPlayerPause;
  protected readonly iPlay = IconPlayerPlay;
  protected readonly iRefresh = IconRefresh;
  protected readonly iSparkles = IconSparkles;
  protected readonly iStar = IconStar;
  protected readonly iX = IconX;

  /* ── Options tĩnh (const ổn định — zoneless-safe) ── */
  protected readonly tanSuatOptions = [
    { label: 'Hàng ngày', value: 'ngay' },
    { label: 'Hàng tuần', value: 'tuan' },
    { label: 'Hàng tháng', value: 'thang' },
  ];
  protected readonly thuOptions: HrmOption<string>[] =
    ['Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy', 'Chủ nhật']
      .map((t) => ({ label: t, value: t }));
  /** Ngày 01..28 — dừng ở 28 để lịch tháng không rơi vào ngày không tồn tại. */
  protected readonly ngayOptions: HrmOption<number>[] = Array.from({ length: 28 }, (_, i) => ({
    label: 'Ngày ' + String(i + 1).padStart(2, '0'), value: i + 1,
  }));
  protected readonly nhomOptions: HrmOption<string>[] = [
    { label: 'Danh sách nhân viên', value: 'Danh sách nhân viên' },
    { label: 'Báo cáo nhân sự', value: 'Báo cáo nhân sự' },
    { label: 'Hồ sơ nhân viên', value: 'Hồ sơ nhân viên' },
  ];
  protected readonly formatOptions: HrmOption<EcFormat>[] = [
    { label: EC_FORMAT_LABEL.xlsx, value: 'xlsx' },
    { label: EC_FORMAT_LABEL.csv, value: 'csv' },
    { label: EC_FORMAT_LABEL.pdf, value: 'pdf' },
  ];

  /* ── Computed từ store ── */
  /** Số dòng format vi-VN (1.248) — bind sống lên CTA + tóm tắt. */
  protected readonly rowCountLabel = computed(() => this.store.rowCount().toLocaleString('vi-VN'));
  protected readonly srcKindLabel = computed(() =>
    this.store.source()?.kind === 'lich' ? 'Lịch xuất' : 'Nguồn cấu hình');
  protected readonly srcName = computed(() => {
    const s = this.store.source();
    if (!s) return 'Tùy chỉnh — chưa gắn mẫu';
    return s.kind === 'hist' ? 'Lịch sử · ' + s.ten : s.ten;
  });
  /** ★ chỉ khi nguồn là mẫu VÀ mẫu đó đang ghim mặc định. */
  protected readonly srcIsDefault = computed(() => {
    const s = this.store.source();
    return s?.kind === 'mau' && !!this.store.templates().find((t) => t.id === s.id)?.macDinh;
  });
  /** Nguồn là LỊCH → dock đổi vai điều khiển lịch (màn 07). */
  protected readonly srcSchedule = computed(() => {
    const s = this.store.source();
    return s?.kind === 'lich' ? (this.store.schedules().find((x) => x.id === s.id) ?? null) : null;
  });
  protected readonly docFormatLabel = computed(() => {
    const d = this.store.selectedDoc();
    return d ? EC_FORMAT_LABEL[d.format] : '';
  });
  protected readonly docFormatShort = computed(() => {
    const d = this.store.selectedDoc();
    return d ? EC_FORMAT_SHORT[d.format] : '';
  });
  /** Chọn mẫu ★ trong modal tạo lịch — {label,value:id}, mẫu mặc định đánh dấu ★. */
  protected readonly templateOptions = computed<HrmOption<string>[]>(() =>
    this.store.templates().map((t) => ({ label: (t.macDinh ? '★ ' : '') + t.ten, value: t.id })));

  /* ── Form đặt lịch (dùng chung dock morph + modal — không bao giờ mở đồng thời) ── */
  protected readonly schTanSuat = signal<'ngay' | 'tuan' | 'thang'>('tuan');
  protected readonly schThu = signal('Thứ Hai');
  protected readonly schNgayThang = signal(1);
  /** Giờ neo cố định 08:00 ngày EC_TODAY — giá trị tường minh, không Date.now() (zoneless). */
  protected readonly schGio = signal<Date | null>(new Date(2026, 7, 20, 8, 0));
  protected readonly schTen = signal('Báo cáo nhân sự hàng tuần');
  protected readonly schNguoiNhan = signal<string[]>(['HR Manager', 'hr@company.com']);
  protected readonly schNewRcpt = signal('');
  protected readonly schMailReady = signal(true);
  protected readonly schMailChanged = signal(false);
  /** Đang CHỈNH SỬA lịch nào qua dock morph — null = tạo mới (sửa KHÔNG nhân đôi lịch). */
  protected readonly editingScheduleId = signal<string | null>(null);
  /** Cờ transient: lần mở morph kế tiếp là để SỬA (đặt bởi editSchedule) → effect không reset form. */
  private openingForEdit = false;

  constructor() {
    // Prefill/reset form dock morph khi mở. Nguồn: openingForEdit (editSchedule đã nạp form) >
    // aiScheduleSeed (AI đặt lịch) > reset mặc định. Tránh: (a) mở tạo-mới nhưng dính mode "Cập nhật lịch"
    // ghi đè lịch cũ; (b) form còn kẹt tên/tần suất/người nhận của lần trước.
    // Effect track CẢ schedOpen LẪN aiScheduleSeed: nếu AI set seed lúc morph ĐANG mở (schedOpen đã true —
    // không có transition false→true) thì seed vẫn được tiêu thụ + prefill NGAY, không rò sang lần mở tay sau.
    let prevOpen = false;
    effect(() => {
      const open = this.store.schedOpen();
      const seed = this.store.aiScheduleSeed(); // tracked: seed đổi cũng kích effect (kể cả khi đang mở)
      if (!open) { prevOpen = open; return; }
      if (this.openingForEdit) { this.openingForEdit = false; prevOpen = open; return; }
      if (seed) {
        this.prefillSchedFromSeed(seed);       // AI mở lịch → prefill từ seed, coi như TẠO MỚI
        this.store.aiScheduleSeed.set(null);   // seed dùng 1 lần → tiêu thụ ngay, không dính lần mở tay sau
      } else if (!prevOpen) {
        this.editingScheduleId.set(null);
        this.resetSchedForm();
      }
      prevOpen = open;
    });
  }

  /** AI đặt lịch: nạp form từ seed rồi coi như TẠO MỚI (editingScheduleId=null → không nhân đôi/ghi đè lịch cũ).
   *  Nền sạch trước (giờ/checkbox/người nhận mặc định), rồi phủ đúng field seed suy được. */
  private prefillSchedFromSeed(seed: NonNullable<EcAiPlan['schedule']>): void {
    this.resetSchedForm();
    this.editingScheduleId.set(null);
    this.schTanSuat.set(seed.tanSuat);
    if (seed.thu) this.schThu.set(seed.thu);
    if (seed.ngayThang) this.schNgayThang.set(seed.ngayThang);
    if (seed.nguoiNhan?.length) this.schNguoiNhan.set([...seed.nguoiNhan]);
    this.schTen.set('Lịch từ AI');            // tên gợi mở — người dùng sửa tuỳ ý trước khi lưu
  }

  /** Modal tạo lịch: đổi mẫu nguồn → đồng bộ ô Định dạng theo format của mẫu đó (không kẹt xlsx cũ). */
  protected pickCsTemplate(id: string): void {
    this.csTemplateId.set(id);
    const t = this.store.templates().find((x) => x.id === id);
    if (t) this.csFormat.set(t.format);
  }

  /** Reset form đặt lịch về mặc định (đối xứng openSaveModal của modal Lưu mẫu). */
  private resetSchedForm(): void {
    this.schTanSuat.set('tuan');
    this.schThu.set('Thứ Hai');
    this.schNgayThang.set(1);
    this.schGio.set(new Date(2026, 7, 20, 8, 0));
    this.schTen.set('Báo cáo nhân sự hàng tuần');
    this.schNguoiNhan.set(['HR Manager', 'hr@company.com']);
    this.schNewRcpt.set('');
    this.schMailReady.set(true);
    this.schMailChanged.set(false);
  }
  /** Modal tạo lịch: mẫu nguồn + định dạng riêng (dock morph thừa kế format canvas). */
  protected readonly csTemplateId = signal('tpl-1');
  protected readonly csFormat = signal<EcFormat>('xlsx');

  /* ── Form lưu mẫu ── */
  protected readonly svTen = signal('');
  protected readonly svMoTa = signal('');
  protected readonly svNhom = signal('Danh sách nhân viên');
  protected readonly svMacDinh = signal(false);

  /* ── Helpers hiển thị ── */

  /** Nhịp đầy đủ cho khối "Nhịp chạy" ('Hàng tuần · Thứ Hai' — mockup màn 07). */
  protected nhipFull(s: EcSchedule): string {
    if (s.tanSuat === 'ngay') return 'Hàng ngày';
    if (s.tanSuat === 'tuan') return 'Hàng tuần · ' + (s.thu ?? '');
    return 'Hàng tháng · ' + ecNhipLabel(s);
  }

  /** Người nhận có '@' = email ngoài, còn lại là người trong hệ thống. */
  protected rcptKind(r: string): string {
    return r.includes('@') ? 'email' : 'trong hệ thống';
  }

  /* ── Actions: người nhận ── */

  protected addRcpt(): void {
    const v = this.schNewRcpt().trim();
    if (!v || this.schNguoiNhan().includes(v)) return;
    this.schNguoiNhan.update((l) => [...l, v]);
    this.schNewRcpt.set('');
  }

  protected removeRcpt(r: string): void {
    this.schNguoiNhan.update((l) => l.filter((x) => x !== r));
  }

  /* ── Actions: đặt lịch ── */

  /** Lưu lịch từ dock morph — đang SỬA thì cập nhật đúng lịch đó (không nhân đôi), còn lại tạo mới. */
  protected saveSchedule(): void {
    const ten = this.schTen().trim();
    if (!ten) return;
    const editId = this.editingScheduleId();
    if (editId) {
      const tanSuat = this.schTanSuat();
      this.store.schedules.update((l) => l.map((x) => x.id === editId
        ? {
            ...x, ten, tanSuat,
            thu: tanSuat === 'tuan' ? this.schThu() : undefined,
            ngayThang: tanSuat === 'thang' ? this.schNgayThang() : undefined,
            gio: this.gioStr(),
            nguoiNhan: [...this.schNguoiNhan()],
            // Giữ active + lanChay; lanKe tính lại theo tần suất mới (chỉ khi đang hoạt động).
            lanKe: x.active ? EC_NEXT_RUN[tanSuat] : x.lanKe,
          }
        : x));
      const src = this.store.source();
      if (src?.kind === 'lich' && src.id === editId) this.store.source.set({ ...src, ten });
      this.editingScheduleId.set(null);
      this.store.schedOpen.set(false);
      // Cập nhật lịch = thay-đổi-trạng-thái (twin của rename mẫu → store dùng success) → toast success.
      this.toast.success('Đã cập nhật lịch', '"' + ten + '"');
      return; // KHÔNG chuyển màn "Đã tạo lịch xuất" — đây là cập nhật, không phải tạo mới.
    }
    this.store.createSchedule({
      ten,
      tanSuat: this.schTanSuat(),
      thu: this.schThu(),
      ngayThang: this.schNgayThang(),
      gio: this.gioStr(),
      nguoiNhan: [...this.schNguoiNhan()],
    });
  }

  /** Lưu lịch từ modal đầy đủ — "Dùng cấu hình" khác nguồn hiện tại thì nạp mẫu đó trước. */
  protected saveScheduleFromModal(): void {
    const ten = this.schTen().trim();
    if (!ten) return;
    const src = this.store.source();
    if (!src || src.id !== this.csTemplateId()) this.store.hydrateTemplate(this.csTemplateId());
    this.store.createSchedule({
      ten,
      tanSuat: this.schTanSuat(),
      thu: this.schThu(),
      ngayThang: this.schNgayThang(),
      gio: this.gioStr(),
      format: this.csFormat(),
      nguoiNhan: [...this.schNguoiNhan()],
    });
  }

  /** "Chỉnh sửa lịch": nạp giá trị lịch vào form rồi mở dock morph — sửa tại chỗ, 0 chuyển màn. */
  protected editSchedule(s: EcSchedule): void {
    this.openingForEdit = true; // báo effect: lần mở này là SỬA, đừng reset form
    this.editingScheduleId.set(s.id);
    this.schTen.set(s.ten);
    this.schTanSuat.set(s.tanSuat);
    if (s.thu) this.schThu.set(s.thu);
    if (s.ngayThang) this.schNgayThang.set(s.ngayThang);
    this.schGio.set(this.parseGio(s.gio));
    this.schNguoiNhan.set([...s.nguoiNhan]);
    this.store.schedOpen.set(true);
  }

  /** Mở morph tạo lịch MỚI — effect (schedOpen false→true, không openingForEdit) tự dọn cờ sửa + reset form. */
  protected openSchedMorph(): void {
    this.store.schedOpen.set(true);
  }

  /** Đóng morph — hủy cả chế độ sửa (lịch gốc giữ nguyên). */
  protected cancelSched(): void {
    this.editingScheduleId.set(null);
    this.store.schedOpen.set(false);
  }

  /* ── Actions: lưu mẫu ── */

  /** Mở modal với form sạch — tránh rác từ lần lưu trước. */
  protected openSaveModal(): void {
    this.svTen.set('');
    this.svMoTa.set('');
    this.svMacDinh.set(false);
    this.store.saveModalOpen.set(true);
  }

  /** B (autofill) — AI suy Tên + Mô tả từ cấu hình hiện tại, CHỈ điền 2 ô (không auto-lưu; người dùng sửa được). */
  protected aiFillTemplateMeta(): void {
    const meta = this.store.aiSuggestTemplateMeta();
    this.svTen.set(meta.ten);
    this.svMoTa.set(meta.moTa);
  }

  protected saveTemplate(): void {
    const ten = this.svTen().trim();
    if (!ten) return;
    this.store.saveTemplate({
      ten,
      moTa: this.svMoTa().trim() || undefined,
      macDinh: this.svMacDinh(),
    });
  }

  /* ── Actions: tab văn bản (demo — chỉ thông báo, không sinh file thật) ── */

  protected docDownload(): void {
    const d = this.store.selectedDoc();
    if (!d) return;
    // Tạo văn bản = hành động sinh output đã hoàn tất (twin của runScheduleNow → success) → toast success.
    this.toast.success('Đã tạo văn bản', this.store.totalFilter + ' văn bản ' + EC_FORMAT_SHORT[d.format] + ' — "' + d.ten + '"');
  }

  protected docUpdate(): void {
    const d = this.store.selectedDoc();
    if (!d) return;
    // Cập nhật mẫu = thay-đổi-trạng-thái (twin của rename mẫu → success) → toast success.
    this.toast.success('Đã cập nhật mẫu', '"' + d.ten + '"');
  }

  /** "+ Lưu thành mẫu mới" (mockup màn 09/10): nhân bản mẫu văn bản đang soạn thành mẫu mới. */
  protected docSaveAsNew(): void {
    const d = this.store.selectedDoc();
    if (!d) return;
    const copy: EcDocTemplate = { ...d, id: 'doc-c' + ++this.docSeq, ten: d.ten + ' (bản sao)', capNhat: EC_TODAY };
    this.store.docTemplates.update((l) => [copy, ...l]);
    this.store.selectedDocId.set(copy.id);
    // Lưu-thành-mẫu-mới = nhân bản (twin của duplicateTemplate → store dùng neutral) → toast neutral.
    this.toast.neutral('Đã lưu mẫu văn bản mới', '"' + copy.ten + '"');
  }

  /* ── Private ── */

  /** Date của time-picker → 'HH:mm' cho store (store chỉ giữ chuỗi — zoneless). */
  private gioStr(): string {
    const d = this.schGio();
    if (!d) return '08:00';
    return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  }

  /** 'HH:mm' → Date neo ngày cố định (chỉ dùng giờ:phút cho time-picker). */
  private parseGio(g: string): Date {
    const [h, m] = g.split(':').map(Number);
    return new Date(2026, 7, 20, h || 8, m || 0);
  }
}
