import { DestroyRef, Injectable, computed, inject, signal } from '@angular/core';

// ============================================================
// Types — AI Data Import (contract §3)
// ============================================================

export type ImpStep = 0 | 1 | 2 | 3; // 0 Thiết lập · 1 Kiểm tra & sửa · 2 Xác nhận & import · 3 Kết quả
export type ImpMode = 'template' | 'ai';
export type ScanPhase = 'idle' | 'scanning' | 'done';
export type ImportPhase = 'idle' | 'running' | 'background' | 'done';
export type RowState = 'valid' | 'warn' | 'error';

export interface ImpField {
  key: string;
  label: string;
  required?: boolean;
}

export interface ImpMapping {
  fieldKey: string;
  fieldLabel: string;
  required?: boolean;
  fileCol: string | null;
  confidence: number; // 0..100
  status: 'high' | 'review' | 'confirm' | 'unmapped'; // 🟢95+ · 🟡80–94 · 🔴<80 · chưa map
  reason: string; // giải thích AI (explainability)
  accepted?: boolean;
}

export interface ImpScanStep {
  label: string;
  state: 'done' | 'active' | 'todo';
}

export interface ImpIssue {
  id: string;
  severity: 'error' | 'warn' | 'hint';
  label: string;
  count: number;
}

export interface ImpRow {
  id: number;
  name: string;
  email: string;
  phone: string;
  dept: string;
  role: string;
  status: string;
  joined: string;
  state: RowState;
  errors: string[]; // rỗng khi valid
  aiSuggest?: string; // gợi ý AI cho lỗi (nếu có)
  dup?: boolean;
  exists?: boolean;
  fixed?: boolean;
}

export interface ImpDupPair {
  id: number;
  a: { row: number; name: string; email: string };
  b: { row: number; name: string; email: string };
  match: number; // % khả năng trùng
  resolved?: 'a' | 'b' | null;
}

export interface ImpHistoryRow {
  file: string;
  user: string;
  time: string;
  total: string;
  ok: string;
  err: string;
  quality: string;
  status: 'ok' | 'partial' | 'fail';
}

