// Thông điệp lỗi chuẩn (dùng thống nhất giữa mock + validators)
const ERR_EMAIL = 'Email không hợp lệ';
const ERR_DEPT = 'Phòng ban không tồn tại';
const ERR_PHONE = 'Số điện thoại chưa đúng định dạng';
const ERR_DATE = 'Sai định dạng ngày';
const ERR_EMPCODE = 'Không tìm thấy mã nhân viên';

const EMAIL_RE = /.+@.+\..+/;
const PHONE_RE = /^\d{4} \d{3} \d{3}$/;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const FIELD_ERRORS: readonly string[] = [ERR_EMAIL, ERR_DEPT, ERR_PHONE, ERR_DATE];
const WARN_ERRORS: readonly string[] = [ERR_DEPT, ERR_PHONE];

const SMART_FIX_SOURCE: readonly string[] = ['Sale', 'sales', 'Sales Dept'];
const SMART_FIX_TARGET = 'Sales Department';

const IMPORT_TOTAL = 178240;

const fmt = (n: number): string => n.toLocaleString('en-US');

/**
 * Re-validate một dòng: email regex, dept thuộc DEPTS, phone/ngày đúng format.
 * Lỗi không thuộc 4 trường trên (vd thiếu mã NV) được giữ nguyên.
 */
function revalidateRow(row: ImpRow, markFixed: boolean): ImpRow {
  const errors: string[] = [];
  if (!EMAIL_RE.test(row.email)) errors.push(ERR_EMAIL);
  if (!DEPTS.includes(row.dept)) errors.push(ERR_DEPT);
  if (!PHONE_RE.test(row.phone)) errors.push(ERR_PHONE);
  if (!DATE_RE.test(row.joined)) errors.push(ERR_DATE);
  for (const e of row.errors) {
    if (!FIELD_ERRORS.includes(e) && !errors.includes(e)) errors.push(e);
  }
  const state: RowState =
    errors.length === 0 ? 'valid' : errors.some((e) => !WARN_ERRORS.includes(e)) ? 'error' : 'warn';
  const aiSuggest = errors.length === 0 ? undefined : row.aiSuggest;
  return {
    ...row,
    errors,
    state,
    aiSuggest,
    fixed: markFixed && errors.length === 0 ? true : row.fixed,
  };
}

