import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HrmButton, HrmInput, HrmSelect } from 'hrm-ui';
import {
  TablerIconComponent,
  IconChevronLeft,
  IconChevronRight,
  IconEye,
  IconPencil,
  IconPlus,
  IconSearch,
  IconSparkles,
} from '@tabler/icons-angular';
import { ExportCenterStore } from './_export-data';

/** Một dòng đã parse của trang preview — tách k/v để style nhãn trái / giá trị phải như mockup màn 11. */
interface EcDocLine { kind: 'title' | 'kv' | 'text' | 'blank'; k?: string; v?: string; num?: boolean; }

/** ec-canvas-doc — CANVAS tab "Văn bản theo mẫu" (mockup màn 09/10/11).
 *  Soạn thảo {{field}} + field picker 1-click + Xem trước dữ liệu THẬT theo từng nhân viên.
 *  KHÔNG provide store — host page provide (mỗi phiên demo là store mới). */
@Component({
  selector: 'ec-canvas-doc',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule, HrmButton, HrmInput, HrmSelect, TablerIconComponent],
  template: `
    @if (store.selectedDoc(); as doc) {
      <!-- Hàng 1: tên mẫu + WORD/PDF — chỉ tab Soạn thảo (màn 11 ẩn: preview tập trung vào trang giấy) -->
      @if (store.docTab() === 'edit') {
        <div class="tm-row">
          <hrm-input
            class="grow"
            placeholder="Tên mẫu văn bản"
            [ngModel]="doc.ten"
            (ngModelChange)="renameDoc($event)" />
          <div class="wpseg" role="group" aria-label="Định dạng văn bản">
            <button type="button" class="m" [class.on]="doc.format === 'word'" (click)="setFormat('word')">WORD</button>
            <button type="button" class="m" [class.on]="doc.format === 'pdf'" (click)="setFormat('pdf')">PDF</button>
          </div>
        </div>
      }

      <!-- Hàng 2: tabs Soạn thảo/Xem trước + hành động theo tab -->
      <div class="tm-row">
        <div class="edtabs" role="tablist">
          <button type="button" class="m" role="tab" [class.on]="store.docTab() === 'edit'" (click)="openTab('edit')">
            <tabler-icon [icon]="IconPencil" [size]="13" /> Soạn thảo
          </button>
          <button type="button" class="m" role="tab" [class.on]="store.docTab() === 'preview'" (click)="openTab('preview')">
            <tabler-icon [icon]="IconEye" [size]="13" /> Xem trước
          </button>
        </div>

        @if (store.docTab() === 'edit') {
          <!-- Feature C: AI soạn nháp theo LOẠI mẫu đang chọn (tên mẫu → keyword). Chỉ điền body, KHÔNG auto-Xuất. -->
          <hrm-button
            class="push"
            size="sm"
            variant="default"
            [disabled]="store.aiThinking()"
            (click)="runAiDraft()">
            <tabler-icon [icon]="IconSparkles" [size]="13" />
            {{ store.aiThinking() ? 'Đang soạn…' : 'Soạn bằng AI' }}
          </hrm-button>
          <!-- Nút đổi primary khi picker mở (màn 10) — thấy rõ nguồn popover đang bật -->
          <hrm-button
            size="sm"
            [variant]="store.fieldPickerOpen() ? 'primary' : 'default'"
            (click)="togglePicker()">
            <tabler-icon [icon]="IconPlus" [size]="13" /> Chèn trường
          </hrm-button>
        } @else {
          <span class="pv-lb push">Nhân viên:</span>
          <div class="pv-sel">
            <hrm-select
              [options]="empOptions"
              [allowClear]="false"
              [ngModel]="store.previewEmpIdx()"
              (ngModelChange)="setEmp($event)" />
          </div>
          <div class="pv-nav">
            <hrm-button [iconOnly]="true" ariaLabel="Nhân viên trước" [disabled]="store.previewEmpIdx() === 0" (click)="prevEmp()">
              <tabler-icon [icon]="IconChevronLeft" [size]="15" />
            </hrm-button>
            <hrm-button [iconOnly]="true" ariaLabel="Nhân viên sau" [disabled]="store.previewEmpIdx() === lastIdx" (click)="nextEmp()">
              <tabler-icon [icon]="IconChevronRight" [size]="15" />
            </hrm-button>
          </div>
        }
      </div>

      @if (store.docTab() === 'edit') {
        <!-- Editor mono — demo dùng textarea thuần (không track caret): insertField chèn cuối -->
        <div class="ed-wrap">
          <textarea
            class="editor"
            spellcheck="false"
            aria-label="Nội dung mẫu văn bản"
            [value]="doc.body"
            (input)="onBody($event)"></textarea>

          @if (store.aiThinking()) {
            <!-- Phủ mờ nhẹ khi AI soạn lại — editor vẫn thấy lờ mờ, không đụng logic picker/state cũ. -->
            <div class="ai-overlay">
              <span class="ai-badge"><tabler-icon [icon]="IconSparkles" [size]="15" /> AI đang soạn…</span>
            </div>
          }

          @if (store.fieldPickerOpen()) {
            <!-- Backdrop trong suốt: click ngoài = đóng popover -->
            <div class="fp-backdrop" (click)="store.fieldPickerOpen.set(false)"></div>
            <div class="fpick">
              <div class="fp-s">
                <hrm-input
                  size="sm"
                  placeholder="Tìm trường…"
                  [prefixIcon]="IconSearch"
                  [ngModel]="fieldQ()"
                  (ngModelChange)="fieldQ.set($event ?? '')" />
              </div>
              <div class="fp-list">
                @for (g of fieldGroups(); track g.nhom) {
                  <div class="fg">{{ g.nhom }}</div>
                  @for (f of g.fields; track f.code) {
                    <!-- Mã hiện cạnh tên để user học dần cú pháp (màn 10) -->
                    <button type="button" class="fi" (click)="store.insertField(f.code)">
                      <span>{{ f.label }}</span>
                      <!-- Literal {{ }} phải đi qua interpolation string — entity &#123; bị decode TRƯỚC khi parse nên vẫn thành interpolation. -->
                      <code>{{ '{{' + f.code + '}}' }}</code>
                    </button>
                  }
                } @empty {
                  <div class="fp-empty">Không có trường phù hợp</div>
                }
              </div>
            </div>
          }
        </div>
        <div class="ed-hint">{{ 'Chèn trường bằng {{ }}, ví dụ {{name}}, {{score}}.' }}</div>
        @if (aiDrafted()) {
          <!-- Nhắc AI chỉ tạo NHÁP — buộc người dùng kiểm tra & sửa, không tin tưởng mù. -->
          <div class="ai-hint"><tabler-icon [icon]="IconSparkles" [size]="13" /> AI nháp — kiểm tra &amp; sửa tuỳ ý</div>
        }
      } @else {
        <!-- Trang giấy trắng render dữ liệu THẬT — soi lỗi mẫu trước khi tạo cả loạt -->
        <div class="docprev">
          <div class="page">
            @for (ln of previewLines(); track $index) {
              @switch (ln.kind) {
                @case ('title') { <h5>{{ ln.v }}</h5> }
                @case ('kv') {
                  <div class="pr">
                    <span class="k">{{ ln.k }}</span>
                    <span class="v" [class.num]="ln.num">{{ ln.v }}</span>
                  </div>
                }
                @case ('text') { <p class="pt">{{ ln.v }}</p> }
                @case ('blank') { <div class="pb"></div> }
              }
            }
          </div>
        </div>
      }
    } @else {
      <div class="ed-hint">Chưa chọn mẫu văn bản — chọn một mẫu ở danh sách bên trái.</div>
    }
  `,
  styles: [`
    /* Spacing = token --space-* (bất biến DS #3, đồng bộ ec-dock). Kích thước cấu trúc (min-height/width
       trang giấy, ring focus) giữ px vì không có token tương ứng. */
    :host { display: flex; flex-direction: column; gap: var(--space-2-5); flex: 1; min-height: 0; }

    .tm-row { display: flex; gap: var(--space-2-5); align-items: center; }
    .grow { flex: 1; min-width: 0; }
    .push { margin-left: auto; }

    /* Toggle WORD/PDF — 2 nút liền khối, active = nền primary (mockup .wpseg) */
    .wpseg { display: inline-flex; border: 1px solid var(--border-sub); border-radius: var(--radius-md); overflow: hidden; flex: none; }
    .wpseg .m {
      font-size: var(--fs-11); font-weight: 600; padding: var(--space-2) var(--space-3-5); border: none;
      background: var(--bg-surface); color: var(--text-sub); cursor: pointer;
    }
    .wpseg .m.on { background: var(--primary-base); color: var(--text-on-primary); }

    /* Tabs Soạn thảo/Xem trước — pill trên nền subtle (mockup .edtabs) */
    .edtabs { display: inline-flex; gap: var(--space-0-5); background: var(--bg-surface-subtle); border-radius: var(--radius-md); padding: var(--space-0-5); width: fit-content; }
    .edtabs .m {
      font-size: var(--fs-12); font-weight: 500; color: var(--text-sub); padding: var(--space-1-5) var(--space-3-5);
      border-radius: var(--radius-sm); border: none; background: transparent; cursor: pointer;
      display: inline-flex; gap: var(--space-1-5); align-items: center;
    }
    .edtabs .m.on { background: var(--bg-surface); color: var(--primary-base); box-shadow: var(--shadow-regular-xs); }

    /* Editor mono — popover định vị theo wrapper */
    .ed-wrap { position: relative; flex: 1; min-height: 0; display: flex; }
    .editor {
      flex: 1; width: 100%; min-height: 280px; resize: none; outline: none;
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface);
      padding: var(--space-4); font-family: var(--font-mono); font-size: var(--fs-13); line-height: 2; color: var(--text-strong);
    }
    .editor:focus { border-color: var(--primary-base); box-shadow: 0 0 0 3px var(--primary-focus-ring); }
    .ed-hint { font-size: var(--fs-11); color: var(--text-soft); }

    /* Overlay "AI đang soạn" — frosted veil token-only (color-mix bg-surface + blur nhẹ), editor còn thấy lờ mờ. */
    .ai-overlay {
      position: absolute; inset: 0; z-index: 23;
      display: flex; align-items: center; justify-content: center;
      border-radius: var(--radius-lg);
      background: color-mix(in srgb, var(--bg-surface) 66%, transparent);
      backdrop-filter: blur(2px);
    }
    .ai-badge { display: inline-flex; align-items: center; gap: var(--space-2); font-size: var(--fs-13); font-weight: 600; color: var(--primary-base); }
    /* Hint sau khi soạn xong — nhắc đây chỉ là NHÁP AI (accent primary, không amber). */
    .ai-hint { display: inline-flex; align-items: center; gap: var(--space-1-5); font-size: var(--fs-11); font-weight: 500; color: var(--primary-base); }

    /* Field picker popover (mockup .fpick) */
    .fp-backdrop { position: fixed; inset: 0; z-index: 24; }
    .fpick {
      position: absolute; top: var(--space-2); right: var(--space-2-5); width: 250px; z-index: 25; overflow: hidden;
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      border-radius: var(--radius-lg); box-shadow: var(--shadow-regular-md);
    }
    .fp-s { margin: var(--space-2) var(--space-2) 0; }
    .fp-list { max-height: 300px; overflow: auto; padding-bottom: var(--space-2); }
    .fg {
      font-size: var(--fs-11); letter-spacing: .8px; text-transform: uppercase; font-weight: 600;
      color: var(--text-soft); padding: var(--space-2) var(--space-3) var(--space-0-5);
    }
    .fi {
      display: flex; justify-content: space-between; align-items: center; gap: var(--space-2); width: 100%;
      font-size: var(--fs-12); color: var(--text-body); padding: var(--space-1-5) var(--space-3);
      border: none; background: transparent; cursor: pointer; text-align: left;
    }
    .fi:hover { background: var(--primary-bg-subtle); color: var(--primary-base); }
    .fi code { font-family: var(--font-mono); font-size: var(--fs-11); color: var(--text-soft); }
    .fi:hover code { color: var(--primary-base); }
    .fp-empty { padding: var(--space-2-5) var(--space-3); font-size: var(--fs-12); color: var(--text-soft); }

    /* Hàng điều hướng preview */
    .pv-lb { font-size: var(--fs-12); color: var(--text-sub); flex: none; }
    .pv-sel { width: 240px; flex: none; }
    .pv-nav { display: flex; gap: var(--space-1); flex: none; }

    /* Trang giấy trắng (mockup .docprev/.page) */
    .docprev {
      flex: 1; min-height: 0; overflow: auto; padding: var(--space-4);
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface-subtle);
    }
    .page {
      max-width: 560px; margin: 0 auto; padding: var(--space-8) var(--space-10); min-height: 420px;
      background: var(--bg-surface); border: 1px solid var(--border-sub);
      border-radius: var(--radius-sm); box-shadow: var(--shadow-regular-sm);
    }
    .page h5 { font-size: var(--fs-15); letter-spacing: .6px; text-align: center; margin: 0 0 var(--space-6); font-weight: 700; color: var(--text-strong); }
    .pr { display: flex; font-size: var(--fs-13); line-height: 2.1; }
    .pr .k { width: 150px; flex: none; color: var(--text-sub); }
    .pr .v { color: var(--text-strong); font-weight: 500; }
    .num { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
    .pt { font-size: var(--fs-13); line-height: 2.1; color: var(--text-strong); margin: 0; }
    .pb { height: var(--space-3); }
  `],
})
export class EcCanvasDoc {
  readonly store = inject(ExportCenterStore);

  // Icon Tabler (object mode)
  readonly IconPlus = IconPlus;
  readonly IconPencil = IconPencil;
  readonly IconEye = IconEye;
  readonly IconSearch = IconSearch;
  readonly IconChevronLeft = IconChevronLeft;
  readonly IconChevronRight = IconChevronRight;
  readonly IconSparkles = IconSparkles;

  /** Từ khóa lọc field picker — state cục bộ, reset mỗi lần mở. */
  readonly fieldQ = signal('');

  /** Options select nhân viên: "Tên (i/26)" — vị trí trong phạm vi giúp định hướng khi duyệt ‹ ›. */
  readonly empOptions = this.store.employees.map((e, i) => ({
    label: e.name + ' (' + (i + 1) + '/' + this.store.employees.length + ')',
    value: i,
  }));
  readonly lastIdx = this.store.employees.length - 1;

  /** Nhóm field sau lọc — bỏ nhóm rỗng để picker gọn. */
  readonly fieldGroups = computed(() => {
    const q = this.fieldQ().trim().toLowerCase();
    return this.store.docFields
      .map((g) => ({
        nhom: g.nhom,
        fields: g.fields.filter((f) => !q || f.label.toLowerCase().includes(q) || f.code.toLowerCase().includes(q)),
      }))
      .filter((g) => g.fields.length > 0);
  });

  /** Parse chuỗi preview thành dòng có cấu trúc — để style nhãn trái/giá trị phải như trang giấy mockup. */
  readonly previewLines = computed<EcDocLine[]>(() => {
    const text = this.store.renderDocPreview(this.store.previewEmpIdx());
    const out: EcDocLine[] = [];
    let titleDone = false;
    for (const raw of text.split('\n')) {
      const line = raw.trim();
      if (!line) { out.push({ kind: 'blank' }); continue; }
      if (!titleDone) { titleDone = true; out.push({ kind: 'title', v: line }); continue; }
      const i = line.indexOf(':');
      const k = i > 0 ? line.slice(0, i).trim() : '';
      // CHỈ coi là nhãn:giá-trị khi key NGẮN (≤24 ký tự) và không phải cả câu (không chứa {{}}/dấu câu/khoảng cách nhiều).
      // Dòng văn xuôi ("Công ty xác nhận Ông/Bà … (Mã NV: …)") có ':' nhưng key dài → render 'text', không vỡ layout.
      const isLabel = i > 0 && i < line.length - 1 && k.length <= 24 && !/[{}(),]/.test(k);
      if (isLabel) {
        const v = line.slice(i + 1).trim();
        // num = giá trị toàn số/ngày/giờ → font mono tabular
        out.push({ kind: 'kv', k, v, num: /\d/.test(v) && /^[\d\/.,:\s·—-]*$/.test(v) });
      } else {
        out.push({ kind: 'text', v: line });
      }
    }
    return out;
  });

  /** Đã có nháp AI → hiện hint "kiểm tra & sửa": AI soạn xong (aiThinking false) và summary chứa 'nháp'. */
  readonly aiDrafted = computed(() => {
    const s = this.store.aiPlan()?.summary ?? '';
    return !this.store.aiThinking() && s.includes('nháp');
  });

  /* ── Hàng 1 ── */

  /** Đổi tên mẫu đang soạn — sửa trực tiếp trong danh sách store. */
  renameDoc(ten: string | null): void {
    const id = this.store.selectedDocId();
    this.store.docTemplates.update((l) => l.map((d) => (d.id === id ? { ...d, ten: ten ?? '' } : d)));
  }

  /** Đổi định dạng đầu ra WORD/PDF của mẫu đang soạn. */
  setFormat(format: 'word' | 'pdf'): void {
    const id = this.store.selectedDocId();
    this.store.docTemplates.update((l) => l.map((d) => (d.id === id ? { ...d, format } : d)));
  }

  /* ── Hàng 2 + editor ── */

  /** Chuyển tab — đóng picker để không lơ lửng popover trên tab preview. */
  openTab(tab: 'edit' | 'preview'): void {
    this.store.docTab.set(tab);
    this.store.fieldPickerOpen.set(false);
  }

  togglePicker(): void {
    this.fieldQ.set('');
    this.store.fieldPickerOpen.update((v) => !v);
  }

  /** Feature C — soạn lại body theo LOẠI mẫu đang chọn (tên mẫu → keyword trong store.aiRunDoc). AI chỉ điền body, KHÔNG Xuất. */
  runAiDraft(): void {
    this.store.aiRunDoc(this.store.selectedDoc()?.ten ?? '');
  }

  /** Gõ trong editor → ghi thẳng body vào store (textarea uncontrolled-nhẹ, đủ cho demo). */
  onBody(ev: Event): void {
    const body = (ev.target as HTMLTextAreaElement).value;
    const id = this.store.selectedDocId();
    this.store.docTemplates.update((l) => l.map((d) => (d.id === id ? { ...d, body } : d)));
  }

  /* ── Preview ── */

  setEmp(idx: unknown): void {
    if (typeof idx === 'number') this.store.previewEmpIdx.set(idx);
  }
  prevEmp(): void { this.store.previewEmpIdx.update((i) => Math.max(0, i - 1)); }
  nextEmp(): void { this.store.previewEmpIdx.update((i) => Math.min(this.lastIdx, i + 1)); }
}
