import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  IconAlertTriangle, IconCheck, IconCircleCheck, IconCloudUpload, IconDownload,
  IconEye, IconFileSpreadsheet, IconListCheck, IconRefresh, IconSparkles, IconX,
  TablerIconComponent,
} from '@tabler/icons-angular';
import {
  HrmButton, HrmGrid, HrmGridColumn, HrmOption, HrmPopover, HrmProgress,
  HrmSegmented, HrmSelect, HrmStatCard, HrmStatusCell, HrmTag,
} from 'hrm-ui';
import { ImpMapping, ImpMode, ImportStore } from './import.store';

/** Bước 0 — Thiết lập file: segmented chọn chế độ (Import theo mẫu / ✨ AI Scan),
 *  dropzone upload, mô phỏng AI scan 8 bước, kết quả scan (5 stat-card + bảng mapping 8 dòng
 *  + popover explainability + chấp nhận/chọn lại cột). State sống trong ImportStore. */
@Component({
  selector: 'sg-import-step-setup',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    FormsModule, TablerIconComponent,
    HrmSegmented, HrmSelect, HrmButton, HrmTag, HrmProgress, HrmStatCard, HrmStatusCell,
    HrmGrid, HrmPopover,
  ],
  template: `
    <header class="ims-head">
      <h3 class="ims-title">Thiết lập file</h3>
      <p class="ims-sub">Upload file và để AI tự động phân tích cấu trúc, mapping và chất lượng dữ liệu.</p>
    </header>

    <div class="ims-mode">
      <hrm-segmented [options]="modeOptions" [(ngModel)]="modeVal" />
    </div>

    @if (st.mode() === 'template') {
      <!-- 5.2 · Import theo mẫu -->
      <section class="ims-sec">
        <div class="ims-tpl-row">
          <hrm-select class="ims-tpl-select" [options]="templateOptions"
            [ngModel]="templateKind()" (ngModelChange)="templateKind.set($event)"
            placeholder="Chọn loại template" />
          <hrm-button variant="default">
            <tabler-icon [icon]="icDownload" [size]="16" /> Tải template
          </hrm-button>
        </div>
        <p class="ims-hint">Tải template chuẩn rồi upload — hệ thống tự map theo mẫu.</p>

        @if (!st.file()) {
          <div class="ims-drop" (click)="st.uploadDemo()">
            <tabler-icon class="ims-drop-ic" [icon]="icCloudUpload" [size]="40" />
            <div class="ims-drop-title">Kéo &amp; thả file vào đây</div>
            <hrm-button variant="primary" (click)="pick($event)">Chọn file</hrm-button>
            <div class="ims-drop-ext">.xlsx · .xls · .csv</div>
          </div>
        } @else {
          <div class="ims-fileok">
            <tabler-icon class="ims-fileok-ic" [icon]="icFile" [size]="28" />
            <div class="ims-fileok-body">
              <div class="ims-fileok-name">{{ st.file()?.name }}</div>
              <div class="ims-fileok-meta">{{ st.file()?.rows }} dòng · {{ st.file()?.cols }} cột · {{ st.file()?.size }}</div>
            </div>
            <hrm-status-cell variant="badge" status="success" label="Đã map theo mẫu" />
          </div>
        }
      </section>
    } @else {
      @switch (st.scanPhase()) {
        @case ('idle') {
          <!-- 5.3 · AI Scan — dropzone -->
          <section class="ims-sec">
            <div class="ims-drop ims-drop--ai" (click)="st.uploadDemo()">
              <tabler-icon class="ims-drop-ic ims-drop-ic--ai" [icon]="icSparkles" [size]="40" />
              <div class="ims-drop-title">Kéo &amp; thả file vào đây</div>
              <hrm-button variant="primary" (click)="pick($event)">Chọn file</hrm-button>
              <div class="ims-drop-ext">.xlsx · .xls · .csv</div>
              <div class="ims-drop-ai">AI sẽ tự động phân tích file</div>
            </div>
            <div class="ims-caps">
              <span class="ims-caps-lbl">AI có thể nhận diện:</span>
              @for (c of aiCaps; track c) {
                <hrm-tag color="default">
                  <tabler-icon class="ims-cap-ic" [icon]="icCheck" [size]="12" /> {{ c }}
                </hrm-tag>
              }
            </div>
          </section>
        }
        @case ('scanning') {
          <!-- 5.3 · AI đang phân tích -->
          <section class="ims-sec ims-scan">
            <h4 class="ims-h4">✨ AI đang phân tích file</h4>
            <div class="ims-file-line">
              <tabler-icon class="ims-file-ic" [icon]="icFile" [size]="18" />
              <span class="ims-file-name">{{ st.file()?.name }}</span>
              <span class="ims-file-meta">{{ st.BIG.rows }} dòng · {{ st.BIG.cols }} cột · {{ st.BIG.size }}</span>
            </div>
            <hrm-progress [percent]="st.scanPct()" />
            <ul class="ims-steps">
              @for (s of st.scanSteps(); track s.label) {
                <li class="ims-step" [class.ims-step--todo]="s.state === 'todo'">
                  @switch (s.state) {
                    @case ('done') { <tabler-icon class="ims-step-done" [icon]="icCircleCheck" [size]="16" /> }
                    @case ('active') { <tabler-icon class="ims-step-spin" [icon]="icRefresh" [size]="16" /> }
                    @default { <span class="ims-step-dot"></span> }
                  }
                  <span>{{ s.label }}</span>
                </li>
              }
            </ul>
            <p class="ims-hint">AI đang phân tích {{ st.BIG.cols }} cột và đối chiếu với cấu trúc dữ liệu HRM.</p>
          </section>
        }
        @case ('done') {
          <!-- 5.4 · Kết quả scan -->
          <section class="ims-sec">
            <div class="ims-done-head">
              <h4 class="ims-h4">✨ AI đã phân tích xong</h4>
              <span class="ims-done-meta">{{ st.BIG.rows }} dòng · {{ st.BIG.cols }} cột</span>
              <hrm-tag color="green">Data quality {{ st.BIG.quality }}</hrm-tag>
            </div>

            <div class="ims-stats">
              <hrm-stat-card variant="pastel" orientation="compact" tone="primary"
                [icon]="icListCheck" [value]="st.BIG.cols + '/' + st.BIG.cols" label="Trường được nhận diện" />
              <hrm-stat-card variant="pastel" orientation="compact" tone="success"
                [icon]="icCircleCheck" [value]="st.BIG.mapOk" label="Mapping độ tin cậy cao" />
              <hrm-stat-card variant="pastel" orientation="compact" tone="warning"
                [icon]="icAlert" [value]="st.BIG.mapReview" label="Cần xác nhận" />
              <hrm-stat-card variant="pastel" orientation="compact" tone="error"
                [icon]="icX" [value]="st.BIG.mapMiss" label="Chưa nhận diện" />
              <hrm-stat-card variant="pastel" orientation="compact" tone="warning"
                [icon]="icEye" [value]="st.BIG.warn" label="Dòng cần kiểm tra" />
            </div>

            <!-- 5.5 · Bảng mapping — panel toolbar-dính-bảng kiểu list-page; explainability = hrmPopover -->
            <section class="ims-tablecard">
              <div class="ims-map-head">Mapping trường dữ liệu <span>hiển thị 8 / {{ st.BIG.cols }} trường</span></div>
              <div class="ims-tablewrap">
                <hrm-grid [columns]="mapCols()" [data]="$any(st.mappings())" rowKey="fieldKey"
                  [showPagination]="false" [reorderable]="false" [customizable]="false" size="small" minWidth="640px" />
              </div>
            </section>
            <p class="ims-note">AI không tự áp dụng mapping có độ tin cậy thấp — bạn luôn xem, xác nhận hoặc chọn lại cột trước khi import.</p>

            <!-- Cell templates hrm-grid -->
            <ng-template #fieldCell let-m>
              <span class="ims-map-field">{{ m.fieldLabel }}@if (m.required) {<span class="ims-req">*</span>}</span>
            </ng-template>
            <!-- Cột Excel = dropdown chỉnh lại thủ công cho MỌI dòng (kể cả đã nhận diện) -->
            <ng-template #fileColCell let-m>
              <hrm-select class="ims-mapsel" size="sm" placeholder="Chọn cột trong file"
                [options]="fileColOptions" [ngModel]="m.fileCol"
                (ngModelChange)="onRemap(m.fieldKey, $event)" />
            </ng-template>
            <ng-template #confCell let-m>
              <button type="button" class="ims-conf" hrmPopover [hrmPopoverContent]="explainTpl"
                hrmPopoverTrigger="click" hrmPopoverPlacement="bottomLeft"
                (click)="st.explainKey.set(m.fieldKey)" title="Xem vì sao AI đề xuất mapping này">
                <span class="ims-conf-dot" [attr.data-tone]="confTone(m.status)"></span>
                {{ m.confidence > 0 ? m.confidence + '%' : '—' }}
              </button>
            </ng-template>
            <ng-template #statusCell let-m>
              <div class="ims-map-actions">
                @switch (m.status) {
                  @case ('high') { <hrm-status-cell variant="badge" status="success" label="Đã nhận diện" /> }
                  @case ('review') {
                    <hrm-status-cell variant="badge" status="warning" label="Cần xác nhận" />
                    <hrm-button variant="default" size="sm" (click)="st.acceptMapping(m.fieldKey)">Chấp nhận</hrm-button>
                  }
                  @case ('unmapped') {
                    <hrm-status-cell variant="badge" status="error" label="Chưa nhận diện" />
                  }
                  @default {
                    <hrm-status-cell variant="badge" status="error" label="Cần xác nhận" />
                    <hrm-button variant="default" size="sm" (click)="st.acceptMapping(m.fieldKey)">Chấp nhận</hrm-button>
                  }
                }
              </div>
            </ng-template>

            <!-- Nội dung popover explainability — đọc mapping đang chọn qua explainKey (1 popover mở/lúc) -->
            <ng-template #explainTpl>
              @if (explainMapping(); as m) {
                <div class="ims-explain-in">
                  <div class="ims-explain-title">AI đề xuất mapping này vì:</div>
                  <div class="ims-explain-body">{{ m.reason }}</div>
                  @if (m.fileCol !== null) {
                    <div class="ims-explain-foot">
                      <hrm-button variant="primary" size="sm" (click)="st.acceptMapping(m.fieldKey)">Chấp nhận</hrm-button>
                    </div>
                  }
                </div>
              }
            </ng-template>
          </section>
        }
      }
    }
  `,
  styles: [`
:host { display: flex; flex-direction: column; gap: var(--space-6); padding: var(--space-6); max-width: 960px; margin-inline: auto; width: 100%; }

.ims-head { display: flex; flex-direction: column; gap: var(--space-1); }
.ims-title { margin: 0; font-size: var(--fs-18); font-weight: var(--font-semibold); color: var(--text-strong); }
.ims-sub { margin: 0; font-size: var(--fs-13); color: var(--text-sub); }
.ims-mode { align-self: flex-start; }

.ims-sec { display: flex; flex-direction: column; gap: var(--space-4); }
.ims-hint { margin: 0; font-size: var(--fs-13); color: var(--text-sub); }
.ims-note { margin: 0; font-size: var(--fs-12); color: var(--text-soft); }
.ims-h4 { margin: 0; font-size: var(--fs-15); font-weight: var(--font-semibold); color: var(--text-strong); }

/* — mode template — */
.ims-tpl-row { display: flex; align-items: center; gap: var(--space-3); }
.ims-tpl-select { width: 260px; }
.ims-fileok { display: flex; align-items: center; gap: var(--space-3); padding: var(--space-4);
  border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface); }
.ims-fileok-ic { color: var(--icon-secondary); }
.ims-fileok-body { flex: 1; min-width: 0; }
.ims-fileok-name { font-size: var(--fs-14); font-weight: var(--font-semibold); color: var(--text-strong); }
.ims-fileok-meta { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; }

/* — dropzone — */
.ims-drop { display: flex; flex-direction: column; align-items: center; gap: var(--space-3); text-align: center;
  padding: var(--space-12) var(--space-6); border: 1px dashed var(--border-sub); border-radius: var(--radius-lg);
  cursor: pointer; transition: border-color .15s ease, background .15s ease; }
.ims-drop:hover { border-color: var(--primary-border); background: var(--primary-bg-subtle); }
.ims-drop-ic { color: var(--icon-secondary); }
.ims-drop-ic--ai { color: var(--primary-base); }
.ims-drop-title { font-size: var(--fs-15); font-weight: var(--font-semibold); color: var(--text-strong); }
.ims-drop-ext { font-size: var(--fs-12); color: var(--text-soft); }
.ims-drop-ai { font-size: var(--fs-13); color: var(--primary-base); }

/* — chips năng lực AI — */
.ims-caps { display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-2); }
.ims-caps-lbl { font-size: var(--fs-13); color: var(--text-sub); }
.ims-cap-ic { color: var(--success-base); vertical-align: -2px; margin-right: var(--space-1); }

/* — scanning — */
.ims-scan { max-width: 640px; width: 100%; margin: 0 auto; }
.ims-file-line { display: flex; align-items: center; gap: var(--space-2); font-size: var(--fs-13); color: var(--text-sub); }
.ims-file-ic { color: var(--icon-secondary); }
.ims-file-name { font-weight: var(--font-medium); color: var(--text-strong); }
.ims-file-meta { font-variant-numeric: tabular-nums; }
.ims-steps { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--space-2); }
.ims-step { display: flex; align-items: center; gap: var(--space-2); font-size: var(--fs-13); color: var(--text-body); }
.ims-step--todo { color: var(--text-soft); }
.ims-step-done { color: var(--success-base); }
.ims-step-spin { color: var(--primary-base); animation: ims-rot .9s linear infinite; }
.ims-step-dot { flex: none; width: 8px; height: 8px; margin: var(--space-1); border-radius: var(--radius-full); background: var(--border-strong); }
@keyframes ims-rot { to { transform: rotate(360deg); } }

/* — kết quả scan — */
.ims-done-head { display: flex; align-items: center; gap: var(--space-3); flex-wrap: wrap; }
.ims-done-meta { font-size: var(--fs-13); color: var(--text-sub); font-variant-numeric: tabular-nums; }
.ims-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: var(--space-3); }

.ims-map-field { font-weight: var(--font-medium); color: var(--text-strong); white-space: nowrap; }
.ims-req { color: var(--error-base); margin-left: var(--space-1); }
.ims-map-col { font-variant-numeric: tabular-nums; }
.ims-map-actions { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
.ims-remap { display: inline-block; width: 220px; }

/* Panel bảng mapping kiểu list-page: viền bo overflow-hidden, head = toolbar band (border-bottom), grid flush */
.ims-tablecard { border: 1px solid var(--border-sub); border-radius: var(--radius-lg); overflow: hidden; }
.ims-map-head { display: flex; align-items: baseline; gap: var(--space-2); padding: var(--space-2-5) var(--space-3);
  border-bottom: 1px solid var(--border-sub); font-size: var(--fs-14); font-weight: var(--font-semibold); color: var(--text-strong); }
.ims-tablewrap { min-width: 0; }
.ims-tablewrap ::ng-deep .ant-table { border: 0; border-radius: 0; background: transparent; }
.ims-map-head span { font-size: var(--fs-12); font-weight: var(--font-regular); color: var(--text-soft); }
.ims-map-field { font-weight: var(--font-medium); color: var(--text-strong); white-space: nowrap; }
.ims-req { color: var(--error-base); margin-left: var(--space-1); }
.ims-map-col { font-variant-numeric: tabular-nums; }
.ims-map-actions { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
.ims-mapsel { display: block; width: 100%; min-width: 150px; }
.ims-explain-in { display: block; max-width: 300px; }
/* — confidence + popover explainability — */
.ims-conf { display: inline-flex; align-items: center; gap: var(--space-2); border: 0; background: transparent;
  font: inherit; font-size: var(--fs-13); color: var(--text-body); font-variant-numeric: tabular-nums;
  padding: var(--space-1) var(--space-2); border-radius: var(--radius-sm); cursor: pointer; }
.ims-conf:hover { background: var(--bg-surface-subtle); }
.ims-conf:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 1px; }
.ims-conf-dot { flex: none; width: 8px; height: 8px; border-radius: var(--radius-full); }
.ims-conf-dot[data-tone='success'] { background: var(--success-base); }
.ims-conf-dot[data-tone='warning'] { background: var(--warning-base); }
.ims-conf-dot[data-tone='error'] { background: var(--error-base); }
.ims-explain-title { font-size: var(--fs-13); font-weight: var(--font-semibold); color: var(--text-strong); margin-bottom: var(--space-2); }
.ims-explain-body { font-size: var(--fs-13); color: var(--text-body); white-space: pre-line; }
.ims-explain-foot { display: flex; gap: var(--space-2); margin-top: var(--space-3); }
  `],
})
export class SgImportStepSetup {
  protected readonly st = inject(ImportStore);

  protected readonly icSparkles = IconSparkles;
  protected readonly icCloudUpload = IconCloudUpload;
  protected readonly icDownload = IconDownload;
  protected readonly icCheck = IconCheck;
  protected readonly icCircleCheck = IconCircleCheck;
  protected readonly icRefresh = IconRefresh;
  protected readonly icFile = IconFileSpreadsheet;
  protected readonly icListCheck = IconListCheck;
  protected readonly icAlert = IconAlertTriangle;
  protected readonly icX = IconX;
  protected readonly icEye = IconEye;

  protected readonly modeOptions = [
    { label: 'Import theo mẫu', value: 'template' },
    { label: '✨ AI Scan', value: 'ai' },
  ];
  protected readonly templateOptions: HrmOption[] = [
    { label: 'Danh sách nhân viên', value: 'emp' },
    { label: 'Hợp đồng', value: 'contract' },
    { label: 'Chấm công', value: 'attendance' },
  ];
  /** FILE_COLS theo contract §3 — lặp cục bộ thành options cho select remap. */
  protected readonly fileColOptions: HrmOption[] = [
    'Full Name', 'Email Address', 'Mobile', 'Dept', 'Job Title', 'Status', 'Join Date', 'Emp Code',
  ].map((c) => ({ label: c, value: c }));
  protected readonly aiCaps = [
    'Tên trường', 'Kiểu dữ liệu', 'Mapping HRM', 'Dữ liệu trùng', 'Dữ liệu thiếu',
    'Format bất thường', 'Master data mismatch',
  ];

  /** Loại template (mode 'template') — chọn local, demo. */
  protected readonly templateKind = signal<string>('emp');

  /** ngModel bridge cho hrm-segmented ↔ st.mode. */
  protected get modeVal(): string | number { return this.st.mode(); }
  protected set modeVal(v: string | number) { this.st.mode.set(v as ImpMode); }

  /** Nút "Chọn file" nằm trong dropzone (dropzone cũng click) → chặn nổi bọt để không upload 2 lần. */
  protected pick(e: Event): void {
    e.stopPropagation();
    this.st.uploadDemo();
  }

  protected onRemap(key: string, col: unknown): void {
    if (typeof col === 'string' && col) this.st.remap(key, col);
  }

  protected confTone(status: ImpMapping['status']): 'success' | 'warning' | 'error' {
    return status === 'high' ? 'success' : status === 'review' ? 'warning' : 'error';
  }

  // ── hrm-grid cột + cell template cho bảng mapping ──
  private readonly fieldCell = viewChild<TemplateRef<any>>('fieldCell');
  private readonly fileColCell = viewChild<TemplateRef<any>>('fileColCell');
  private readonly confCell = viewChild<TemplateRef<any>>('confCell');
  private readonly statusCell = viewChild<TemplateRef<any>>('statusCell');
  protected readonly mapCols = computed<HrmGridColumn[]>(() => [
    { key: 'fieldLabel', title: 'Trường HRM', width: '180px', cell: this.fieldCell() },
    { key: 'fileCol', title: 'Cột trong file', width: '210px', cell: this.fileColCell() },
    { key: 'confidence', title: 'AI confidence', width: '140px', cell: this.confCell() },
    { key: 'status', title: 'Trạng thái', width: '260px', cell: this.statusCell() },
  ]);

  /** Mapping đang mở popover explain (1 popover mở/lúc) — nội dung popover đọc từ đây. */
  protected readonly explainMapping = computed<ImpMapping | undefined>(() =>
    this.st.mappings().find((m) => m.fieldKey === this.st.explainKey()));
}
