import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconHistory, IconSearch, IconX, TablerIconComponent } from '@tabler/icons-angular';
import { HrmButton, HrmEmpty, HrmGrid, HrmGridColumn, HrmInput, HrmOption, HrmSelect, HrmStatusCell } from 'hrm-ui';
import { ImportStore, ImpHistoryRow } from './import.store';

/** Lịch sử import — overlay absolute phủ TRONG dialog wizard (không phải overlay toàn màn).
 *  Header + filter (search hoạt động thật, 2 select trình diễn) + BẢNG hrm-grid 4 lần import từ st.history. */
@Component({
  selector: 'sg-import-history',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule, TablerIconComponent, HrmButton, HrmInput, HrmSelect, HrmStatusCell, HrmGrid, HrmEmpty],
  template: `
    <div class="imh-head">
      <div class="imh-title">
        <tabler-icon [icon]="icHistory" [size]="18" />
        <h3>Lịch sử import</h3>
      </div>
      <hrm-button variant="text" [iconOnly]="true" ariaLabel="Đóng lịch sử" (click)="close()">
        <tabler-icon [icon]="icX" [size]="18" />
      </hrm-button>
    </div>

    <!-- Panel toolbar-dính-bảng kiểu list-page: filter = toolbar band, grid flush -->
    <div class="imh-body">
      <section class="imh-tablecard">
        <div class="imh-filter">
          <hrm-input class="imh-search" [(ngModel)]="search" [prefixIcon]="icSearch"
            [clearable]="true" placeholder="Tìm theo tên file, người import..." />
          <hrm-select class="imh-sel" [(ngModel)]="statusFilter" [options]="statusOptions"
            placeholder="Trạng thái" />
          <hrm-select class="imh-sel" [(ngModel)]="timeFilter" [options]="timeOptions"
            placeholder="Khoảng thời gian" />
        </div>
        <div class="imh-tablewrap">
          @if (viewRows().length) {
            <hrm-grid [columns]="cols()" [data]="$any(viewRows())" rowKey="file"
              [showPagination]="false" [reorderable]="false" [customizable]="false"
              size="small" minWidth="880px" />
          } @else {
            <hrm-empty preset="no-results" description="Không tìm thấy lần import nào phù hợp." />
          }
        </div>
      </section>
    </div>

    <!-- Cell templates -->
    <ng-template #fileCell let-r><span class="imh-file">{{ r.file }}</span></ng-template>
    <ng-template #errCell let-r><span [class.imh-err]="r.err !== '0'">{{ r.err }}</span></ng-template>
    <ng-template #statusCell let-r>
      <hrm-status-cell variant="badge" [status]="ST[$any(r).status].tone" [label]="ST[$any(r).status].label" />
    </ng-template>
    <ng-template #actCell><hrm-button variant="text" size="sm">Xem chi tiết</hrm-button></ng-template>
  `,
  styles: [`
:host {
  position: absolute; inset: 0; z-index: var(--z-modal);
  display: flex; flex-direction: column;
  background: var(--bg-surface);
}
.imh-head {
  flex: none; display: flex; align-items: center; justify-content: space-between;
  gap: var(--space-3); padding: var(--space-4) var(--space-5);
  border-bottom: 1px solid var(--border-sub);
}
.imh-title { display: flex; align-items: center; gap: var(--space-2); color: var(--icon-secondary); }
.imh-title h3 { margin: 0; font-size: var(--fs-16); font-weight: var(--font-semibold); color: var(--text-strong); }
.imh-filter {
  flex: none; display: flex; align-items: center; flex-wrap: wrap;
  gap: var(--space-3); padding: var(--space-2-5) var(--space-3);
  border-bottom: 1px solid var(--border-sub);
}
.imh-search { flex: 1 1 260px; max-width: 380px; }
.imh-sel { width: 200px; }
.imh-body { flex: 1 1 auto; min-height: 0; overflow: hidden; padding: var(--space-5); }
/* Panel list-page: viền bo overflow-hidden, filter band trên + grid flush cuộn trong */
.imh-tablecard { display: flex; flex-direction: column; min-height: 0; height: 100%;
  border: 1px solid var(--border-sub); border-radius: var(--radius-lg); overflow: hidden; }
.imh-tablewrap { flex: 1 1 auto; min-height: 0; overflow: auto; }
.imh-tablewrap ::ng-deep .ant-table { border: 0; border-radius: 0; background: transparent; }
.imh-file { font-weight: var(--font-medium); color: var(--text-strong); white-space: nowrap; }
.imh-err { color: var(--error-base); }
  `],
})
export class SgImportHistory {
  protected readonly st = inject(ImportStore);

  protected readonly icHistory = IconHistory;
  protected readonly icSearch = IconSearch;
  protected readonly icX = IconX;

  /** Search hoạt động thật trên tên file / người import. */
  protected readonly search = signal('');
  /** 2 filter trình diễn (no-op theo contract §9). */
  protected readonly statusFilter = signal<string | null>(null);
  protected readonly timeFilter = signal<string | null>(null);

  protected readonly statusOptions: HrmOption<string>[] = [
    { label: 'Tất cả trạng thái', value: 'all' },
    { label: 'Thành công', value: 'ok' },
    { label: 'Thành công một phần', value: 'partial' },
    { label: 'Thất bại', value: 'fail' },
  ];
  protected readonly timeOptions: HrmOption<string>[] = [
    { label: '7 ngày qua', value: '7d' },
    { label: '30 ngày qua', value: '30d' },
    { label: 'Quý này', value: 'quarter' },
    { label: 'Tất cả', value: 'all' },
  ];

  /** Map trạng thái lịch sử → tông + nhãn hiển thị. */
  protected readonly ST: Record<ImpHistoryRow['status'], { tone: 'success' | 'warning' | 'error'; label: string }> = {
    ok: { tone: 'success', label: 'Thành công' },
    partial: { tone: 'warning', label: 'Thành công một phần' },
    fail: { tone: 'error', label: 'Thất bại' },
  };

  // ── Cell templates cho hrm-grid ──
  private readonly fileCell = viewChild<TemplateRef<any>>('fileCell');
  private readonly errCell = viewChild<TemplateRef<any>>('errCell');
  private readonly statusCell = viewChild<TemplateRef<any>>('statusCell');
  private readonly actCell = viewChild<TemplateRef<any>>('actCell');

  protected readonly cols = computed<HrmGridColumn[]>(() => [
    { key: 'file', title: 'File', width: '220px', cell: this.fileCell() },
    { key: 'user', title: 'Người import', width: '140px' },
    { key: 'time', title: 'Thời gian', width: '130px' },
    { key: 'total', title: 'Tổng dòng', width: '110px', align: 'right' },
    { key: 'ok', title: 'Thành công', width: '110px', align: 'right' },
    { key: 'err', title: 'Lỗi', width: '90px', align: 'right', cell: this.errCell() },
    { key: 'quality', title: 'Data Quality', width: '120px', align: 'right' },
    { key: 'status', title: 'Trạng thái', width: '160px', cell: this.statusCell() },
    { key: 'act', title: '', width: '110px', align: 'right', cell: this.actCell() },
  ]);

  protected readonly viewRows = computed<ImpHistoryRow[]>(() => {
    const q = this.search().trim().toLowerCase();
    if (!q) return this.st.history;
    return this.st.history.filter(
      (r) => r.file.toLowerCase().includes(q) || r.user.toLowerCase().includes(q),
    );
  });

  protected close(): void {
    this.st.historyOpen.set(false);
  }
}
