import { Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';
import {
  IconEdit, IconTrash, IconPlus, IconFilter, IconCheck,
  IconClock, TablerIconComponent,
  IconBuilding, IconMail, IconUserCog,
  IconDownload, IconArrowsMaximize, IconCamera, IconFilterOff,
} from '@tabler/icons-angular';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import {
  HrmBoardGroup, HrmAppShell, HrmInput, HrmButton, HrmSelect,
  HrmUserCell, HrmTextCell, HrmStatusCell, HrmActionCell, HrmActionItem,
  HrmDetailPeek, HrmPeekMode, HrmCheckbox, HrmPopover, HrmOption,
  HrmWorkflowStatus, HRM_WORKFLOW_ACTIONS, HrmActionBar, HrmActionBarItem,
  HrmDataWorkspace, HrmWorkspaceQuickFilter,
  HrmColumnDef, HrmColumnGroup, HrmRowGroupLevel, HrmGridSort,
} from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont } from '../../../doc/sg-blocks';
import { SgTemplateSideNav } from './_template-side-nav';
import { PEOPLE, STAGES, fmtDM, EmpRow } from './_people';
import { SgEmpDetail } from './emp-detail-card';
import { SgFormBuilder } from '../feature/sg-form-builder';
import { SgImportWizard } from './import/import-wizard';
import { SgFeatureExportCenter } from '../feature/export-center/export-center-page';

/** Doc page · Chế độ xem dữ liệu (Template) — TEMPLATE MẪU CHUẨN màn danh sách:
 *  App Shell default (side nav nhóm cha-con) + list-page (breadcrumb/tiêu đề/toolbar) +
 *  hrm-data-view đa chế độ (Bảng/Thẻ/Kanban/Gantt kiểu ClickUp). Song ngữ docs.listPage.*. */
@Component({
  selector: 'sg-doc-list-page',
  imports: [
    FormsModule, NgTemplateOutlet, TablerIconComponent, TranslateModule,
    HrmDataWorkspace, HrmAppShell, SgTemplateSideNav, HrmInput, HrmButton, HrmSelect,
    HrmUserCell, HrmTextCell, HrmStatusCell, HrmActionCell, HrmDetailPeek, HrmActionBar,
    HrmCheckbox, HrmPopover,
    SgEmpDetail, SgFormBuilder, SgImportWizard, SgFeatureExportCenter,
    SgDoc, SgUse, SgDo, SgDont,
  ],
  template: `
    @if (preview) {
      <!-- Chế độ preview (route /preview/list-page, tab mới) — full viewport thật. -->
      <div class="lp-desktop lp-desktop--full"><ng-container *ngTemplateOutlet="screen" /></div>
    } @else {
    <sg-doc category="Template" [title]="'docs.listPage.title' | translate" [desc]="'docs.listPage.desc' | translate">

      <div sgOverview>
        <!-- MÀN CHUẨN — desktop lớn: App Shell default + list-page + đa chế độ xem. -->
        <div class="lp-desktop"><ng-container *ngTemplateOutlet="screen" /></div>
        <div class="lp-full">
          <a class="lp-full-link" href="/preview/list-page" target="_blank" rel="noopener">
            <hrm-button variant="default">
              <tabler-icon [icon]="maximize" [size]="16" /> {{ 'sg.openFull' | translate }}
            </hrm-button>
          </a>
        </div>
      </div>

      <div sgUsage>
        <sg-use [purpose]="'docs.listPage.purpose' | translate" [when]="when"
          [behavior]="'docs.listPage.behavior' | translate"
          [avoid]="'docs.listPage.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do>{{ 'docs.listPage.do1' | translate }}</sg-do>
        <sg-do>{{ 'docs.listPage.do2' | translate }}</sg-do>
        <sg-dont>{{ 'docs.listPage.dont1' | translate }}</sg-dont>
      </div>

    </sg-doc>
    }

    <!-- Màn danh sách (App Shell + hrm-data-workspace) — dùng chung cho doc (khung) & preview (full tab mới).
         hrm-data-workspace gói dàn nhạc toolbar (segmented + tìm + 2 lọc nhanh + Nhóm/Xuất/⋮) + bảng
         đa chế độ + overlay Cấu hình cột/sắp xếp. Consumer chỉ truyền cột/data/quickFilters/flags + điền slot. -->
    <ng-template #screen>
      <hrm-app-shell contentPad="none">
        <sg-template-side-nav appSideNav selectedKey="emp-list" />
        <hrm-data-workspace
          [title]="'docs.listPage.pageTitle' | translate"
          [columns]="mcols()" [cellTemplates]="$any(cellByKey())" [computedCell]="computedCell"
          [data]="filteredPeople()" rowKey="id" tableMinWidth="620px"
          [modes]="['table','card','kanban','gantt']" [(mode)]="mode"
          [selectable]="true" bulkUnit="nhân viên" [(selectedKeys)]="selKeys"
          [total]="mode === 'table' ? 120 : 0" [(pageIndex)]="page" [pageSize]="10" [showSizeChanger]="true"
          [searchPlaceholder]="'docs.listPage.searchPh' | translate" [(search)]="kw"
          [quickFilters]="wsQuickFilters" [(quickFilterValues)]="qfValues"
          [groupable]="true" [exportable]="true" [importable]="true" [printable]="true"
          [columnConfig]="true" [sortConfig]="true" [formConfig]="true"
          [(sortLevels)]="sortLevels" [(hiddenKeys)]="hiddenKeys" [(rowGroups)]="rowGroups"
          [(showGroupPanel)]="showGroups" [(columnGroups)]="mgroups"
          [groupLabelFormatter]="groupLabel"
          groupBy="stage" [boardGroups]="boardGroups()"
          [cardTemplate]="dvCard" [boardCardTemplate]="bdCard" boardAddLabel="Thêm nhân viên" (boardAdd)="openCreate()"
          startField="start" endField="end" progressField="progress" ganttLabelField="name"
          ganttHeader="Nhân viên" ganttDateHeader="Hạn" [ganttLabelTemplate]="gtLabel" [ganttBarTone]="ganttTone"
          (rowClick)="openEmp($event)"
          (importClick)="moreAction('import')" (printClick)="moreAction('print')"
          (exportClick)="exportOpen.set(true)"
          (formConfigClick)="fbOpen.set(true)">

          <!-- Cạnh segmented (segmented do workspace tự render từ [modes]) — nút "Thêm nhân viên". -->
          <hrm-button wsHeaderActions variant="primary" (click)="openCreate()">
            <tabler-icon [icon]="plus" [size]="18" /> Thêm nhân viên
          </hrm-button>

          <!-- Bộ lọc → popover panel (nội dung tùy ý = form lọc); badge đếm số điều kiện đang bật.
               State CHUNG _f với 2 quick-filter của workspace ⇒ đồng bộ badge + kết quả. -->
          <hrm-button wsFilterPanel variant="default" hrmPopover [hrmPopoverContent]="filterPanel"
            hrmPopoverTrigger="click" hrmPopoverPlacement="bottomLeft" [class.tbx-on]="filterCount() > 0">
            <tabler-icon [icon]="filter" [size]="18" /> {{ 'docs.listPage.filterBtn' | translate }}
            @if (filterCount() > 0) { <span class="tbx-badge">{{ filterCount() }}</span> }
          </hrm-button>

          <!-- Hành động hàng loạt (hiện khi có chọn) — thay cụm nút chuẩn của workspace. -->
          <ng-container wsBulkActions>
            <hrm-button variant="primary" (click)="bulkDone()"><tabler-icon [icon]="check" [size]="16" /> Duyệt chính thức</hrm-button>
            <hrm-button variant="default"><tabler-icon [icon]="download" [size]="16" /> Xuất</hrm-button>
            <hrm-button variant="default" [danger]="true" (click)="bulkDelete()"><tabler-icon [icon]="trash" [size]="16" /> Xoá</hrm-button>
          </ng-container>

          <!-- Chi tiết bản ghi HOẶC form Thêm/Sửa — CÙNG surface đa chế độ: master (slot lpDetail
               qua wsDetail) · side (drawer) · center (modal) · full/tab (route). -->
          <hrm-detail-peek wsDetail [(open)]="peekOpen" [(peekMode)]="peekMode"
            [modes]="['master','side','center','full','tab']" [expandable]="false"
            [title]="peekTitle()" [content]="peekContent()" [footer]="peekKind() === 'detail' ? peekFooter : empFooter" [modeLabels]="peekLabels"
            [routeUrl]="peekRoute()"
            switchLabel="Đổi cách hiển thị" expandLabel="Mở toàn trang" closeLabel="Đóng"
            resizeLabel="Kéo đổi độ rộng" />
        </hrm-data-workspace>

        <!-- Wizard Import dữ liệu (AI Data Import) — mở từ ⋮ Nhập dữ liệu. -->
        <sg-import-wizard [(open)]="importOpen" />

        <!-- Export Center — MODAL Xuất dữ liệu, mở từ chính nút "Xuất dữ liệu" của list-page
             (exportClick → exportOpen). KHÔNG còn là page riêng ở nav tính năng. -->
        <sg-feature-export-center [(open)]="exportOpen" />
      </hrm-app-shell>
    </ng-template>

    <!-- Nội dung chi tiết — thẻ dùng chung (cũng render ở trang toàn trang list-record).
         Đầu drawer: TRẠNG THÁI QUY TRÌNH + cụm nút hành động (hrm-workflow-actions) — bấm sẽ
         CHUYỂN trạng thái theo State Machine (cột bảng + chip cập nhật ngay). -->
    <ng-template #empDetail let-surface>
      @if (selected(); as r) {
        <sg-emp-detail [emp]="$any(r)" [wfStatus]="wfOf(r)" (wfAction)="doWf(r, $event)" [surfaceMode]="$any(surface)" />
      }
    </ng-template>

    <!-- FOOTER chi tiết (mọi surface master/side/center): cụm hành động ghim chân — quy trình + Duyệt/Sửa.
         hrm-action-bar: responsive KHÔNG rớt hàng, nút dư thu vào ⋮ góc phải. -->
    <ng-template #peekFooter>
      @if (selected(); as r) {
        <hrm-action-bar [actions]="footerActions(r)" moreLabel="Thêm thao tác" (action)="onFooterAction(r, $event)" />
      }
    </ng-template>

    <!-- Form Thêm/Sửa nhân viên — nội dung của CÙNG hrm-detail-peek (dùng chung mọi surface).
         Chia SECTION · body cuộn · FOOTER ghim đáy (sticky) mọi surface (drawer/modal/master/full). -->
    <ng-template #empForm>
      <form class="ef" (ngSubmit)="saveEmp()">
        <div class="ef-body">
          <!-- Thông tin cơ bản + avatar -->
          <section class="ef-sec">
            <div class="ef-sec-h">Thông tin cơ bản</div>
            <div class="ef-id">
              <label class="ef-ava" aria-label="Tải ảnh đại diện">
                @if (form.avatar) { <img class="ef-ava-img" [src]="form.avatar" alt="" /> }
                @else { <span class="ef-ava-ph"><tabler-icon [icon]="camera" [size]="22" /></span> }
                <span class="ef-ava-badge"><tabler-icon [icon]="camera" [size]="13" /></span>
                <input type="file" accept="image/*" class="ef-ava-in" (change)="onAvatar($event)" />
              </label>
              <div class="ef-grid ef-id-fields">
                <label class="ef-field ef-field--full">
                  <span class="ef-lbl">Họ và tên <b class="ef-req">*</b></span>
                  <hrm-input name="name" [(ngModel)]="form.name" placeholder="Nhập họ và tên" />
                </label>
                <label class="ef-field">
                  <span class="ef-lbl">Chức vụ</span>
                  <hrm-select name="role" [(ngModel)]="form.role" [options]="roleOptions" placeholder="Chọn chức vụ" />
                </label>
                <label class="ef-field">
                  <span class="ef-lbl">Trạng thái</span>
                  <hrm-select name="status" [(ngModel)]="form.status" [options]="statusOptions" />
                </label>
                <label class="ef-field ef-field--full">
                  <span class="ef-lbl">Giai đoạn onboarding</span>
                  <hrm-select name="stage" [(ngModel)]="form.stage" [options]="stageOptions" />
                </label>
              </div>
            </div>
          </section>

          <!-- Thông tin liên hệ -->
          <section class="ef-sec">
            <div class="ef-sec-h">Thông tin liên hệ</div>
            <div class="ef-grid">
              <label class="ef-field"><span class="ef-lbl">Email</span><hrm-input name="email" [(ngModel)]="form.email" placeholder="email@vnr.vn" /></label>
              <label class="ef-field"><span class="ef-lbl">Số điện thoại</span><hrm-input name="phone" [(ngModel)]="form.phone" placeholder="09xx xxx xxx" /></label>
              <label class="ef-field ef-field--full"><span class="ef-lbl">Địa chỉ</span><hrm-input name="address" [(ngModel)]="form.address" placeholder="Số nhà, đường, phường/xã, quận/huyện, tỉnh/TP" /></label>
            </div>
          </section>

          <!-- Giấy tờ tùy thân -->
          <section class="ef-sec">
            <div class="ef-sec-h">Giấy tờ tùy thân</div>
            <div class="ef-grid">
              <label class="ef-field"><span class="ef-lbl">Loại giấy tờ</span><hrm-select name="idType" [(ngModel)]="form.idType" [options]="idTypeOptions" /></label>
              <label class="ef-field"><span class="ef-lbl">Số</span><hrm-input name="idNo" [(ngModel)]="form.idNo" placeholder="Nhập số giấy tờ" /></label>
              <label class="ef-field"><span class="ef-lbl">Ngày cấp</span><hrm-input name="idDate" [(ngModel)]="form.idDate" placeholder="dd/mm/yyyy" /></label>
              <label class="ef-field"><span class="ef-lbl">Nơi cấp</span><hrm-input name="idPlace" [(ngModel)]="form.idPlace" placeholder="Nơi cấp" /></label>
            </div>
          </section>

          <!-- Kinh nghiệm làm việc (danh sách thêm/xoá) -->
          <section class="ef-sec">
            <div class="ef-sec-h">Kinh nghiệm làm việc
              <button type="button" class="ef-add" (click)="addExp()"><tabler-icon [icon]="plus" [size]="15" /> Thêm</button>
            </div>
            @for (ex of form.experiences; track $index) {
              <div class="ef-exp">
                <div class="ef-grid">
                  <label class="ef-field"><span class="ef-lbl">Công ty</span><hrm-input [name]="'exp-co-' + $index" [(ngModel)]="ex.company" placeholder="Tên công ty" /></label>
                  <label class="ef-field"><span class="ef-lbl">Vị trí</span><hrm-input [name]="'exp-pos-' + $index" [(ngModel)]="ex.position" placeholder="Chức danh" /></label>
                  <label class="ef-field ef-field--full"><span class="ef-lbl">Thời gian</span><hrm-input [name]="'exp-per-' + $index" [(ngModel)]="ex.period" placeholder="VD: 2020 – 2023" /></label>
                </div>
                @if (form.experiences.length > 1) {
                  <button type="button" class="ef-exp-del" (click)="removeExp($index)" aria-label="Xoá kinh nghiệm"><tabler-icon [icon]="trash" [size]="15" /></button>
                }
              </div>
            }
          </section>
        </div>

      </form>
    </ng-template>

    <!-- FOOTER form — dùng slot [footer] của peek (GIỐNG view chi tiết) ⇒ cùng .dp-mfoot,
         chiều cao bottom-nav ĐỒNG BỘ với chi tiết (55px), không còn .ef-foot cao 69px riêng. -->
    <ng-template #empFooter>
      <div class="ef-foot">
        <hrm-button variant="default" (click)="peekOpen.set(false)">Hủy</hrm-button>
        <hrm-button variant="primary" (click)="saveEmp()">
          <tabler-icon [icon]="check" [size]="16" /> {{ formMode() === 'create' ? 'Thêm nhân viên' : 'Lưu thay đổi' }}
        </hrm-button>
      </div>
    </ng-template>

    <ng-template #userCell let-r>
      <hrm-user-cell [name]="$any(r.name)" [colorful]="true" [avatarSize]="30" />
    </ng-template>
    <ng-template #roleCell let-r>
      <hrm-text-cell [primary]="$any(r.role) | translate" />
    </ng-template>
    <!-- Cột Trạng thái = TRẠNG THÁI QUY TRÌNH (State Machine) qua [preset] — tự tông + nhãn. -->
    <ng-template #statusCell let-r>
      <hrm-status [preset]="wfOf(r)" variant="badge" [dot]="true" />
    </ng-template>
    <ng-template #actionCell let-r>
      <hrm-action-cell [actions]="rowActions" [moreLabel]="'docs.enterpriseGrid.moreLabel' | translate" (action)="onRowAction($event, r)" />
    </ng-template>
    <!-- Ô mặc định cho CỘT TÍNH TOÁN (demo — giá trị suy từ công thức, chưa chạy engine). -->
    <ng-template #computedCell let-r>
      <hrm-text-cell [primary]="'—'" />
    </ng-template>
    <!-- Thẻ view "Thẻ" — duyệt trực quan: nhận diện người + trạng thái + action.
         Chân thẻ: component TRẠNG THÁI (hrm-status, thay tag giai đoạn cũ) + cụm icon-button CÓ VIỀN. -->
    <ng-template #dvCard let-r>
      <div class="ec">
        <div class="ec-top">
          <hrm-user-cell [name]="$any(r.name)" [sub]="$any(r.role) | translate" [colorful]="true" [avatarSize]="38" />
        </div>
        <!-- Meta nhân viên — mỗi field 1 dòng icon + giá trị; chỉ hiện dòng CÓ dữ liệu. -->
        <div class="ec-meta">
          @if (r.email) { <div class="mrow"><tabler-icon [icon]="mailIcon" [size]="14" /><span>{{ r.email }}</span></div> }
          @if (r.dept) { <div class="mrow"><tabler-icon [icon]="deptIcon" [size]="14" /><span>{{ r.dept }}</span></div> }
          @if (r.manager) { <div class="mrow"><tabler-icon [icon]="mgrIcon" [size]="14" /><span>{{ r.manager }}</span></div> }
          @if (r.tenure) { <div class="mrow"><tabler-icon [icon]="clockIcon" [size]="14" /><span>{{ $any(r.tenure) | translate }}</span></div> }
        </div>
        <div class="ec-foot">
          <hrm-status [status]="r.status === 'active' ? 'success' : 'error'"
            [label]="(r.status === 'active' ? 'docs.enterpriseGrid.statusActive' : 'docs.enterpriseGrid.statusAbsent') | translate"
            variant="badge" [dot]="true" />
          <hrm-action-cell [bordered]="true" [actions]="rowActions" [moreLabel]="'docs.enterpriseGrid.moreLabel' | translate" (action)="onRowAction($event, r)" />
        </div>
      </div>
    </ng-template>

    <!-- Panel Bộ lọc (nội dung popover) — nhóm checkbox Trạng thái + Giai đoạn, footer Đặt lại/Áp dụng. -->
    <ng-template #filterPanel>
      <div class="flt">
        <div class="flt-grp">
          <div class="flt-h">Trạng thái chuyên cần</div>
          <hrm-checkbox [(ngModel)]="fActive">Đang làm</hrm-checkbox>
          <hrm-checkbox [(ngModel)]="fAbsent">Vắng</hrm-checkbox>
        </div>
        <div class="flt-grp">
          <div class="flt-h">Giai đoạn</div>
          <hrm-checkbox [(ngModel)]="fTodo">Chờ nhận việc</hrm-checkbox>
          <hrm-checkbox [(ngModel)]="fDoing">Đang thử việc</hrm-checkbox>
          <hrm-checkbox [(ngModel)]="fDone">Chính thức</hrm-checkbox>
        </div>
        <div class="flt-foot">
          <hrm-button variant="text" size="sm" [disabled]="filterCount() === 0" (click)="resetFilter()">
            <tabler-icon [icon]="filterOff" [size]="15" /> Đặt lại
          </hrm-button>
          <span class="flt-res">{{ filteredPeople().length }} kết quả</span>
        </div>
      </div>
    </ng-template>

    <!-- Ô nhãn trái Gantt — chấm chuyên cần + avatar + tên + chức vụ (đồng bộ danh tính với bảng/thẻ). -->
    <ng-template #gtLabel let-r>
      <span class="gl">
        <hrm-status-cell [status]="r.status === 'active' ? 'success' : 'error'" variant="dot" />
        <hrm-user-cell [name]="$any(r.name)" [sub]="$any(r.role) | translate" [colorful]="true" [avatarSize]="26" />
      </span>
    </ng-template>

    <!-- Thẻ Kanban — GỌN hơn (cột hẹp, quét nhanh): danh tính + action icon CÓ VIỀN;
         chân = component TRẠNG THÁI (hrm-status, badge) + hạn thử việc. -->
    <ng-template #bdCard let-r>
      <div class="kc">
        <div class="kc-top">
          <hrm-user-cell [name]="$any(r.name)" [sub]="$any(r.role) | translate" [colorful]="true" [avatarSize]="30" />
          <hrm-action-cell [bordered]="true" [max]="2" [actions]="rowActions" [moreLabel]="'docs.enterpriseGrid.moreLabel' | translate" (action)="onRowAction($event, r)" />
        </div>
        <!-- Meta gọn cho kanban: email + phòng (chỉ hiện field có dữ liệu). -->
        <div class="kc-meta">
          @if (r.email) { <div class="mrow"><tabler-icon [icon]="mailIcon" [size]="13" /><span>{{ r.email }}</span></div> }
          @if (r.dept) { <div class="mrow"><tabler-icon [icon]="deptIcon" [size]="13" /><span>{{ r.dept }}</span></div> }
        </div>
        <div class="kc-foot">
          <hrm-status [status]="r.status === 'active' ? 'success' : 'error'"
            [label]="(r.status === 'active' ? 'docs.enterpriseGrid.statusActive' : 'docs.enterpriseGrid.statusAbsent') | translate"
            variant="badge" [dot]="true" />
          <span class="kc-date">{{ endText(r) }}</span>
        </div>
      </div>
    </ng-template>

    <!-- Cụm Sắp xếp / Cấu hình cột đã CHUYỂN VÀO <hrm-data-workspace> (mở qua ⋮) — bỏ overlay inline ở đây. -->

    <!-- Form Builder no-code (overlay full-screen) — thiết kế biểu mẫu "Thêm nhân viên";
         mở từ ⋮ "Cấu hình biểu mẫu" của workspace qua (formConfigClick). -->
    <sg-form-builder [(open)]="fbOpen" />
  `,
  styles: [`
    /* Preview desktop lớn — dễ xem như màn hình thật. */
    .lp-desktop { height: 760px; border: 1px solid var(--border-sub); border-radius: var(--radius-xl); overflow: hidden; box-shadow: var(--shadow-regular-sm); }
    .lp-full { margin-top: 14px; }
    .lp-full-link { text-decoration: none; }
    /* Preview (route /preview/list-page, tab mới) — khung phủ full viewport, bỏ viền/bo. */
    .lp-desktop--full { height: 100vh; border: 0; border-radius: 0; box-shadow: none; }
    /* Vùng nội dung: padding 0 để khối tiêu đề (breadcrumb+title+tab) chạy FULL-BLEED như top nav.
       Gutter 16px + gap đáy do panel bảng tự lo (margin 16px). */
    .lp-desktop ::ng-deep .shell-content { padding: 0; display: flex; flex-direction: column; min-height: 0; }
    /* Workspace là flex-item lấp đầy shell-content; list-page bên trong nó cũng lấp đầy chiều cao. */
    .lp-desktop ::ng-deep .shell-content hrm-data-workspace { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
    .lp-desktop ::ng-deep .shell-content hrm-data-workspace > hrm-list-page { flex: 1 1 auto; min-height: 0; }

    /* ── Thẻ view "Thẻ": nhận diện người + ĐỦ field/action như 1 dòng bảng ── */
    .ec { display: flex; flex-direction: column; gap: var(--space-2-5); }
    .ec-top { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-2); }
    .ec-meta { display: flex; flex-direction: column; gap: var(--space-1); }
    /* 1 dòng meta: icon xám + giá trị, cắt gọn 1 dòng. */
    .mrow { display: flex; align-items: center; gap: var(--space-1-5); min-width: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .mrow tabler-icon { flex: none; color: var(--text-soft); }
    .mrow span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .kc-meta { display: flex; flex-direction: column; gap: var(--space-0-5); }
    .ec-foot {
      display: flex; align-items: center; justify-content: space-between; gap: var(--space-2);
      padding-top: var(--space-2); border-top: 1px solid var(--border-soft);
    }

    /* ── Thẻ Kanban: GỌN hơn (cột hẹp, quét nhanh) ── */
    .kc { display: flex; flex-direction: column; gap: 8px; }
    .kc-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 6px; }
    .kc-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
    .kc-date { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; }

    /* ── Ô nhãn trái Gantt ── */
    .gl { display: flex; align-items: center; gap: 8px; min-width: 0; }

    /* Bỏ padding của surface (drawer/modal/master) KHI chứa form → footer ghim SÁT đáy (không hở gap);
       form tự lo padding đều. Gated :has(.ef) → không đụng nội dung chi tiết hay drawer khác. */
    ::ng-deep .ant-drawer-body:has(.ef),
    ::ng-deep .ant-modal-body:has(.ef),
    ::ng-deep .dp-mbody:has(.ef) { padding: 0 !important; }

    /* Chi tiết: BỎ padding-top của surface → action bar sticky ghim FLUSH sát header (không hở
       khe padding). Bù lại bằng padding-top của chính .pk (trong sg-emp-detail) → nhịp trên vẫn đều. */
    ::ng-deep .ant-drawer-body:has(sg-emp-detail),
    ::ng-deep .ant-modal-body:has(sg-emp-detail),
    ::ng-deep .dp-mbody:has(sg-emp-detail) { padding-top: 0 !important; }

    /* Form Thêm/Sửa nhân viên (nội dung peek) — chia section, body cuộn, footer ghim đáy. */
    .ef { display: flex; flex-direction: column; min-height: 100%; }
    .ef-body { flex: 1 1 auto; display: flex; flex-direction: column; gap: 24px; padding: 20px 20px 12px; }
    .ef-sec { display: flex; flex-direction: column; gap: 12px; }
    .ef-sec-h { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: var(--fs-13); font-weight: 700; color: var(--text-strong); padding-bottom: 8px; border-bottom: 1px solid var(--border-soft); }
    .ef-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 16px; }
    .ef-field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
    .ef-field--full { grid-column: 1 / -1; }
    .ef-lbl { font-size: var(--fs-13); font-weight: 500; color: var(--text-body); }
    .ef-req { color: var(--error-base); }

    /* Avatar upload — canh GIỮA phía trên, các field xếp bên dưới. */
    .ef-id { display: flex; flex-direction: column; align-items: center; gap: 16px; }
    .ef-id-fields { width: 100%; min-width: 0; }
    .ef-ava { position: relative; flex: none; width: 84px; height: 84px; border-radius: 50%; cursor: pointer; }
    .ef-ava-img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; display: block; }
    .ef-ava-ph { display: grid; place-items: center; width: 100%; height: 100%; border-radius: 50%; background: var(--bg-surface-subtle); border: 1px dashed var(--border-strong, var(--border-sub)); color: var(--text-soft); }
    .ef-ava-badge { position: absolute; right: -2px; bottom: -2px; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; background: var(--primary-base); color: var(--text-on-primary); border: 2px solid var(--bg-surface); }
    .ef-ava-in { position: absolute; inset: 0; opacity: 0; cursor: pointer; }

    /* Kinh nghiệm làm việc */
    .ef-add { display: inline-flex; align-items: center; gap: 4px; padding: 4px 8px; border: 1px solid var(--border-sub); border-radius: var(--radius-md); background: var(--bg-surface); color: var(--primary-base); font: inherit; font-size: var(--fs-12); font-weight: 600; cursor: pointer; }
    .ef-add:hover { border-color: var(--primary-base); background: var(--primary-bg-subtle); }
    .ef-exp { position: relative; padding: 12px; border: 1px solid var(--border-soft); border-radius: var(--radius-lg); background: var(--bg-surface-subtle); }
    .ef-exp + .ef-exp { margin-top: 10px; }
    .ef-exp-del { position: absolute; top: 8px; right: 8px; display: grid; place-items: center; width: 26px; height: 26px; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--text-soft); }
    .ef-exp-del:hover { background: var(--bg-surface); color: var(--error-base); }

    /* Footer ghim đáy surface (sticky) — SÁT đáy, padding đều phải/dưới (20px). */
    /* Footer đặt trong slot [footer] của peek (.dp-mfoot đã lo padding 10/16 + border-top) → chỉ căn nút. */
    .ef-foot { display: flex; justify-content: flex-end; gap: 10px; }

    /* Footer modal (mode center): cụm hành động ghim chân — quy trình trái, Duyệt/Sửa phải. */
    .pkf { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; flex: 1 1 auto; width: 100%; }
    .pkf-sep { flex: 1 1 auto; }
    /* (CSS chi tiết bản ghi nằm trong component sg-emp-detail — dùng chung mọi surface.) */
    /* Ẩn thanh chuyển chế độ nội bộ của hrm-data-view (bộ chuyển đã đưa lên tầng tab ngoài panel). */
    .lp-desktop ::ng-deep hrm-data-view .dv-bar { display: none; }
    /* Lưới dữ liệu ĐƠN: mỗi ô đúng 1 dòng — hẹp thì cắt/cuộn ngang, KHÔNG rớt 2 dòng. */
    .lp-desktop ::ng-deep .ant-table-tbody > tr > td,
    .lp-desktop ::ng-deep .ant-table-thead > tr > th { white-space: nowrap; }

    /* Nút Bộ lọc (slot wsFilterPanel) khi có điều kiện bật — viền primary + badge đếm.
       ⚠ list-page (host component này) ENCAPSULATION EMULATED → ::ng-deep mới xuyên vào .ant-btn
       (nội dung project vào workspace vẫn giữ style-context của component khai báo = list-page). */
    .tbx-on ::ng-deep .ant-btn { border-color: var(--primary-base) !important; color: var(--primary-base) !important; }
    .tbx-badge { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px; margin-left: 2px; border-radius: var(--radius-full); background: var(--primary-base); color: var(--text-on-primary); font-size: var(--fs-11); font-weight: 600; line-height: 1; }

    /* Panel Bộ lọc trong popover. */
    .flt { display: flex; flex-direction: column; gap: 14px; min-width: 220px; }
    .flt-grp { display: flex; flex-direction: column; gap: 8px; }
    .flt-h { font-size: var(--fs-12); font-weight: 600; text-transform: uppercase; letter-spacing: .04em; color: var(--text-sub); }
    .flt-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding-top: 10px; border-top: 1px solid var(--border-soft); }
    .flt-res { font-size: var(--fs-12); color: var(--text-soft); }
  `],
})
export class SgDocListPage {
  private readonly t = inject(TranslateService);
  private readonly lang = signal(this.t.currentLang);
  /** true khi mở qua route /preview/list-page (tab mới) → render full viewport, không có sg-doc. */
  protected readonly preview = inject(ActivatedRoute).snapshot.data['preview'] === true;
  constructor() {
    this.t.onLangChange.subscribe((e) => this.lang.set(e.lang));
    // Cấu hình cột (ẩn/hiện, ghim, cột tính toán…) do <hrm-data-workspace> quản lý nội bộ và
    // ĐỒNG BỘ hiddenKeys/columnGroups ra ngoài qua two-way — không còn effect mcols→hiddenKeys ở đây.
  }

  protected readonly plus = IconPlus;
  protected readonly camera = IconCamera;
  protected readonly filter = IconFilter;
  protected readonly filterOff = IconFilterOff;
  protected readonly download = IconDownload;
  protected readonly check = IconCheck;
  protected readonly edit = IconEdit;
  protected readonly mailIcon = IconMail;
  protected readonly deptIcon = IconBuilding;
  protected readonly mgrIcon = IconUserCog;
  protected readonly clockIcon = IconClock;
  protected readonly trash = IconTrash;

  // ── State cấu hình bảng — two-way vào <hrm-data-workspace> (workspace forward xuống data-view/grid) ──
  /** Sort đa cấp. */
  protected readonly sortLevels = signal<HrmGridSort[]>([]);
  /** Khoá các cột đang ẩn — workspace ghi ra khi ẩn/hiện cột trong Column Manager. */
  protected readonly hiddenKeys = signal<string[]>([]);
  /** Các cấp NHÓM DỮ LIỆU (chiều dọc) + cờ mở panel kéo-thả nhóm. */
  protected readonly rowGroups = signal<HrmRowGroupLevel[]>([]);
  protected readonly showGroups = signal(false);
  /** Form Builder no-code (overlay full-screen) — mở từ ⋮ "Cấu hình biểu mẫu" (formConfigClick). */
  protected readonly fbOpen = signal(false);
  /** Các nhóm cột (Column Manager tổ chức header theo chiều ngang) — two-way [(columnGroups)]. */
  protected readonly mgroups = signal<HrmColumnGroup[]>([]);

  /** Định nghĩa cột nguồn truyền vào [columns] của workspace (width giữ nguyên bề rộng như bản cũ). */
  protected readonly mcols = signal<HrmColumnDef[]>([
    { key: 'name', title: 'Nhân viên', type: 'user', visible: true, hideable: true, pin: 'none', width: '240px' },
    { key: 'role', title: 'Chức vụ', type: 'text', visible: true, width: '200px' },
    { key: 'status', title: 'Trạng thái', type: 'status', visible: true, width: '140px' },
    { key: 'act', title: 'Hành động', type: 'text', align: 'right', pin: 'right', visible: true, hideable: false, width: '96px' },
  ]);

  /** Nhãn group-header khi nhóm dữ liệu — giá trị thô của cột là mã (role = i18n key,
   *  status = active/absent) nên dịch sang nhãn người đọc; cột khác (dept…) giữ nguyên. */
  protected readonly groupLabel = (key: string, value: unknown): string => {
    const v = String(value ?? '');
    if (!v) return '—';
    if (key === 'role') return this.t.instant(v);
    if (key === 'status') return v === 'active' ? 'Đang làm' : v === 'absent' ? 'Vắng' : v;
    return v;
  };

  // ── Bộ lọc: search + checkbox nhóm; signal-backed để filteredPeople reactive ──
  private readonly _f = signal({ active: false, absent: false, todo: false, doing: false, done: false });
  protected get fActive() { return this._f().active; } protected set fActive(v: boolean) { this._f.update((o) => ({ ...o, active: v })); }
  protected get fAbsent() { return this._f().absent; } protected set fAbsent(v: boolean) { this._f.update((o) => ({ ...o, absent: v })); }
  protected get fTodo() { return this._f().todo; } protected set fTodo(v: boolean) { this._f.update((o) => ({ ...o, todo: v })); }
  protected get fDoing() { return this._f().doing; } protected set fDoing(v: boolean) { this._f.update((o) => ({ ...o, doing: v })); }
  protected get fDone() { return this._f().done; } protected set fDone(v: boolean) { this._f.update((o) => ({ ...o, done: v })); }
  /** Số điều kiện lọc đang bật (hiện badge trên nút Bộ lọc). */
  protected readonly filterCount = computed(() => Object.values(this._f()).filter(Boolean).length);
  protected resetFilter(): void { this._f.set({ active: false, absent: false, todo: false, doing: false, done: false }); }

  /** Cấu hình 2 bộ lọc nhanh (pill) cho workspace — key khớp nhóm trong quickFilterValues. */
  protected readonly wsQuickFilters: HrmWorkspaceQuickFilter[] = [
    { key: 'status', label: 'Trạng thái', unit: 'trạng thái',
      options: [{ value: 'active', label: 'Đang làm' }, { value: 'absent', label: 'Vắng' }] },
    { key: 'stage', label: 'Giai đoạn', unit: 'giai đoạn',
      options: [
        { value: 'todo', label: STAGES['todo'].label }, { value: 'doing', label: STAGES['doing'].label }, { value: 'done', label: STAGES['done'].label },
      ] },
  ];
  /** quickFilterValues ↔ _f: 2 nhóm "status"(active/absent) & "stage"(todo/doing/done) map thẳng vào _f
   *  ⇒ 2 pill của workspace + popover Bộ lọc + badge + filteredPeople DÙNG CHUNG một nguồn state. */
  protected get qfValues(): Record<string, string[]> {
    const f = this._f();
    return {
      status: [...(f.active ? ['active'] : []), ...(f.absent ? ['absent'] : [])],
      stage: [...(f.todo ? ['todo'] : []), ...(f.doing ? ['doing'] : []), ...(f.done ? ['done'] : [])],
    };
  }
  protected set qfValues(v: Record<string, string[]>) {
    const st = v['status'] ?? []; const sg = v['stage'] ?? [];
    this._f.update((o) => ({
      ...o,
      active: st.includes('active'), absent: st.includes('absent'),
      todo: sg.includes('todo'), doing: sg.includes('doing'), done: sg.includes('done'),
    }));
  }
  /** Thao tác phụ menu ⋮ (Nhập/In) — demo no-op; bản thật gọi service tương ứng. */
  /** Cờ mở wizard Import dữ liệu (AI Data Import). */
  protected readonly importOpen = signal(false);
  /** Cờ mở drawer Export Center (Xuất dữ liệu). */
  protected readonly exportOpen = signal(false);
  protected moreAction(key: 'import' | 'print'): void {
    if (key === 'import') this.importOpen.set(true);
  }

  /** Khoá bản ghi đang chọn — dùng chung 4 chế độ xem (bảng/thẻ/kanban/gantt). */
  protected readonly selKeys = signal<unknown[]>([]);
  /** Hành động hàng loạt (demo): thao tác xong bỏ chọn. */
  protected bulkDone(): void { this.selKeys.set([]); }
  protected bulkDelete(): void { this.selKeys.set([]); }
  protected readonly maximize = IconArrowsMaximize;
  private readonly _kw = signal('');
  protected get kw() { return this._kw(); }
  protected set kw(v: string) { this._kw.set(v); }

  /** Danh sách sau khi áp search + bộ lọc — nguồn cho mọi chế độ xem. */
  protected readonly filteredPeople = computed<EmpRow[]>(() => {
    const kw = this._kw().trim().toLowerCase();
    const f = this._f();
    const stTon = f.active || f.absent;      // có lọc trạng thái?
    const sgOn = f.todo || f.doing || f.done;  // có lọc giai đoạn?
    return PEOPLE.filter((p) => {
      if (kw && !`${p['name']} ${p['email']}`.toLowerCase().includes(kw)) return false;
      if (stTon) {
        const ok = (f.active && p['status'] === 'active') || (f.absent && p['status'] === 'absent');
        if (!ok) return false;
      }
      if (sgOn) {
        const ok = (f.todo && p['stage'] === 'todo') || (f.doing && p['stage'] === 'doing') || (f.done && p['stage'] === 'done');
        if (!ok) return false;
      }
      return true;
    });
  });
  protected page = 1;
  protected mode: 'table' | 'card' | 'kanban' | 'gantt' = 'table';
  // Segmented đổi chế độ + nhãn mode do <hrm-data-workspace> tự render từ [modes] (VN mặc định).

  protected get rangeParams() {
    return { from: 1, to: this.people.length, total: 120, unit: this.t.instant('docs.listPage.countLabel') };
  }
  /** Action/dòng — KHÔNG có "Xem": bấm dòng/thẻ/thanh đã mở chi tiết rồi (tránh 2 lối vào trùng nhau).
   *  Dùng chung cho MỌI view (bảng · thẻ · kanban) → sửa 1 chỗ, đồng bộ hết. */
  protected get rowActions(): HrmActionItem[] {
    return [
      { key: 'edit', icon: IconEdit, label: this.t.instant('docs.enterpriseGrid.actEdit') },
      { key: 'delete', icon: IconTrash, label: this.t.instant('docs.enterpriseGrid.actDelete'), danger: true },
    ];
  }

  protected readonly when = ['docs.listPage.when1', 'docs.listPage.when2'];

  /** Dữ liệu demo — nguồn CHUNG (_people) với trang bản ghi toàn trang. */
  protected readonly people: EmpRow[] = PEOPLE;

  /** Pipeline ONBOARDING (STAGES import từ _people — nguồn chung với trang bản ghi). */
  protected readonly boardGroups = computed<HrmBoardGroup[]>(() => [
    { key: 'todo', label: STAGES['todo'].label, tone: 'neutral' },
    { key: 'doing', label: STAGES['doing'].label, tone: 'info' },
    { key: 'done', label: STAGES['done'].label, tone: 'success' },
  ]);
  /** Chi tiết bản ghi — dùng CHUNG cho mọi view (bảng/thẻ/kanban/gantt). */
  protected readonly selected = signal<Record<string, unknown> | null>(null);

  /** Trạng thái QUY TRÌNH (State Machine) theo id nhân viên — seed đủ 6 trạng thái để demo.
   *  Bấm hành động trong drawer sẽ cập nhật map này → cột bảng + chip đổi ngay (transition thật). */
  protected readonly wfStatus = signal<Record<number, HrmWorkflowStatus>>({
    1: 'pending', 2: 'approved', 3: 'rejected', 4: 'pendingCancel', 5: 'changeRequested', 6: 'cancelled',
  });
  /** Trạng thái quy trình của 1 dòng (mặc định 'pending' nếu chưa seed). */
  protected wfOf(r: Record<string, unknown>): HrmWorkflowStatus {
    return this.wfStatus()[Number(r['id'])] ?? 'pending';
  }
  /** Thực hiện 1 hành động → chuyển sang trạng thái đích theo State Machine (bỏ qua 'end'). */
  protected doWf(r: Record<string, unknown>, key: string): void {
    const id = Number(r['id']);
    const cur = this.wfOf(r);
    const act = HRM_WORKFLOW_ACTIONS[cur].find((a) => a.key === key);
    if (!act || act.to === 'end') return;
    this.wfStatus.update((m) => ({ ...m, [id]: act.to as HrmWorkflowStatus }));
  }

  /** Cụm hành động FOOTER chi tiết (gộp quy trình theo State Machine + hành động bản ghi cố định).
   *  Đưa vào hrm-action-bar → responsive tự thu nút dư vào ⋮. */
  protected footerActions(r: Record<string, unknown>): HrmActionBarItem[] {
    const wfActs: HrmActionBarItem[] = (HRM_WORKFLOW_ACTIONS[this.wfOf(r)] ?? []).map((a) => ({
      key: 'wf:' + a.key, label: a.vi, tone: a.tone, icon: a.icon,
    }));
    return [
      ...wfActs,
      { key: 'approveOfficial', label: 'Duyệt chính thức', tone: 'primary', icon: this.check },
      { key: 'editProfile', label: 'Sửa hồ sơ', tone: 'neutral', icon: this.edit },
    ];
  }
  /** Bấm 1 hành động ở footer: quy trình → chuyển trạng thái; bản ghi (duyệt/sửa) → demo no-op. */
  protected onFooterAction(r: Record<string, unknown>, key: string): void {
    if (key.startsWith('wf:')) this.doWf(r, key.slice(3));
  }
  protected readonly peekOpen = signal(false);
  protected readonly peekMode = signal<HrmPeekMode>('master');
  protected readonly peekLabels: Partial<Record<HrmPeekMode, string>> = {
    master: 'Bảng + chi tiết', side: 'Cạnh danh sách', center: 'Giữa màn hình',
    full: 'Toàn trang', tab: 'Tab mới',
  };
  /** Peek đang hiển thị: chi tiết bản ghi hay form Thêm/Sửa (cùng surface đa chế độ). */
  protected readonly peekKind = signal<'detail' | 'form'>('detail');
  protected readonly formMode = signal<'create' | 'edit'>('create');
  protected readonly idTypeOptions: HrmOption[] = [
    { value: 'cccd', label: 'CCCD' }, { value: 'cmnd', label: 'CMND' }, { value: 'passport', label: 'Hộ chiếu' },
  ];
  /** Form rỗng — dùng khi mở Thêm mới. */
  private emptyForm() {
    return {
      name: '', role: 'staff', status: 'active', stage: 'todo', avatar: '',
      email: '', phone: '', address: '',
      idType: 'cccd', idNo: '', idDate: '', idPlace: '',
      experiences: [{ company: '', position: '', period: '' }],
    };
  }
  /** Model form Thêm/Sửa (demo — nhiều section: cơ bản · liên hệ · giấy tờ · kinh nghiệm). */
  protected form = this.emptyForm();
  protected readonly roleOptions: HrmOption[] = [
    { value: 'staff', label: 'Nhân viên' }, { value: 'lead', label: 'Trưởng nhóm' }, { value: 'manager', label: 'Quản lý' },
  ];
  protected readonly statusOptions: HrmOption[] = [
    { value: 'active', label: 'Đang làm' }, { value: 'absent', label: 'Vắng' },
  ];
  protected get stageOptions(): HrmOption[] {
    return [
      { value: 'todo', label: STAGES['todo'].label }, { value: 'doing', label: STAGES['doing'].label }, { value: 'done', label: STAGES['done'].label },
    ];
  }
  /** Nội dung peek theo loại (chi tiết ↔ form). */
  protected readonly peekContent = computed<TemplateRef<unknown> | null>(() =>
    this.peekKind() === 'form' ? (this.empFormTpl() ?? null) : (this.empDetailTpl() ?? null));
  /** Route bản ghi độc lập — đích của mode Toàn trang (điều hướng) + Tab mới (window.open). */
  protected readonly peekRoute = computed(() => {
    if (this.peekKind() === 'form' && this.formMode() === 'create') return '/styleguide/hrm/template/list-page';
    const r = this.selected();
    return r ? `/styleguide/hrm/template/list-record?id=${r['id']}` : '';
  });
  protected readonly peekTitle = computed(() =>
    this.peekKind() === 'form'
      ? (this.formMode() === 'create' ? 'Thêm nhân viên' : 'Sửa nhân viên')
      : String(this.selected()?.['name'] ?? ''));
  /** Mở chi tiết bản ghi (click dòng/thẻ/thanh). */
  protected openEmp(r: Record<string, unknown>): void { this.selected.set(r); this.peekKind.set('detail'); this.peekOpen.set(true); }
  /** Mở form THÊM — cùng surface đa chế độ như màn chi tiết. */
  protected openCreate(): void {
    this.form = this.emptyForm();
    this.formMode.set('create'); this.peekKind.set('form'); this.peekOpen.set(true);
  }
  /** Mở form SỬA (action "Sửa" trên dòng) — nạp danh tính + liên hệ từ bản ghi. */
  protected openEdit(r: Record<string, unknown>): void {
    const f = this.emptyForm();
    f.name = String(r['name'] ?? ''); f.email = String(r['email'] ?? '');
    f.role = String(r['role'] ?? 'staff'); f.status = String(r['status'] ?? 'active'); f.stage = String(r['stage'] ?? 'todo');
    this.form = f;
    this.selected.set(r); this.formMode.set('edit'); this.peekKind.set('form'); this.peekOpen.set(true);
  }
  /** Lưu form (demo: đóng peek). */
  protected saveEmp(): void { this.peekOpen.set(false); }
  /** Action trên dòng: Sửa → mở form; Xoá → demo no-op. */
  protected onRowAction(key: string, r: Record<string, unknown>): void {
    if (key === 'edit') this.openEdit(r);
  }
  /** Đổi ảnh đại diện — đọc file thành data URL để xem trước (chỉ local, không upload). */
  protected onAvatar(e: Event): void {
    const file = (e.target as HTMLInputElement).files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => { this.form.avatar = String(reader.result ?? ''); };
    reader.readAsDataURL(file);
  }
  protected addExp(): void { this.form.experiences.push({ company: '', position: '', period: '' }); }
  protected removeExp(i: number): void { this.form.experiences.splice(i, 1); }

  /** Tông màu thanh Gantt theo giai đoạn onboarding (đồng bộ màu với cột Kanban). */
  protected readonly ganttTone = (r: Record<string, unknown>): string =>
    r['stage'] === 'done' ? 'success' : r['stage'] === 'doing' ? 'info' : 'neutral';
  protected stageLabel(r: EmpRow): string { return STAGES[String(r['stage'])]?.label ?? ''; }
  protected stageHue(r: EmpRow): string { return STAGES[String(r['stage'])]?.hue ?? 'gray'; }
  /** Hạn kết thúc thử việc — dd/MM cố định. */
  protected endText(r: EmpRow): string { return fmtDM(r['end']); }

  private readonly userCell = viewChild<TemplateRef<any>>('userCell');
  private readonly roleCell = viewChild<TemplateRef<any>>('roleCell');
  private readonly statusCell = viewChild<TemplateRef<any>>('statusCell');
  private readonly actionCell = viewChild<TemplateRef<any>>('actionCell');
  protected readonly computedCell = viewChild<TemplateRef<any>>('computedCell');
  private readonly empDetailTpl = viewChild<TemplateRef<unknown>>('empDetail');
  private readonly empFormTpl = viewChild<TemplateRef<unknown>>('empForm');

  /** Map key→template ô truyền vào [cellTemplates] của workspace (workspace tự suy gridCols theo cột). */
  protected readonly cellByKey = computed<Record<string, TemplateRef<any> | undefined>>(() => ({
    name: this.userCell(), role: this.roleCell(), status: this.statusCell(), act: this.actionCell(),
  }));
}
