/** Bước 3 — Kết quả import: header hoàn tất + 5 chỉ số + bảng kết quả theo tab +
 *  nút tải file + card lưu cấu hình import làm template cho lần sau. */
@Component({
  selector: 'sg-import-step-result',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    FormsModule, TablerIconComponent,
    HrmStatCard, HrmTabs, HrmTab, HrmStatusCell, HrmButton, HrmInput, HrmTag, HrmGrid,
  ],
  template: `
    <div class="imk-wrap">

      <!-- Header hoàn tất -->
      <div class="imk-head">
        <span class="imk-head-ic"><tabler-icon [icon]="icDone" [size]="26" /></span>
        <div>
          <h3 class="imk-title">Import hoàn tất</h3>
          <p class="imk-sub">{{ st.file()?.name ?? 'DanhSachNhanVien_2026.xlsx' }} · {{ st.BIG.rows }} dòng</p>
        </div>
      </div>

      <!-- 5 chỉ số kết quả -->
      <div class="imk-stats">
        <hrm-stat-card [value]="st.BIG.willImport" label="Thành công" [icon]="icDone" variant="pastel" tone="success" />
        <hrm-stat-card [value]="st.BIG.willUpdate" label="Đã cập nhật" [icon]="icRefresh" variant="pastel" tone="primary" />
        <hrm-stat-card [value]="st.BIG.willSkip" label="Đã bỏ qua" [icon]="icFilter" variant="pastel" tone="neutral" />
        <hrm-stat-card [value]="st.BIG.willReject" label="Không import" [icon]="icX" variant="pastel" tone="error" />
        <hrm-stat-card value="0" label="Lỗi hệ thống" [icon]="icAlert" variant="pastel" tone="neutral" />
      </div>

      <!-- Bảng kết quả theo tab — panel list-page: tab strip = toolbar band, grid flush -->
      <div class="imk-card imk-tablecard">
        <hrm-tabs [(selectedIndex)]="st.resultTab">
          <hrm-tab title="Đã import">
            <hrm-grid [columns]="cols()" [data]="$any(rowsImported)" rowKey="line"
              [showPagination]="false" [reorderable]="false" [customizable]="false" size="small" minWidth="720px" />
          </hrm-tab>
          <hrm-tab title="Đã cập nhật">
            <hrm-grid [columns]="cols()" [data]="$any(rowsUpdated)" rowKey="line"
              [showPagination]="false" [reorderable]="false" [customizable]="false" size="small" minWidth="720px" />
          </hrm-tab>
          <hrm-tab title="Bỏ qua">
            <hrm-grid [columns]="cols()" [data]="$any(rowsSkipped)" rowKey="line"
              [showPagination]="false" [reorderable]="false" [customizable]="false" size="small" minWidth="720px" />
          </hrm-tab>
          <hrm-tab title="Không hợp lệ">
            <hrm-grid [columns]="cols()" [data]="$any(rowsInvalid)" rowKey="line"
              [showPagination]="false" [reorderable]="false" [customizable]="false" size="small" minWidth="720px" />
          </hrm-tab>
        </hrm-tabs>
      </div>

      <!-- Cell templates -->
      <ng-template #nameCell let-r><span class="imk-name">{{ r.name }}</span></ng-template>
      <ng-template #statusCell let-r>
        <hrm-status-cell variant="badge" [status]="$any(r).tone" [label]="$any(r).label" />
      </ng-template>

      <!-- Tải file kết quả -->
      <div class="imk-dl">
        <hrm-button variant="default"><tabler-icon [icon]="icDownload" [size]="16" /> Tải file kết quả</hrm-button>
        <hrm-button variant="default"><tabler-icon [icon]="icDownload" [size]="16" /> Tải báo cáo lỗi</hrm-button>
        <hrm-button variant="default"><tabler-icon [icon]="icDownload" [size]="16" /> Tải file đã mapping</hrm-button>
        <hrm-button variant="default"><tabler-icon [icon]="icDownload" [size]="16" /> Tải audit log</hrm-button>
      </div>

      <!-- Lưu cấu hình import làm template -->
      <div class="imk-card imk-save">
        <div class="imk-save-head">
          <h4 class="imk-save-title">Lưu cấu hình import</h4>
          <p class="imk-save-desc">Lưu toàn bộ thiết lập của lần import này làm template — lần sau chỉ cần upload file.</p>
        </div>
        <label class="imk-save-name">
          <span>Tên cấu hình</span>
          <hrm-input [ngModel]="tplName()" (ngModelChange)="tplName.set($event)" placeholder="Nhập tên cấu hình..." />
        </label>
        <ul class="imk-save-list">
          @for (it of savedItems; track it.k) {
            <li>
              <span class="imk-save-check"><tabler-icon [icon]="icCheck" [size]="15" /></span>
              <span class="imk-save-k">{{ it.k }}</span>
              <span class="imk-save-d">— {{ it.d }}</span>
            </li>
          }
        </ul>
        <div class="imk-save-foot">
          @if (!tplSaved()) {
            <hrm-button variant="primary" (click)="tplSaved.set(true)">
              <tabler-icon [icon]="icSave" [size]="16" /> Lưu template
            </hrm-button>
          } @else {
            <hrm-tag color="success"><tabler-icon [icon]="icCheck" [size]="13" /> Đã lưu template</hrm-tag>
          }
        </div>
      </div>

    </div>
  `,
  styles: [`
:host { display: block; padding: var(--space-6); max-width: 960px; margin-inline: auto; }
.imk-wrap { display: flex; flex-direction: column; gap: var(--space-6); }

/* — Header hoàn tất — */
.imk-head { display: flex; align-items: center; gap: var(--space-3); }
.imk-head-ic {
  flex: none; width: 44px; height: 44px; border-radius: var(--radius-full);
  display: grid; place-items: center;
  background: color-mix(in srgb, var(--success-base) 15%, var(--bg-surface));
  color: var(--success-base);
}
.imk-title { margin: 0; font-size: var(--fs-18); font-weight: var(--font-semibold); color: var(--text-strong); }
.imk-sub { margin: var(--space-1) 0 0; font-size: var(--fs-13); color: var(--text-sub); font-variant-numeric: tabular-nums; }

/* — 5 stat card — */
.imk-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: var(--space-3); }

/* — Card chung — */
.imk-card {
  border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
  background: var(--bg-surface); padding: var(--space-4);
}
/* Panel bảng kết quả kiểu list-page: tab strip = toolbar band (đã có border-bottom của nz-tabs), grid flush */
.imk-tablecard { padding: 0; overflow: hidden; }
.imk-tablecard ::ng-deep .ant-tabs-nav { margin: 0; padding: 0 var(--space-3); }
.imk-tablecard ::ng-deep .ant-table { border: 0; border-radius: 0; background: transparent; }

.imk-name { color: var(--text-strong); font-weight: var(--font-medium); }

/* — Hàng nút download — */
.imk-dl { display: flex; flex-wrap: wrap; gap: var(--space-2); }

/* — Card lưu cấu hình — */
.imk-save { display: flex; flex-direction: column; gap: var(--space-4); }
.imk-save-title { margin: 0; font-size: var(--fs-15); font-weight: var(--font-semibold); color: var(--text-strong); }
.imk-save-desc { margin: var(--space-1) 0 0; font-size: var(--fs-13); color: var(--text-sub); }
.imk-save-name { display: flex; flex-direction: column; gap: var(--space-1); max-width: 420px; }
.imk-save-name > span { font-size: var(--fs-13); color: var(--text-sub); }
.imk-save-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--space-2); }
.imk-save-list li { display: flex; align-items: center; gap: var(--space-2); font-size: var(--fs-13); }
.imk-save-check { flex: none; display: inline-flex; color: var(--success-base); }
.imk-save-k { color: var(--text-strong); font-weight: var(--font-medium); white-space: nowrap; }
.imk-save-d { color: var(--text-sub); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.imk-save-foot { display: flex; align-items: center; }
  `],
})
export class SgImportStepResult {
  protected readonly st = inject(ImportStore);

  // — icon (Tabler object mode) —
  protected readonly icDone = IconCircleCheck;
  protected readonly icRefresh = IconRefresh;
  protected readonly icX = IconX;
  protected readonly icAlert = IconAlertTriangle;
  protected readonly icFilter = IconFilter;
  protected readonly icDownload = IconDownload;
  protected readonly icCheck = IconCheck;
  protected readonly icSave = IconDeviceFloppy;

  // — dữ liệu bảng kết quả mock (hằng số, không random) —
  protected readonly rowsImported = ROWS_IMPORTED.map((r) => ({ ...r, tone: 'success', label: 'Đã import' }));
  protected readonly rowsUpdated = ROWS_UPDATED.map((r) => ({ ...r, tone: 'info', label: 'Đã cập nhật' }));
  protected readonly rowsSkipped = ROWS_SKIPPED.map((r) => ({ ...r, tone: 'neutral', label: 'Bỏ qua' }));
  protected readonly rowsInvalid = ROWS_INVALID.map((r) => ({ ...r, tone: 'error', label: 'Không hợp lệ' }));

  // ── Cột + cell template hrm-grid ──
  private readonly nameCell = viewChild<TemplateRef<any>>('nameCell');
  private readonly statusCell = viewChild<TemplateRef<any>>('statusCell');
  protected readonly cols = computed<HrmGridColumn[]>(() => [
    { key: 'line', title: 'Dòng gốc', width: '90px', align: 'right' },
    { key: 'name', title: 'Họ tên', width: '150px', cell: this.nameCell() },
    { key: 'email', title: 'Email', width: '200px' },
    { key: 'dept', title: 'Phòng ban', width: '170px' },
    { key: 'status', title: 'Kết quả', width: '150px', cell: this.statusCell() },
    { key: 'time', title: 'Thời gian', width: '110px', align: 'right' },
  ]);

  // — card lưu cấu hình import (state cục bộ) —
  protected readonly tplName = signal('Danh sách nhân viên — SAP');
  protected readonly tplSaved = signal(false);
  protected readonly savedItems: { k: string; d: string }[] = [
    { k: 'Mapping', d: '24 trường nhận diện tự động + 1 map thủ công' },
    { k: 'AI transformation', d: 'chuẩn hóa phòng ban, định dạng SĐT và ngày' },
    { k: 'Validation rules', d: 'email, mã nhân viên, đối chiếu master data' },
    { k: 'Duplicate rules', d: 'gộp theo mã nhân viên / email' },
    { k: 'Import mode', d: 'Thêm mới + cập nhật' },
  ];
}
