import { ChangeDetectionStrategy, Component, computed, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  IconCircleCheck, IconDatabase, IconFilter, IconRefresh, IconSparkles, IconX,
  TablerIconComponent,
} from '@tabler/icons-angular';
import { HrmAlert, HrmDescItem, HrmDescriptions, HrmOption, HrmProgress, HrmRadioGroup } from 'hrm-ui';
import { ImportStore } from './import.store';

/** Bước 2 — Xác nhận & import: màn xác nhận (tóm tắt + strategy + nguyên tắc AI)
 *  và màn đang import (progress + đã xử lý + 3 stat + ghi chú chạy nền).
 *  Nút điều hướng/Import nằm ở footer wizard — step KHÔNG render nút. */
@Component({
  selector: 'sg-import-step-confirm',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [FormsModule, TablerIconComponent, HrmAlert, HrmDescriptions, HrmProgress, HrmRadioGroup],
  template: `
    @if (st.importPhase() === 'idle') {
      <div class="imc-wrap">
        <div class="imc-head">
          <div>
            <h3 class="imc-title">Xác nhận dữ liệu</h3>
            <div class="imc-sub">{{ st.BIG.rows }} dòng</div>
          </div>
          <div class="imc-quality">
            <tabler-icon [icon]="icAi" [size]="16" />
            Data quality <strong>{{ st.BIG.doneQuality }}</strong>
          </div>
        </div>

        <!-- Đối chiếu dữ liệu hiện có + Import mode — CHUYỂN từ bước Kiểm tra & sửa về đây:
             quyết định chiến lược import thuộc ngữ cảnh Xác nhận. -->
        <div class="imc-card">
          <div class="imc-card-title"><tabler-icon [icon]="icDb" [size]="16" /> Đối chiếu dữ liệu hiện có</div>
          <div class="imc-recon">
            <div class="imc-recon-item">
              <span class="imc-recon-v" data-tone="success">{{ st.BIG.newEmp }}</span>
              <span class="imc-recon-l">Nhân viên mới</span>
            </div>
            <div class="imc-recon-item">
              <span class="imc-recon-v">{{ st.BIG.existed }}</span>
              <span class="imc-recon-l">Đã tồn tại</span>
            </div>
            <div class="imc-recon-item">
              <span class="imc-recon-v" data-tone="info">{{ st.BIG.changed }}</span>
              <span class="imc-recon-l">Có thay đổi</span>
            </div>
            <div class="imc-recon-item">
              <span class="imc-recon-v" data-tone="warn">{{ st.BIG.conflict }}</span>
              <span class="imc-recon-l">Xung đột</span>
            </div>
          </div>
          <div class="imc-mode">
            <span class="imc-mode-lbl">Import mode:</span>
            <hrm-radio-group [options]="importModeOptions" [(ngModel)]="importModeVal" />
          </div>
        </div>

        <div class="imc-summary">
          @for (r of sumRows; track r.label) {
            <div [class]="'imc-sum-row t-' + r.tone">
              <span class="imc-disc"><tabler-icon [icon]="r.icon" [size]="16" /></span>
              <span class="imc-num">{{ r.num }}</span>
              <span class="imc-lbl">{{ r.label }}</span>
            </div>
          }
        </div>

        <hrm-descriptions title="Import strategy" [items]="strategy" [column]="1"
          layout="horizontal" size="small" />

        <hrm-alert
          type="info"
          message="AI không tự thay đổi dữ liệu quan trọng — mọi thay đổi đã được bạn xem và duyệt ở bước Kiểm tra & sửa." />
      </div>
    } @else {
      <div class="imc-wrap imc-wrap--run">
        <h3 class="imc-title">Đang import dữ liệu</h3>

        <hrm-progress [percent]="st.importPct()" />

        <div class="imc-processed">Đã xử lý: <strong>{{ st.processed() }}</strong></div>

        <div class="imc-stats">
          <div class="imc-stat t-success">
            <span class="imc-disc"><tabler-icon [icon]="icOk" [size]="16" /></span>
            <div class="imc-stat-body">
              <div class="imc-stat-num">{{ okCount() }}</div>
              <div class="imc-lbl">Thành công</div>
            </div>
          </div>
          <div class="imc-stat t-warning">
            <span class="imc-disc"><tabler-icon class="imc-spin" [icon]="icUpdate" [size]="16" /></span>
            <div class="imc-stat-body">
              <div class="imc-stat-num">{{ pendingCount() }}</div>
              <div class="imc-lbl">Đang xử lý</div>
            </div>
          </div>
          <div class="imc-stat t-error">
            <span class="imc-disc"><tabler-icon [icon]="icErr" [size]="16" /></span>
            <div class="imc-stat-body">
              <div class="imc-stat-num">0</div>
              <div class="imc-lbl">Lỗi</div>
            </div>
          </div>
        </div>

        <p class="imc-note">Bạn có thể đóng cửa sổ. Hệ thống sẽ tiếp tục xử lý ở chế độ nền.</p>

        @if (st.importPhase() === 'background') {
          <hrm-alert type="info" message="Đang chạy nền — bạn có thể tiếp tục thao tác khác." />
        }
      </div>
    }
  `,
  styles: [`
    :host { display: block; padding: var(--space-6); max-width: 960px; margin-inline: auto; }

    .imc-wrap {
      display: flex; flex-direction: column; gap: var(--space-6);
      margin: 0 auto;
    }
    .imc-wrap--run { max-width: 680px; padding-top: var(--space-8); }

    /* — header — */
    .imc-head {
      display: flex; align-items: flex-start; justify-content: space-between;
      gap: var(--space-4);
    }
    .imc-title {
      margin: 0; color: var(--text-strong);
      font-size: var(--fs-18); font-weight: var(--font-semibold);
    }
    .imc-sub { margin-top: var(--space-1); color: var(--text-sub); font-size: var(--fs-13); }
    .imc-quality {
      display: inline-flex; align-items: center; gap: var(--space-2);
      padding: var(--space-1) var(--space-3);
      border-radius: var(--radius-full);
      background: var(--success-bg);
      color: var(--success-text);
      font-size: var(--fs-13);
    }
    .imc-quality strong { font-weight: var(--font-semibold); font-variant-numeric: tabular-nums; }

    /* — tone map (alias cục bộ từ token, pattern hrm-shift-cell) — */
    .t-success { --tn: var(--success-base); }
    .t-primary { --tn: var(--primary-base); }
    .t-warning { --tn: var(--warning-base); }
    .t-error   { --tn: var(--error-base); }
    .t-neutral { --tn: var(--text-soft); }

    .imc-disc {
      display: inline-flex; align-items: center; justify-content: center;
      width: 28px; height: 28px; flex: none;
      border-radius: var(--radius-full);
      background: color-mix(in srgb, var(--tn) 12%, transparent);
      color: var(--tn);
    }

    /* — 4 dòng tóm tắt — */
    .imc-summary {
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
      background: var(--bg-surface);
    }
    .imc-sum-row {
      display: flex; align-items: center; gap: var(--space-3);
      padding: var(--space-3) var(--space-4);
    }
    .imc-sum-row + .imc-sum-row { border-top: 1px solid var(--border-soft); }
    .imc-num {
      min-width: 96px; text-align: right;
      color: var(--text-strong);
      font-size: var(--fs-18); font-weight: var(--font-semibold);
      font-variant-numeric: tabular-nums;
    }
    .imc-lbl { color: var(--text-sub); font-size: var(--fs-13); }

    /* — card strategy — */
    .imc-card {
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
      background: var(--bg-surface); padding: var(--space-4);
    }
    .imc-card-title {
      display: flex; align-items: center; gap: var(--space-2);
      margin-bottom: var(--space-3);
      color: var(--text-strong);
      font-size: var(--fs-14); font-weight: var(--font-semibold);
    }

    /* — Đối chiếu dữ liệu hiện có (chuyển từ bước Kiểm tra & sửa) — */
    .imc-recon { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: var(--space-3); }
    .imc-recon-item {
      display: flex; flex-direction: column; gap: var(--space-0-5);
      border: 1px solid var(--border-soft); border-radius: var(--radius-md); padding: var(--space-3);
    }
    .imc-recon-v { font-size: var(--fs-20); font-weight: var(--font-semibold); color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .imc-recon-v[data-tone='success'] { color: var(--success-base); }
    .imc-recon-v[data-tone='info'] { color: var(--info-base); }
    .imc-recon-v[data-tone='warn'] { color: var(--warning-base); }
    .imc-recon-l { font-size: var(--fs-12); color: var(--text-sub); }
    .imc-mode { display: flex; align-items: center; gap: var(--space-3); flex-wrap: wrap; margin-top: var(--space-3); }
    .imc-mode-lbl { font-size: var(--fs-13); font-weight: var(--font-medium); color: var(--text-body); flex: none; }

    /* — màn đang import — */
    .imc-processed { color: var(--text-body); font-size: var(--fs-13); }
    .imc-processed strong {
      color: var(--text-strong); font-weight: var(--font-semibold);
      font-variant-numeric: tabular-nums;
    }
    .imc-stats {
      display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: var(--space-3);
    }
    .imc-stat {
      display: flex; align-items: center; gap: var(--space-3);
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
      background: var(--bg-surface); padding: var(--space-4);
    }
    .imc-stat-body { min-width: 0; }
    .imc-stat-num {
      color: var(--text-strong);
      font-size: var(--fs-20); font-weight: var(--font-semibold);
      font-variant-numeric: tabular-nums;
    }
    .imc-note { margin: 0; color: var(--text-sub); font-size: var(--fs-13); }

    .imc-spin { animation: imc-spin 1s linear infinite; }
    @keyframes imc-spin { to { transform: rotate(360deg); } }
  `],
})
export class SgImportStepConfirm {
  protected readonly st = inject(ImportStore);

  protected readonly icAi = IconSparkles;
  protected readonly icOk = IconCircleCheck;
  protected readonly icUpdate = IconRefresh;
  protected readonly icErr = IconX;
  protected readonly icDb = IconDatabase;

  /** Import mode (chuyển từ bước Kiểm tra & sửa) — ghi thẳng vào store. */
  protected readonly importModeOptions: HrmOption[] = [
    { value: 'add', label: 'Chỉ thêm mới' },
    { value: 'update', label: 'Chỉ cập nhật' },
    { value: 'both', label: 'Thêm mới + cập nhật' },
  ];
  protected get importModeVal(): unknown { return this.st.importMode(); }
  protected set importModeVal(v: unknown) {
    this.st.importMode.set(String(v) as 'add' | 'update' | 'both');
  }

  /** 4 dòng tóm tắt màn xác nhận (icon + số + label, tone semantic). */
  protected readonly sumRows = [
    { icon: IconCircleCheck, tone: 'success', num: this.st.BIG.willImport, label: 'sẽ được import' },
    { icon: IconRefresh, tone: 'primary', num: this.st.BIG.willUpdate, label: 'sẽ được cập nhật' },
    { icon: IconFilter, tone: 'neutral', num: this.st.BIG.willSkip, label: 'sẽ được bỏ qua' },
    { icon: IconX, tone: 'error', num: this.st.BIG.willReject, label: 'không được import' },
  ];

  /** Bảng nhỏ Import strategy (§7 contract — 28,010 là hằng riêng của bảng này). */
  protected readonly strategy: HrmDescItem[] = [
    { label: 'Thêm mới', value: this.st.BIG.newEmp },
    { label: 'Cập nhật', value: '28,010' },
    { label: 'Bỏ qua', value: this.st.BIG.willSkip },
    { label: 'Không hợp lệ', value: this.st.BIG.willReject },
  ];

  /** Tổng dòng sẽ import — parse từ hằng hiển thị của store ('178,240'). */
  private readonly total = Number(this.st.BIG.willImport.replace(/,/g, ''));

  /** Số dòng đã import thành công, suy từ % tiến độ. */
  protected readonly okCount = computed(() =>
    Math.floor((this.total * this.st.importPct()) / 100).toLocaleString('en-US'),
  );

  /** Số dòng còn đang xử lý = tổng − thành công. */
  protected readonly pendingCount = computed(() =>
    (this.total - Math.floor((this.total * this.st.importPct()) / 100)).toLocaleString('en-US'),
  );
}
