import { ChangeDetectionStrategy, Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  TablerIconComponent,
  IconSearch, IconSparkles, IconWand, IconAlertTriangle, IconCircleCheck,
  IconPencil, IconCheck, IconX, IconChevronDown,
} from '@tabler/icons-angular';
import {
  HrmStatCard, HrmGrid, HrmGridColumn, HrmInput, HrmSelect,
  HrmStatusCell, HrmAlert, HrmTag, HrmButton, HrmOption, HrmTableToolbar,
} from 'hrm-ui';
import { ImportStore, ImpRow } from './import.store';

/** Phòng ban hợp lệ (đồng bộ danh sách DEPTS trong import.store — dùng cho option select inline/bulk). */
const VALID_DEPTS = ['Phân xưởng Lắp ráp 1', 'Phòng Kinh doanh', 'Phòng Nhân sự', 'Phòng Kỹ thuật', 'Sales Department'];
const DEPT_OPTIONS: HrmOption[] = VALID_DEPTS.map((d) => ({ value: d, label: d }));

/** Bước 1 — Kiểm tra & sửa dữ liệu (tinh gọn): stat + dải "✨ AI đề xuất" collapsible (chỉ mode AI Scan)
 *  + chip đếm-kiêm-lọc + BẢNG sửa inline là trung tâm. Đối chiếu/Import-mode đã chuyển sang bước Xác nhận.
 *  Nguyên tắc AI: Detect → Suggest → Preview → User approve — không silent modification. */
@Component({
  selector: 'sg-import-step-review',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    FormsModule, TablerIconComponent,
    HrmStatCard, HrmGrid, HrmInput, HrmSelect,
    HrmStatusCell, HrmAlert, HrmTag, HrmButton, HrmTableToolbar,
  ],
  template: `
    <div class="imr">
      <!-- ── Header khối ── -->
      <header class="imr-head">
        <h3 class="imr-title">Kiểm tra &amp; sửa dữ liệu</h3>
        <p class="imr-sub">{{ st.BIG.rows }} dòng · AI đã hoàn tất phân tích</p>
      </header>

      <!-- ── 6.1 Summary 4 stat-card ── -->
      <div class="imr-stats">
        <hrm-stat-card variant="pastel" orientation="compact" tone="success"
          [icon]="icCircleCheck" [value]="st.BIG.valid" label="Hợp lệ" />
        <hrm-stat-card variant="pastel" orientation="compact" tone="warning"
          [icon]="icAlert" [value]="st.BIG.warn" label="Cần sửa" />
        <hrm-stat-card variant="pastel" orientation="compact" tone="error"
          [icon]="icX" [value]="st.BIG.error" label="Lỗi cần xử lý" />
        <hrm-stat-card variant="pastel" orientation="compact" tone="primary"
          [icon]="icSparkles" [value]="st.BIG.quality" label="Data Quality" />
      </div>

      <!-- ── Dải ✨ AI đề xuất (collapsible — spartan accordion anatomy, style token hrm-ui) ──
           CHỈ hiện ở chế độ AI Scan. Import theo mẫu = validate quy tắc thuần, không đề xuất AI. -->
      @if (st.mode() === 'ai') {
        <section class="imr-ai" [class.imr-ai--open]="aiOpen()">
          <button type="button" class="imr-ai-trigger" (click)="aiOpen.set(!aiOpen())"
            [attr.aria-expanded]="aiOpen()">
            <tabler-icon [icon]="icSparkles" [size]="16" class="imr-hic imr-hic--ai" />
            <span class="imr-ai-title">AI đề xuất ({{ aiPending() }})</span>
            <span class="imr-ai-sum">
              @if (aiPending() > 0) { 4,050 dòng có thể sửa nhanh — chuẩn hóa · định dạng · trùng lặp }
              @else { Đã xử lý tất cả đề xuất }
            </span>
            <tabler-icon [icon]="icChevron" [size]="16" class="imr-ai-chev" />
          </button>
          @if (aiOpen()) {
            <div class="imr-ai-body">
              <!-- 1 · Chuẩn hóa phòng ban (Smart Fix) -->
              <div class="imr-ai-item">
                <tabler-icon [icon]="icSparkles" [size]="16" class="imr-hic imr-hic--ai" />
                <div class="imr-ai-txt">
                  <div class="imr-ai-h">Chuẩn hóa phòng ban</div>
                  <div class="imr-ai-d">Sale · sales · Sales Dept → <b>Sales Department</b> ·
                    <b class="imr-num">{{ st.BIG.smartFixCount }}</b> dòng sẽ được cập nhật</div>
                </div>
                @if (!st.smartFixApplied()) {
                  <div class="imr-actions">
                    <hrm-button variant="default" size="sm" (click)="noop()">Xem mẫu</hrm-button>
                    <hrm-button variant="primary" size="sm" (click)="st.applySmartFix()">Áp dụng {{ st.BIG.smartFixCount }} dòng</hrm-button>
                  </div>
                } @else {
                  <hrm-tag color="success" size="sm"><tabler-icon [icon]="icCheck" [size]="12" /> Đã áp dụng</hrm-tag>
                }
              </div>
              <!-- 2 · Tự động sửa định dạng (Auto Fix) -->
              <div class="imr-ai-item">
                <tabler-icon [icon]="icWand" [size]="16" class="imr-hic imr-hic--ai" />
                <div class="imr-ai-txt">
                  <div class="imr-ai-h">Tự động sửa định dạng</div>
                  <div class="imr-ai-d">Khoảng trắng · SĐT · email · ngày — VD "0901000001" → "0901 000 001" ·
                    <b class="imr-num">{{ st.BIG.autoFixCount }}</b> lỗi</div>
                </div>
                @if (!st.autoFixApplied()) {
                  <div class="imr-actions">
                    <hrm-button variant="default" size="sm" (click)="noop()">Xem thay đổi</hrm-button>
                    <hrm-button variant="primary" size="sm" (click)="st.applyAutoFix()">Áp dụng tất cả</hrm-button>
                  </div>
                } @else {
                  <hrm-tag color="success" size="sm"><tabler-icon [icon]="icCheck" [size]="12" /> Đã áp dụng</hrm-tag>
                }
              </div>
              <!-- 3 · Dữ liệu trùng — expand con: từng cặp hàng ngang gọn -->
              <div class="imr-ai-item imr-ai-item--col">
                <div class="imr-ai-row">
                  <tabler-icon [icon]="icAlert" [size]="16" class="imr-hic imr-hic--warn" />
                  <div class="imr-ai-txt">
                    <div class="imr-ai-h">Dữ liệu trùng</div>
                    <div class="imr-ai-d"><b class="imr-num">{{ st.BIG.dupCount }}</b> nhân viên có khả năng trùng
                      (khớp mã NV · email · SĐT · CCCD) · {{ dupPending() }} cặp cần quyết định</div>
                  </div>
                  <hrm-button variant="default" size="sm" (click)="dupOpen.set(!dupOpen())">
                    Xử lý từng cặp <tabler-icon [icon]="icChevron" [size]="14" [class.imr-rot]="dupOpen()" />
                  </hrm-button>
                </div>
                @if (dupOpen()) {
                  <div class="imr-dups">
                    @for (d of st.dups(); track d.id) {
                      <div class="imr-dup">
                        <span class="imr-dup-cell"><b>Dòng {{ d.a.row }}</b> {{ d.a.name }} · {{ d.a.email }}</span>
                        <span class="imr-dup-vs">↔</span>
                        <span class="imr-dup-cell"><b>Dòng {{ d.b.row }}</b> {{ d.b.name }} · {{ d.b.email }}</span>
                        <span class="imr-dup-match">{{ d.match }}%</span>
                        @if (d.resolved) {
                          <hrm-status-cell status="success" variant="badge" [dot]="true"
                            [label]="'Giữ dòng ' + (d.resolved === 'a' ? d.a.row : d.b.row)" />
                        } @else {
                          <div class="imr-actions">
                            <hrm-button variant="default" size="sm" (click)="st.resolveDup(d.id, 'a')">Giữ {{ d.a.row }}</hrm-button>
                            <hrm-button variant="default" size="sm" (click)="st.resolveDup(d.id, 'b')">Giữ {{ d.b.row }}</hrm-button>
                          </div>
                        }
                      </div>
                    }
                  </div>
                }
              </div>
            </div>
          }
        </section>
      } @else {
        <!-- Import theo mẫu: 1 dòng gợi ý — không chiếm không gian của bảng -->
        <hrm-alert type="info"
          message="Chế độ Import theo mẫu chỉ kiểm tra quy tắc. Bật ✨ AI Scan ở bước Thiết lập để nhận đề xuất sửa tự động." />
      }


      <!-- ── 6.7 + 6.8 + 6.9 Bảng dòng: filter bar + bulk bar + hrm-grid sửa inline ── -->
      <!-- Panel bảng theo ĐÚNG khung list-page chuẩn: wrapper .imr-toolbar (chỉ border-bottom, y hệt
           .lp-toolbar) bọc component DS <hrm-table-toolbar> — KHÔNG tự chế thanh toolbar. -->
      <section class="imr-card imr-tablecard">
        <div class="imr-toolbar">
          <hrm-table-toolbar>
            <hrm-input class="imr-search" [prefixIcon]="icSearch" [clearable]="true"
              placeholder="Tìm tên, email, mã nhân viên..." [(ngModel)]="searchVal" />
            <!-- Chip đếm-kiêm-lọc (toggle-group anatomy): 1 hàng THAY cả Error Center + tab lọc cũ.
                 Chip lỗi click = lọc bảng theo loại lỗi; chip Trùng mở mục xử lý trong dải AI. -->
            <div class="imr-chips" role="group" aria-label="Lọc dòng theo trạng thái">
              @for (c of chips(); track c.key) {
                <button type="button" class="imr-chip" [class.is-on]="st.filterTab() === c.key"
                  [attr.aria-pressed]="st.filterTab() === c.key" (click)="chipClick(c.key)">
                  @if (c.tone === 'ai') { <tabler-icon [icon]="icSparkles" [size]="13" /> }
                  @else { <span class="imr-chip-dot" [attr.data-tone]="c.tone"></span> }
                  {{ c.label }}
                  <span class="imr-chip-n">{{ c.count }}</span>
                </button>
              }
            </div>
          </hrm-table-toolbar>
        </div>
        <!-- 6.9 Bulk band: DÍNH giữa toolbar và bảng (band riêng, KHÔNG absolute → hết đè header) -->
        @if (st.selection().length > 0) {
          <div class="imr-bulk">
            <span class="imr-bulk-n">{{ st.selection().length }} dòng được chọn</span>
            <hrm-button variant="primary" size="sm" (click)="aiFixSelected()">
              <tabler-icon [icon]="icSparkles" [size]="14" /> AI sửa đề xuất
            </hrm-button>
            @if (!bulkOpen()) {
              <hrm-button variant="default" size="sm" (click)="bulkOpen.set(true)">
                <tabler-icon [icon]="icPencil" [size]="14" /> Sửa hàng loạt
              </hrm-button>
            } @else {
              <hrm-select class="imr-bulk-sel" size="sm" [options]="deptOptions" [allowClear]="false" [(ngModel)]="bulkDeptVal" />
              <hrm-button variant="primary" size="sm" (click)="applyBulk()">
                <tabler-icon [icon]="icCheck" [size]="14" /> Áp dụng
              </hrm-button>
            }
            <hrm-button variant="text" size="sm" (click)="st.clearSelection()">
              <tabler-icon [icon]="icX" [size]="14" /> Bỏ chọn
            </hrm-button>
          </div>
        }
        <div class="imr-tablewrap">
          <hrm-grid [columns]="cols()" [data]="$any(st.viewRows())" rowKey="id"
            [selectable]="true" [selectedKeys]="selKeys()" (selectedKeysChange)="onSel($event)"
            [showPagination]="false" [reorderable]="false" [customizable]="false"
            size="small" minWidth="960px" />
        </div>
      </section>
    </div>

    <!-- ── Cell templates của hrm-grid ── -->
    <!-- Email: có lỗi email (hoặc đang bấm Sửa) → input inline, gõ tới đâu re-validate tới đó. -->
    <ng-template #emailCell let-r>
      @if (hasEmailErr(r) || editId() === r.id) {
        <!-- focus giữ editId ⇒ input SỐNG khi lỗi vừa hết giữa lúc gõ (không bị destroy nửa chừng);
             blur mới trả về chế độ text. -->
        <input class="imr-edit" [class.imr-edit--err]="hasEmailErr(r)" [value]="r.email"
          (focus)="editId.set(r.id)" (blur)="editId.set(null)"
          (input)="onEmail(r, $event)" placeholder="ten@congty.vn" aria-label="Sửa email" />
      } @else {
        <span>{{ r.email }}</span>
      }
    </ng-template>
    <!-- Phòng ban: dept sai master data (hoặc đang Sửa) → hrm-select DEPTS inline. -->
    <ng-template #deptCell let-r>
      @if (hasDeptErr(r) || editId() === r.id) {
        <hrm-select class="imr-editsel" size="sm" [options]="deptOptions" [allowClear]="false"
          placeholder="Chọn phòng ban" [ngModel]="deptValid(r) ? r.dept : null"
          (ngModelChange)="onDept(r, $event)" />
      } @else {
        <span>{{ r.dept }}</span>
      }
    </ng-template>
    <ng-template #stateCell let-r>
      <hrm-status-cell variant="badge" [dot]="true"
        [status]="r.state === 'valid' ? 'success' : r.state === 'warn' ? 'warning' : 'error'"
        [label]="r.state === 'valid' ? 'Hợp lệ' : r.state === 'warn' ? 'Cảnh báo' : 'Lỗi'" />
    </ng-template>
    <ng-template #errCell let-r>
      <span class="imr-errtext">{{ r.errors?.length ? r.errors[0] : '—' }}</span>
    </ng-template>
    <ng-template #actCell let-r>
      <!-- Icon edit đặt cột ĐẦU (kế checkbox) — mở editor inline; luôn hiện để sửa lại được. -->
      <hrm-button variant="text" [iconOnly]="true" ariaLabel="Sửa dòng" (click)="edit(r)">
        <tabler-icon [icon]="icPencil" [size]="16" />
      </hrm-button>
    </ng-template>
  `,
  styles: [`
    :host { display: block; padding: var(--space-6); max-width: 960px; margin-inline: auto; }
    .imr { display: flex; flex-direction: column; gap: var(--space-6); }

    /* ── Header ── */
    .imr-title { margin: 0; font-size: var(--fs-18); font-weight: var(--font-semibold); color: var(--text-strong); }
    .imr-sub { margin: var(--space-1) 0 0; font-size: var(--fs-13); color: var(--text-sub); }

    /* ── Stat cards ── */
    .imr-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: var(--space-3); }

    /* ── Card chung ── */
    .imr-card {
      display: flex; flex-direction: column; gap: var(--space-3);
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
      background: var(--bg-surface); padding: var(--space-4);
    }
    .imr-hic { color: var(--icon-secondary); flex: none; }
    .imr-hic--ai { color: var(--primary-base); }
    .imr-hic--warn { color: var(--warning-base); }
    .imr-num { font-weight: var(--font-bold); color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .imr-actions { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }


    /* ── Dải ✨ AI đề xuất (collapsible — accordion anatomy, token DS) ── */
    .imr-ai { border: 1px solid var(--border-sub); border-left: 3px solid var(--primary-base);
      border-radius: var(--radius-lg); background: var(--bg-surface); }
    .imr-ai-trigger { display: flex; align-items: center; gap: var(--space-2); width: 100%;
      border: 0; background: transparent; cursor: pointer; text-align: start; font: inherit;
      padding: var(--space-3) var(--space-4); border-radius: var(--radius-lg); }
    .imr-ai-trigger:hover { background: var(--bg-surface-subtle); }
    .imr-ai-title { font-size: var(--fs-14); font-weight: var(--font-semibold); color: var(--text-strong); flex: none; }
    .imr-ai-sum { flex: 1 1 auto; min-width: 0; font-size: var(--fs-13); color: var(--text-sub);
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .imr-ai-chev { color: var(--icon-secondary); flex: none;
      transition: transform var(--duration-fast, .15s) ease; }
    .imr-ai--open .imr-ai-chev { transform: rotate(180deg); }
    .imr-ai-body { display: flex; flex-direction: column; border-top: 1px solid var(--border-soft); }
    .imr-ai-item { display: flex; align-items: center; gap: var(--space-3); padding: var(--space-3) var(--space-4); }
    .imr-ai-item + .imr-ai-item { border-top: 1px solid var(--border-soft); }
    .imr-ai-item--col { flex-direction: column; align-items: stretch; gap: var(--space-2); }
    .imr-ai-row { display: flex; align-items: center; gap: var(--space-3); }
    .imr-ai-txt { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: var(--space-0-5); }
    .imr-ai-h { font-size: var(--fs-13); font-weight: var(--font-semibold); color: var(--text-strong); }
    .imr-ai-d { font-size: var(--fs-13); color: var(--text-sub); }
    .imr-rot { transform: rotate(180deg); }

    /* ── Cặp trùng — hàng ngang gọn trong dải AI ── */
    .imr-dups { display: flex; flex-direction: column; gap: var(--space-2); }
    .imr-dup { display: flex; align-items: center; gap: var(--space-3); flex-wrap: wrap;
      border: 1px solid var(--border-soft); border-radius: var(--radius-md);
      padding: var(--space-2) var(--space-3); }
    .imr-dup-cell { font-size: var(--fs-13); color: var(--text-body); min-width: 0;
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .imr-dup-cell b { color: var(--text-strong); }
    .imr-dup-vs { flex: none; color: var(--text-soft); font-size: var(--fs-12); }
    .imr-dup-match { flex: none; font-size: var(--fs-12); font-weight: var(--font-semibold); color: var(--warning-text);
      font-variant-numeric: tabular-nums; }

    /* ── Chip đếm-kiêm-lọc (toggle-group anatomy, token DS) ── */
    .imr-chips { display: flex; align-items: center; gap: var(--space-1-5); flex-wrap: wrap; }
    .imr-chip { display: inline-flex; align-items: center; gap: var(--space-1-5);
      border: 1px solid var(--border-sub); border-radius: var(--radius-full);
      background: var(--bg-surface); padding: var(--space-1) var(--space-2-5);
      font: inherit; font-size: var(--fs-13); color: var(--text-body); cursor: pointer; }
    .imr-chip:hover { background: var(--bg-surface-subtle); }
    .imr-chip:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 1px; }
    .imr-chip.is-on { background: var(--primary-bg-subtle); border-color: var(--primary-border); color: var(--text-strong); }
    .imr-chip-dot { width: 6px; height: 6px; border-radius: var(--radius-full); background: var(--text-soft); flex: none; }
    .imr-chip-dot[data-tone='ok'] { background: var(--success-base); }
    .imr-chip-dot[data-tone='err'] { background: var(--error-base); }
    .imr-chip-dot[data-tone='warn'] { background: var(--warning-base); }
    .imr-chip-n { font-size: var(--fs-12); font-weight: var(--font-semibold); color: var(--text-sub);
      font-variant-numeric: tabular-nums; padding: 0 var(--space-1);
      border-radius: var(--radius-full); background: var(--bg-surface-subtle); }
    .imr-chip.is-on .imr-chip-n { background: var(--bg-surface); color: var(--text-strong); }

    /* ── 6.7 filter bar + 6.8 bảng ── */
    /* ── Panel bảng theo khung list-page chuẩn (.lp-panel/.lp-toolbar/.lp-body) —
       toolbar = component DS hrm-table-toolbar, wrapper chỉ kẻ divider; bảng flush mép. ── */
    .imr-tablecard { padding: 0; gap: 0; overflow: hidden; }
    .imr-toolbar { border-bottom: 1px solid var(--border-sub); }        /* = .lp-toolbar */
    .imr-tablewrap ::ng-deep .ant-table { border: 0; border-radius: 0; background: transparent; }  /* = .lp-body */
    .imr-search { width: 320px; max-width: 100%; }
    /* chips xuống hàng gọn trong slot giữa của toolbar khi hẹp */
    .imr-toolbar hrm-table-toolbar { flex-wrap: wrap; }
    .imr-tablewrap { position: relative; min-width: 0; }
    .imr-errtext { font-size: var(--fs-12); color: var(--text-sub); }
    /* Input sửa inline trong ô (theo contract .imr-edit — input event → fixRow re-validate). */
    .imr-edit {
      width: 100%; min-width: 140px; padding: var(--space-0-5) var(--space-2);
      font: inherit; font-size: var(--fs-13); color: var(--text-body);
      background: var(--bg-surface); border: 1px solid var(--border-input); border-radius: var(--radius-sm);
    }
    .imr-edit:focus { outline: none; border-color: var(--border-focus); }
    .imr-edit--err { border-color: var(--border-error); }
    .imr-editsel { display: block; width: 100%; min-width: 160px; }

    /* ── 6.9 bulk bar nổi trên bảng ── */
    /* Bulk band DÍNH: nằm giữa toolbar và bảng, nền primary tint + border-bottom — không đè header */
    .imr-bulk {
      display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap;
      padding: var(--space-2) var(--space-3);
      background: var(--primary-bg-subtle); border-bottom: 1px solid var(--primary-border);
    }
    .imr-bulk-n { font-size: var(--fs-13); font-weight: var(--font-semibold); color: var(--text-strong); white-space: nowrap; }
    .imr-bulk-sel { width: 220px; }
  `],
})
export class SgImportStepReview {
  protected readonly st = inject(ImportStore);

  // ── Icon (Tabler object mode) ──
  protected readonly icSearch = IconSearch;
  protected readonly icSparkles = IconSparkles;
  protected readonly icWand = IconWand;
  protected readonly icAlert = IconAlertTriangle;
  protected readonly icCircleCheck = IconCircleCheck;
  protected readonly icPencil = IconPencil;
  protected readonly icCheck = IconCheck;
  protected readonly icX = IconX;
  protected readonly icChevron = IconChevronDown;

  // ── Hằng hiển thị ──
  protected readonly deptOptions = DEPT_OPTIONS;

  // ── State cục bộ (UI-only) ──
  /** Dòng đang ép mở editor inline (bấm nút "Sửa"). */
  protected readonly editId = signal<number | null>(null);
  /** Dải "✨ AI đề xuất" đang mở rộng (mặc định THU GỌN — bảng là trung tâm). */
  protected readonly aiOpen = signal(false);
  /** Mục "Dữ liệu trùng" trong dải AI đang mở danh sách cặp. */
  protected readonly dupOpen = signal(false);
  /** Mở panel chọn phòng ban của "Sửa hàng loạt" trong bulk bar. */
  protected readonly bulkOpen = signal(false);
  private readonly bulkDept = signal('Sales Department');

  // ── ngModel bridge (getter/setter ↔ signal) ──
  protected get searchVal() { return this.st.search(); }
  protected set searchVal(v: string) { this.st.search.set(v ?? ''); }
  protected get bulkDeptVal(): unknown { return this.bulkDept(); }
  protected set bulkDeptVal(v: unknown) { this.bulkDept.set(String(v ?? 'Sales Department')); }

  // ── Grid: cột + cell template ──
  private readonly emailCell = viewChild<TemplateRef<any>>('emailCell');
  private readonly deptCell = viewChild<TemplateRef<any>>('deptCell');
  private readonly stateCell = viewChild<TemplateRef<any>>('stateCell');
  private readonly errCell = viewChild<TemplateRef<any>>('errCell');
  private readonly actCell = viewChild<TemplateRef<any>>('actCell');

  protected readonly cols = computed<HrmGridColumn[]>(() => [
    { key: 'act', title: '', width: '46px', align: 'center', cell: this.actCell() },
    { key: 'id', title: 'Dòng', width: '64px' },
    { key: 'name', title: 'Họ tên', width: '170px' },
    { key: 'email', title: 'Email', width: '230px', cell: this.emailCell() },
    { key: 'phone', title: 'Điện thoại', width: '130px' },
    { key: 'dept', title: 'Phòng ban', width: '200px', cell: this.deptCell() },
    { key: 'state', title: 'Trạng thái dòng', width: '130px', cell: this.stateCell() },
    { key: 'errs', title: 'Lỗi', width: '210px', cell: this.errCell() },
  ]);

  /** selection (number[]) → khóa chọn của grid. */
  protected readonly selKeys = computed<unknown[]>(() => this.st.selection());
  protected onSel(keys: unknown[]): void {
    this.st.selection.set(keys.map((k) => Number(k)));
  }

  // ── Helpers (cell template context là Record — cast nội bộ) ──
  protected hasEmailErr(r: Record<string, unknown>): boolean {
    const errs = (r['errors'] as string[] | undefined) ?? [];
    return errs.some((e) => e.toLowerCase().includes('email'));
  }
  protected hasDeptErr(r: Record<string, unknown>): boolean {
    const errs = (r['errors'] as string[] | undefined) ?? [];
    return errs.some((e) => e.toLowerCase().includes('phòng ban'));
  }
  protected deptValid(r: Record<string, unknown>): boolean {
    return VALID_DEPTS.includes(String(r['dept'] ?? ''));
  }
  protected fmtN(n: number): string { return n.toLocaleString('en-US'); }
  /** Demo no-op (nút preview phụ). */
  protected noop(): void { /* demo no-op */ }

  // ── Actions ──
  /** Chip đếm-kiêm-lọc: label + count (đếm mức file lớn từ st.issues / BIG) + tone chấm màu.
   *  Chế độ Import theo mẫu: ẨN chip Trùng + AI đề xuất (thuộc giá trị AI Scan). */
  protected readonly chips = computed<{ key: 'all' | 'valid' | 'email' | 'dept' | 'empcode' | 'date' | 'dup' | 'ai'; label: string; count: string; tone: 'none' | 'ok' | 'err' | 'warn' | 'ai' }[]>(() => {
    const n = (id: string) => this.fmtN(this.st.issues.find((i) => i.id === id)?.count ?? 0);
    const base: { key: 'all' | 'valid' | 'email' | 'dept' | 'empcode' | 'date' | 'dup' | 'ai'; label: string; count: string; tone: 'none' | 'ok' | 'err' | 'warn' | 'ai' }[] = [
      { key: 'all', label: 'Tất cả', count: this.st.BIG.rows, tone: 'none' },
      { key: 'valid', label: 'Hợp lệ', count: this.st.BIG.valid, tone: 'ok' },
      { key: 'email', label: 'Email', count: n('email'), tone: 'err' },
      { key: 'dept', label: 'Phòng ban', count: n('dept'), tone: 'warn' },
      { key: 'empcode', label: 'Mã NV', count: n('empcode'), tone: 'warn' },
      { key: 'date', label: 'Ngày', count: n('date'), tone: 'warn' },
    ];
    if (this.st.mode() === 'ai') {
      base.push({ key: 'dup', label: 'Trùng', count: n('dup'), tone: 'warn' });
      base.push({ key: 'ai', label: 'AI đề xuất', count: '3,722', tone: 'ai' });
    }
    return base;
  });
  /** Chip Trùng KHÔNG lọc bảng (dòng trùng xử lý theo cặp) — mở thẳng mục trong dải AI. */
  protected chipClick(key: 'all' | 'valid' | 'email' | 'dept' | 'empcode' | 'date' | 'dup' | 'ai'): void {
    this.st.filterTab.set(key);
    if (key === 'dup') { this.aiOpen.set(true); this.dupOpen.set(true); }
  }
  /** Số nhóm đề xuất AI còn chờ xử lý (đếm trên tiêu đề dải). */
  protected readonly aiPending = computed(() =>
    (this.st.smartFixApplied() ? 0 : 1) + (this.st.autoFixApplied() ? 0 : 1) + (this.dupPending() > 0 ? 1 : 0));
  /** Số cặp trùng chưa quyết định. */
  protected readonly dupPending = computed(() => this.st.dups().filter((d) => !d.resolved).length);
  /** Bấm "Sửa" trên dòng → ép mở editor inline (email + phòng ban) của dòng đó. */
  protected edit(r: Record<string, unknown>): void { this.editId.set(Number(r['id'])); }
  /** Sửa email inline — gõ tới đâu fixRow re-validate tới đó (store cập nhật state/errors). */
  protected onEmail(r: Record<string, unknown>, e: Event): void {
    this.st.fixRow(Number(r['id']), { email: (e.target as HTMLInputElement).value });
  }
  /** Sửa phòng ban inline qua select. */
  protected onDept(r: Record<string, unknown>, v: unknown): void {
    if (v == null) return;
    this.st.fixRow(Number(r['id']), { dept: String(v) });
  }
  /** Bulk "AI sửa đề xuất": với mỗi dòng chọn CÓ aiSuggest → áp bản sửa suy từ gợi ý qua fixRow
   *  (dept sai → 'Sales Department', phone 10 số dính → format, ngày dd/MM/yyyy → yyyy-MM-dd). */
  protected aiFixSelected(): void {
    const sel = new Set(this.st.selection());
    let applied = 0;
    for (const r of this.st.rows()) {
      if (!sel.has(r.id) || !r.aiSuggest) continue;
      const patch: Partial<ImpRow> = {};
      if (!VALID_DEPTS.includes(r.dept)) patch.dept = 'Sales Department';
      if (/^0\d{9}$/.test(r.phone)) patch.phone = r.phone.replace(/^(\d{4})(\d{3})(\d{3})$/, '$1 $2 $3');
      if (/^\d{2}\/\d{2}\/\d{4}$/.test(r.joined)) {
        const [d, m, y] = r.joined.split('/');
        patch.joined = `${y}-${m}-${d}`;
      }
      if (Object.keys(patch).length > 0) { this.st.fixRow(r.id, patch); applied++; }
    }
    // Chỉ bỏ chọn khi có dòng được sửa — 0 dòng áp được thì giữ selection để user thấy nút không có gì để làm.
    if (applied > 0) this.st.clearSelection();
  }
  /** Bulk "Sửa hàng loạt": áp phòng ban đã chọn cho các dòng chọn (store re-validate + clear chọn). */
  protected applyBulk(): void {
    this.st.bulkFix(this.bulkDept());
    this.bulkOpen.set(false);
  }
}
